import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY || "";

export async function analyzeSurgicalImage(base64Image: string, prompt: string) {
  if (!API_KEY) return "AI tagging unavailable: No API Key configured.";

  try {
    const ai = new GoogleGenAI({ apiKey: API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: 'image/jpeg', data: base64Image } },
          { text: prompt || "Analyze this surgical image. Identify the anatomical structures and surgical stage (pre-op, intra-op, post-op)." }
        ]
      }
    });

    return response.text;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Error analyzing image.";
  }
}

