import { LogIn, ShieldAlert } from 'lucide-react';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);

  // Simple mock login handler
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoggedIn(true);
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full bg-white rounded-3xl shadow-xl shadow-slate-200 p-10 border border-slate-100">
          <div className="text-center mb-10">
            <div className="w-16 h-16 bg-teal-500 text-white rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg shadow-teal-100">
              <ShieldAlert size={32} />
            </div>
            <h1 className="text-3xl font-bold text-slate-900">SurgeLog</h1>
            <p className="text-slate-500 mt-2">Surgical Research & Media Management</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Surgeon/Fellow ID</label>
              <input 
                type="text" 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-teal-500 transition-all"
                placeholder="Enter your unique ID"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Passcode</label>
              <input 
                type="password" 
                className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-teal-500 transition-all"
                placeholder="••••••••"
                required
              />
            </div>
            <button 
              type="submit"
              className="w-full bg-teal-600 text-white font-bold py-4 rounded-xl hover:bg-teal-700 transition-all flex items-center justify-center gap-2 shadow-lg shadow-teal-100"
            >
              <LogIn size={20} />
              Secure Login
            </button>
          </form>

          <p className="mt-8 text-center text-xs text-slate-400 leading-relaxed">
            By logging in, you agree to maintain patient confidentiality and follow HIPAA / GDPR standards for clinical photography.
          </p>
        </div>
      </div>
    );
  }

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
        />
      );
    }

    switch (activeView) {
      case 'dashboard':
        return <Dashboard />;
      case 'patients':
        return <PatientList onSelectPatient={(p) => setSelectedPatient(p)} />;
      case 'research':
        return (
          <div className="py-20 text-center">
            <h2 className="text-2xl font-bold text-slate-800">Research & Study Groups</h2>
            <p className="text-slate-500 mt-2">This feature is used for bulk exporting and metadata analysis.</p>
            <div className="mt-10 grid grid-cols-1 md:grid-cols-2 gap-6 text-left max-w-4xl mx-auto">
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-lg mb-2">Study Group Logic</h3>
                <p className="text-sm text-slate-600">
                  Tagging a patient with a Study Group ID (e.g. <strong>"NERVE_2025"</strong>) 
                  automatically indexes all their media for rapid retrieval during journal manuscript preparation.
                </p>
              </div>
              <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
                <h3 className="font-bold text-lg mb-2">High-Res Retrieval</h3>
                <p className="text-sm text-slate-600">
                  Search by Group ID to download all Pre-op and Post-op functional outcome videos in one click, 
                  preserving original microvascular detail.
                </p>
              </div>
            </div>
          </div>
        );
      default:
        return <Dashboard />;
    }
  };

  return (
    <div className="flex min-h-screen">
      <Sidebar 
        activeView={activeView} 
        setActiveView={(v) => {
          setActiveView(v);
          setSelectedPatient(null);
        }} 
        onLogout={() => setIsLoggedIn(false)}
      />
      <main className="flex-1 ml-64 p-10 max-w-7xl mx-auto w-full">
        {renderView()}
      </main>
    </div>
  );
};

export default App;

