export default Sidebar;

import React, { useState } from 'react';
import { Search, Plus, Filter, User, Calendar, Microscope, X } from 'lucide-react';
import { Patient, StudyGroup } from '../types';
import { MOCK_STUDY_GROUPS } from '../constants';

interface DashboardProps {
  patients: Patient[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '',
    firstName: '',
    lastName: '',
    dateOfBirth: '',
    diagnosis: '',
    primarySurgeon: 'Dr. Smith',
    studyGroupIds: []
  });

  const filteredPatients = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.lastName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (p.dateOfSurgery && p.dateOfSurgery.includes(searchTerm))
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const patientToAdd: Patient = {
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0]
    };
    onAddPatient(patientToAdd);
    setShowModal(false);
    setNewPatient({
      uhid: '',
      firstName: '',
      lastName: '',
      dateOfBirth: '',
      diagnosis: '',
      primarySurgeon: 'Dr. Smith',
      studyGroupIds: []
    });
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl lg:text-3xl font-bold text-slate-900">Dashboard</h1>
          <p className="text-slate-500 text-sm">Manage patients and surgical records.</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="w-full md:w-auto flex items-center justify-center gap-2 bg-teal-600 text-white px-6 py-2.5 rounded-xl hover:bg-teal-700 transition-colors shadow-lg shadow-teal-100"
        >
          <Plus size={20} />
          New Patient Entry
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row gap-4 items-center">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text"
            placeholder="Search UHID, name, or surgery date..."
            className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-teal-500 transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button className="w-full md:w-auto px-6 py-3 border border-slate-200 bg-white rounded-xl text-slate-600 hover:bg-slate-50 flex items-center justify-center gap-2">
          <Filter size={20} />
          Advanced Filter
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredPatients.length > 0 ? (
          filteredPatients.map(p => (
            <div 
              key={p.uhid}
              onClick={() => onSelectPatient(p)}
              className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all cursor-pointer group"
            >
              <div className="flex justify-between items-start mb-4">
                <div className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-500 group-hover:bg-teal-50 group-hover:text-teal-600 transition-colors">
                  <User size={20} />
                </div>
                <span className="bg-slate-100 px-2 py-0.5 rounded font-mono font-bold text-[10px] text-slate-500">
                  {p.uhid}
                </span>
              </div>
              <h3 className="font-bold text-slate-900 text-lg leading-tight mb-1">{p.lastName}, {p.firstName}</h3>
              <p className="text-slate-500 text-xs mb-3 flex items-center gap-1">
                <Calendar size={12} />
                DOB: {p.dateOfBirth}
              </p>
              <p className="text-slate-600 text-sm line-clamp-2 min-h-[40px] mb-4">{p.diagnosis}</p>

              <div className="pt-4 border-t border-slate-50 flex justify-between items-center">
                <div className="flex gap-1 overflow-hidden">
                  {p.studyGroupIds.map(gid => (
                    <span key={gid} className="bg-teal-50 text-teal-700 text-[9px] px-2 py-0.5 rounded-full border border-teal-100 font-bold uppercase tracking-tighter">
                      {gid}
                    </span>
                  ))}
                </div>
                {p.dateOfSurgery && (
                  <span className="text-[10px] font-bold text-orange-600 bg-orange-50 px-2 py-0.5 rounded border border-orange-100 uppercase">
                    Surg: {p.dateOfSurgery}
                  </span>
                )}
              </div>
            </div>
          ))
        ) : (
          <div className="col-span-full py-20 text-center bg-white rounded-3xl border border-slate-100">
            <div className="inline-block p-4 bg-slate-50 rounded-full text-slate-300 mb-4">
              <Search size={48} />
            </div>
            <h3 className="text-xl font-bold text-slate-700">No matching patients</h3>
            <p className="text-slate-500">Try a different UHID or refine your search.</p>
          </div>
        )}
      </div>

      {/* New Patient Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-3xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-8 py-6 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <h2 className="text-xl font-bold text-slate-900">New Patient Entry</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-600">
                <X size={24} />
              </button>
            </div>
            <form onSubmit={handleSubmit} className="p-8 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2 md:col-span-1">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-1.5">Hospital ID (UHID)</label>
                  <input required value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} type="text" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none" placeholder="HOSP-XXXXX" />
                </div>
                <div className="col-span-2 md:col-span-1">
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-1.5">Date of Birth</label>
                  <input required value={newPatient.dateOfBirth} onChange={e => setNewPatient({...newPatient, dateOfBirth: e.target.value})} type="date" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-1.5">First Name</label>
                  <input required value={newPatient.firstName} onChange={e => setNewPatient({...newPatient, firstName: e.target.value})} type="text" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-1.5">Last Name</label>
                  <input required value={newPatient.lastName} onChange={e => setNewPatient({...newPatient, lastName: e.target.value})} type="text" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none" />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-1.5">Diagnosis</label>
                <textarea required value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none h-24 resize-none" placeholder="Describe clinical condition..."></textarea>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-1.5">Surgery Date (Optional)</label>
                <input value={newPatient.dateOfSurgery} onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} type="date" className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none" />
              </div>
              <button type="submit" className="w-full bg-teal-600 text-white font-bold py-3.5 rounded-xl hover:bg-teal-700 transition-all shadow-lg shadow-teal-100">
                Register Patient Record
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Upload, Camera, Database, ChevronRight, UserCircle, Tag, CheckCircle2 } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, MediaType, StudyGroup } from '../types';
import { MOCK_STUDY_GROUPS } from '../constants';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload }) => {
  const [step, setStep] = useState(1);
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [storage, setStorage] = useState<StorageLocation>(StorageLocation.LOCAL);
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryDate, setSurgeryDate] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [isUploading, setIsUploading] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsUploading(true);
    // Simulate upload
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId,
        stage,
        surgeryDate: (stage !== SurgicalStage.PRE_OP) ? surgeryDate : null,
        storage,
        studyGroup: selectedGroup,
        tags: customTags.split(',').map(t => t.trim()),
        timestamp: new Date().toISOString()
      });
      setIsUploading(false);
      setStep(4); // Success step
    }, 1500);
  };

  return (
    <div className="max-w-2xl mx-auto py-8">
      <div className="mb-10 text-center">
        <h1 className="text-3xl font-bold text-slate-900">Upload Media</h1>
        <p className="text-slate-500 mt-2">Associate high-resolution media with patient records.</p>

        {/* Progress Bar */}
        <div className="flex justify-between items-center mt-8 max-w-sm mx-auto relative">
          <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-200 -translate-y-1/2 z-0"></div>
          <div className="absolute top-1/2 left-0 h-0.5 bg-teal-500 -translate-y-1/2 z-0 transition-all duration-300" style={{ width: `${(step - 1) * 50}%` }}></div>
          {[1, 2, 3].map(i => (
            <div key={i} className={`w-8 h-8 rounded-full z-10 flex items-center justify-center font-bold text-sm transition-all duration-300 ${
              step >= i ? 'bg-teal-500 text-white shadow-lg shadow-teal-100' : 'bg-slate-200 text-slate-400'
            }`}>
              {i}
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-xl overflow-hidden p-8">
        {step === 1 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-xl font-bold flex items-center gap-2">
              <Database size={24} className="text-teal-500" />
              1. Setup Storage & Target
            </h2>

            <div className="space-y-4">
              <label className="block text-sm font-bold text-slate-700">Storage Destination</label>
              <div className="grid grid-cols-3 gap-3">
                {Object.values(StorageLocation).map(loc => (
                  <button
                    key={loc}
                    onClick={() => setStorage(loc)}
                    className={`p-4 rounded-xl border-2 text-center transition-all ${
                      storage === loc ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-100 text-slate-500 hover:border-slate-200'
                    }`}
                  >
                    <div className="text-xs">{loc}</div>
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-4">
              <label className="block text-sm font-bold text-slate-700">Select Patient (UHID)</label>
              <select 
                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-teal-500 appearance-none"
                value={selectedPatientId}
                onChange={e => setSelectedPatientId(e.target.value)}
              >
                <option value="">Choose a patient...</option>
                {patients.map(p => (
                  <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>
                ))}
              </select>
            </div>

            <button 
              disabled={!selectedPatientId}
              onClick={() => setStep(2)}
              className="w-full bg-slate-900 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 hover:bg-slate-800 transition-all disabled:opacity-50"
            >
              Continue
              <ChevronRight size={20} />
            </button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-xl font-bold flex items-center gap-2">
              <Tag size={24} className="text-teal-500" />
              2. Surgical Context
            </h2>

            <div className="space-y-4">
              <label className="block text-sm font-bold text-slate-700">Surgical Stage</label>
              <div className="flex flex-col gap-2">
                {Object.values(SurgicalStage).map(s => (
                  <button
                    key={s}
                    onClick={() => setStage(s)}
                    className={`p-4 rounded-xl border-2 flex justify-between items-center transition-all ${
                      stage === s ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-100 text-slate-500 hover:border-slate-200'
                    }`}
                  >
                    <span>{s}</span>
                    {stage === s && <CheckCircle2 size={18} />}
                  </button>
                ))}
              </div>
            </div>

            {(stage === SurgicalStage.INTRA_OP || stage === SurgicalStage.POST_OP) && (
              <div className="space-y-4 animate-in slide-in-from-top-2">
                <label className="block text-sm font-bold text-slate-700">Date of Surgery</label>
                <input 
                  type="date" 
                  required
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-teal-500"
                  value={surgeryDate}
                  onChange={e => setSurgeryDate(e.target.value)}
                />
              </div>
            )}

            <div className="space-y-4">
              <label className="block text-sm font-bold text-slate-700">Assign to Study Group (Optional)</label>
              <select 
                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-teal-500"
                value={selectedGroup}
                onChange={e => setSelectedGroup(e.target.value)}
              >
                <option value="">None</option>
                {MOCK_STUDY_GROUPS.map(g => (
                  <option key={g.id} value={g.id}>{g.name}</option>
                ))}
              </select>
            </div>

            <div className="flex gap-4">
              <button 
                onClick={() => setStep(1)}
                className="flex-1 border border-slate-200 text-slate-600 font-bold py-4 rounded-xl hover:bg-slate-50 transition-all"
              >
                Back
              </button>
              <button 
                onClick={() => setStep(3)}
                className="flex-1 bg-slate-900 text-white font-bold py-4 rounded-xl hover:bg-slate-800 transition-all"
              >
                Next Step
              </button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
            <h2 className="text-xl font-bold flex items-center gap-2">
              <Upload size={24} className="text-teal-500" />
              3. Select Files & Upload
            </h2>

            <div className="p-10 border-2 border-dashed border-slate-200 rounded-3xl flex flex-col items-center justify-center text-center bg-slate-50">
              <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center text-slate-400 shadow-sm mb-4">
                <Camera size={32} />
              </div>
              <h3 className="font-bold text-slate-700">Tap to Capture or Upload</h3>
              <p className="text-slate-500 text-sm mt-1">High-quality photos or videos</p>
              <input type="file" multiple className="hidden" id="file-upload" />
              <label htmlFor="file-upload" className="mt-6 px-6 py-2 bg-white border border-slate-200 rounded-xl text-slate-700 font-bold cursor-pointer hover:bg-slate-50 shadow-sm">
                Browse Gallery
              </label>
            </div>

            <div className="space-y-4">
              <label className="block text-sm font-bold text-slate-700">Custom Tags (comma separated)</label>
              <input 
                type="text"
                placeholder="e.g. complication, successful, tendon repair"
                className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl outline-none focus:ring-2 focus:ring-teal-500"
                value={customTags}
                onChange={e => setCustomTags(e.target.value)}
              />
            </div>

            <button 
              onClick={handleSubmit}
              disabled={isUploading}
              className={`w-full bg-teal-600 text-white font-bold py-4 rounded-xl flex items-center justify-center gap-2 shadow-lg shadow-teal-100 transition-all ${isUploading ? 'opacity-70 cursor-not-allowed' : 'hover:bg-teal-700'}`}
            >
              {isUploading ? (
                <>
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  Uploading to {storage}...
                </>
              ) : (
                <>
                  <CheckCircle2 size={20} />
                  Start Secure Upload
                </>
              )}
            </button>
          </div>
        )}

        {step === 4 && (
          <div className="py-10 text-center space-y-6 animate-in zoom-in-95 duration-300">
            <div className="w-20 h-20 bg-teal-100 text-teal-600 rounded-full flex items-center justify-center mx-auto shadow-inner">
              <CheckCircle2 size={40} />
            </div>
            <div>
              <h2 className="text-2xl font-bold text-slate-900">Upload Successful</h2>
              <p className="text-slate-500 mt-2">Media has been encrypted and stored in {storage}.</p>
            </div>
            <button 
              onClick={() => setStep(1)}
              className="w-full bg-teal-600 text-white font-bold py-4 rounded-xl hover:bg-teal-700 transition-all"
            >
              Upload More Media
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default UploadMedia;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { Patient, MediaEntry } from './types';
import { LogIn, ShieldAlert, Menu } from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [media, setMedia] = useState<MediaEntry[]>(MOCK_MEDIA);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
  };

  const handleUploadComplete = (uploadData: any) => {
    // In a real app, we'd update the media state here
    console.log("Uploaded Media Info:", uploadData);
    // Automatically add study group if selected
    if (uploadData.studyGroup) {
      setPatients(prev => prev.map(p => 
        p.uhid === uploadData.uhid && !p.studyGroupIds.includes(uploadData.studyGroup)
          ? { ...p, studyGroupIds: [...p.studyGroupIds, uploadData.studyGroup] }
          : p
      ));
    }
    // Set surgery date on patient if not set
    if (uploadData.surgeryDate) {
      setPatients(prev => prev.map(p => 
        p.uhid === uploadData.uhid ? { ...p, dateOfSurgery: uploadData.surgeryDate } : p
      ));
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full bg-white rounded-3xl shadow-xl shadow-slate-200 p-10 border border-slate-100">
          <div className="text-center mb-10">
            <div className="w-16 h-16 bg-teal-500 text-white rounded-2xl flex items-center justify-center mx-auto mb-6 shadow-lg shadow-teal-100">
              <ShieldAlert size={32} />
            </div>
            <h1 className="text-3xl font-bold text-slate-900">SurgeLog</h1>
            <p className="text-slate-500 mt-2">Surgical Research & Media Management</p>
          </div>

          <form onSubmit={(e) => { e.preventDefault(); setIsLoggedIn(true); }} className="space-y-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Surgeon/Fellow ID</label>
              <input type="text" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none" placeholder="Enter your ID" required />
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Passcode</label>
              <input type="password" placeholder="••••••••" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-teal-500 outline-none" required />
            </div>
            <button type="submit" className="w-full bg-teal-600 text-white font-bold py-4 rounded-xl hover:bg-teal-700 transition-all shadow-lg shadow-teal-100">Secure Login</button>
          </form>
          <p className="mt-8 text-center text-[10px] text-slate-400 leading-relaxed uppercase tracking-widest font-bold">Confidential Medical Data System</p>
        </div>
      </div>
    );
  }

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
        />
      );
    }

    switch (activeView) {
      case 'dashboard':
        return <Dashboard 
          patients={patients} 
          onAddPatient={handleAddPatient}
          onSelectPatient={(p) => setSelectedPatient(p)}
        />;
      case 'upload':
        return <UploadMedia patients={patients} onUpload={handleUploadComplete} />;
      case 'research':
        return (
          <div className="py-20 text-center animate-in fade-in slide-in-from-bottom-4">
            <h2 className="text-3xl font-bold text-slate-900">Study Groups</h2>
            <p className="text-slate-500 mt-2">Managing {MOCK_STUDY_GROUPS.length} clinical research clusters.</p>
            <div className="mt-12 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 max-w-5xl mx-auto text-left">
              {MOCK_STUDY_GROUPS.map(group => (
                <div key={group.id} className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm hover:shadow-md transition-all">
                  <div className="w-12 h-12 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center mb-4">
                    <Library size={24} />
                  </div>
