import { GoogleGenAI } from "@google/genai";

// Analyze surgical images using the Gemini API.
export async function analyzeSurgicalImage(base64Image: string, prompt: string) {
  try {
    // GUIDELINE: Always initialize GoogleGenAI using the process.env.API_KEY directly.
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // GUIDELINE: Use the recommended gemini-3-flash-preview model for basic multimodal tasks.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Image
            }
          },
          {
            text: prompt || "Analyze this surgical image. Identify the anatomical structures and surgical stage (pre-op, intra-op, post-op)."
          }
        ]
      }
    });

    // GUIDELINE: Access generated text via the .text property directly.
    return response.text;
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return "Error analyzing image.";
  }
}

