import React, { useState } from 'react';
import { Upload, Camera, Database, ChevronRight, Tag, CheckCircle2, Image as ImageIcon, X } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, MediaEntry } from '../types';
import { MOCK_STUDY_GROUPS } from '../constants';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload }) => {
  const [step, setStep] = useState(1);
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [storage, setStorage] = useState<StorageLocation>(StorageLocation.LOCAL);
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryDate, setSurgeryDate] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<string[]>([]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const urls = Array.from(e.target.files).map(f => URL.createObjectURL(f));
      setPreviewFiles(prev => [...prev, ...urls]);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId,
        stage,
        surgeryDate: (stage !== SurgicalStage.PRE_OP) ? surgeryDate : null,
        storage,
        studyGroup: selectedGroup,
        tags: customTags.split(',').map(t => t.trim()),
        timestamp: new Date().toISOString()
      });
      setIsUploading(false);
      setStep(4);
    }, 1200);
  };

  return (
    <div className="max-w-2xl mx-auto py-6">
      <div className="mb-8 text-center">
        <h1 className="text-2xl md:text-3xl font-bold text-slate-900">Upload Media</h1>
        <p className="text-slate-500 mt-1 text-sm">Clinical media for hand and microvascular research.</p>

        <div className="flex justify-between items-center mt-6 max-w-xs mx-auto relative">
          <div className="absolute top-1/2 left-0 w-full h-0.5 bg-slate-200 -translate-y-1/2 z-0"></div>
          <div className="absolute top-1/2 left-0 h-0.5 bg-teal-500 -translate-y-1/2 z-0 transition-all duration-300" style={{ width: `${(step - 1) * 50}%` }}></div>
          {[1, 2, 3].map(i => (
            <div key={i} className={`w-7 h-7 rounded-full z-10 flex items-center justify-center font-bold text-xs transition-all duration-300 ${
              step >= i ? 'bg-teal-500 text-white' : 'bg-slate-200 text-slate-400'
            }`}>
              {i}
            </div>
          ))}
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-xl p-6 md:p-8">
        {step === 1 && (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            <h2 className="text-lg font-bold flex items-center gap-2"><Database size={20} className="text-teal-500" /> 1. Storage & Patient</h2>
            <div className="space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase">Select Storage Location</label>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                {Object.values(StorageLocation).map(loc => (
                  <button key={loc} onClick={() => setStorage(loc)} className={`p-3 rounded-xl border-2 text-sm transition-all ${storage === loc ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 text-slate-500 hover:border-slate-200'}`}>{loc}</button>
                ))}
              </div>
            </div>
            <div className="space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase">Target Patient (UHID)</label>
              <select className="w-full p-3.5 bg-slate-50 border border-slate-200 rounded-xl" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)}>
                <option value="">Search patient...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
              </select>
            </div>
            <button disabled={!selectedPatientId} onClick={() => setStep(2)} className="w-full bg-slate-900 text-white font-bold py-3.5 rounded-xl disabled:opacity-50">Continue</button>
          </div>
        )}

        {step === 2 && (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            <h2 className="text-lg font-bold flex items-center gap-2"><Tag size={20} className="text-teal-500" /> 2. Surgical Context</h2>
            <div className="space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase">Surgical Stage</label>
              <div className="grid grid-cols-1 gap-2">
                {Object.values(SurgicalStage).map(s => (
                  <button key={s} onClick={() => setStage(s)} className={`p-4 rounded-xl border-2 flex justify-between items-center ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 text-slate-500'}`}>
                    {s} {stage === s && <CheckCircle2 size={16} />}
                  </button>
                ))}
              </div>
            </div>
            {(stage === SurgicalStage.INTRA_OP || stage === SurgicalStage.POST_OP) && (
              <div className="animate-in slide-in-from-top-2">
                <label className="text-xs font-bold text-slate-500 uppercase block mb-1">Date of Surgery</label>
                <input type="date" required className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl" value={surgeryDate} onChange={e => setSurgeryDate(e.target.value)} />
              </div>
            )}
            <div className="space-y-3">
              <label className="text-xs font-bold text-slate-500 uppercase">Study Group Tag (Optional)</label>
              <select className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl" value={selectedGroup} onChange={e => setSelectedGroup(e.target.value)}>
                <option value="">None</option>
                {MOCK_STUDY_GROUPS.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
              </select>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setStep(1)} className="flex-1 border border-slate-200 py-3 rounded-xl font-bold">Back</button>
              <button onClick={() => setStep(3)} className="flex-1 bg-slate-900 text-white py-3 rounded-xl font-bold">Files Selection</button>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="space-y-6 animate-in slide-in-from-right-4 duration-300">
            <h2 className="text-lg font-bold flex items-center gap-2"><Upload size={20} className="text-teal-500" /> 3. Media Upload</h2>
            <div className="p-8 border-2 border-dashed border-slate-200 rounded-2xl flex flex-col items-center justify-center bg-slate-50">
              <input type="file" multiple className="hidden" id="media-input" onChange={handleFileChange} />
              <label htmlFor="media-input" className="cursor-pointer flex flex-col items-center">
                <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center shadow-sm mb-3 text-slate-400"><Camera size={24} /></div>
                <p className="text-sm font-bold text-slate-700">Add Photos or Videos</p>
                <p className="text-xs text-slate-400 mt-1">High-def original quality preserved</p>
              </label>
            </div>
            {previewFiles.length > 0 && (
              <div className="grid grid-cols-4 md:grid-cols-5 gap-2">
                {previewFiles.map((url, i) => (
                  <div key={i} className="relative aspect-square rounded-lg overflow-hidden border">
                    <img src={url} className="w-full h-full object-cover" />
                    <button onClick={() => setPreviewFiles(p => p.filter((_, idx) => idx !== i))} className="absolute top-1 right-1 bg-black/50 text-white rounded-full p-0.5"><X size={10} /></button>
                  </div>
                ))}
              </div>
            )}
            <div className="space-y-2">
              <label className="text-xs font-bold text-slate-500 uppercase">Clinical Tags</label>
              <input type="text" placeholder="complication, successful outcome, nerve repair..." className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl" value={customTags} onChange={e => setCustomTags(e.target.value)} />
            </div>
            <button onClick={handleSubmit} disabled={isUploading || previewFiles.length === 0} className="w-full bg-teal-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-teal-100 flex items-center justify-center gap-2">
              {isUploading ? "Uploading Securely..." : "Start Secure Upload"}
            </button>
          </div>
        )}

        {step === 4 && (
          <div className="py-8 text-center space-y-4 animate-in zoom-in-95 duration-300">
            <div className="w-16 h-16 bg-teal-100 text-teal-600 rounded-full flex items-center justify-center mx-auto"><CheckCircle2 size={32} /></div>
            <h2 className="text-2xl font-bold">Securely Stored</h2>
            <p className="text-slate-500 text-sm">Media uploaded to {storage} for patient {selectedPatientId}.</p>
            <button onClick={() => { setStep(1); setPreviewFiles([]); }} className="w-full bg-teal-600 text-white font-bold py-3.5 rounded-xl">Upload More</button>
          </div>
        )}
      </div>
    </div>
  );
};

export default UploadMedia;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { Patient, MediaEntry, StudyGroup } from './types';
import { LogIn, ShieldAlert, Menu, Library, Camera, Plus, FileSpreadsheet, Download } from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);

  const handleAddPatient = (newPatient: Patient) => setPatients(prev => [newPatient, ...prev]);
  const handleUpdatePatient = (updated: Patient) => setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));

  const handleAddStudy = () => {
    const name = prompt("Enter Study Group Name:");
    if (name) {
      const newGroup: StudyGroup = {
        id: `sg${studyGroups.length + 1}`,
        name,
        description: 'New clinical study group.',
        patientCount: 0
      };
      setStudyGroups([...studyGroups, newGroup]);
    }
  };

  const handleExportToSheets = () => {
    alert("Exporting study group metadata to Google Sheets... (This would trigger an OAuth flow to Google Drive/Sheets API in a production environment)");
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
        />
      );
    }

    switch (activeView) {
      case 'dashboard':
        return <Dashboard 
          patients={patients} 
          onAddPatient={handleAddPatient}
          onSelectPatient={(p) => setSelectedPatient(p)}
        />;
      case 'upload':
        return <UploadMedia patients={patients} onUpload={(d) => console.log("Upload:", d)} />;
      case 'research':
        return (
          <div className="py-10">
            <div className="flex justify-between items-center mb-10">
              <div>
                <h2 className="text-3xl font-bold text-slate-900">Study Groups</h2>
                <p className="text-slate-500 mt-1">Cross-patient analysis and export.</p>
              </div>
              <div className="flex gap-3">
                <button onClick={handleExportToSheets} className="flex items-center gap-2 border border-slate-200 bg-white px-4 py-2 rounded-xl text-sm font-bold text-slate-700">
                  <FileSpreadsheet size={18} /> Export to Sheets
                </button>
                <button onClick={handleAddStudy} className="flex items-center gap-2 bg-teal-600 text-white px-4 py-2 rounded-xl text-sm font-bold shadow-lg shadow-teal-100">
                  <Plus size={18} /> New Study
                </button>
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {studyGroups.map(group => (
                <div key={group.id} className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
                  <div className="w-12 h-12 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center mb-4"><Library size={24} /></div>
                  <h3 className="font-bold text-slate-900 text-lg">{group.name}</h3>
                  <p className="text-slate-500 text-sm mt-1 mb-6">{group.description}</p>
                  <div className="flex justify-between items-center pt-4 border-t border-slate-50">
                    <span className="text-teal-700 font-bold text-xs bg-teal-50 px-3 py-1 rounded-full uppercase">
                      {patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled
                    </span>
                    <button className="text-slate-400 hover:text-slate-900 font-bold text-xs uppercase">Download Data</button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      default:
        return <Dashboard patients={patients} onAddPatient={handleAddPatient} onSelectPatient={(p) => setSelectedPatient(p)} />;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6">
        <div className="max-w-md w-full bg-white rounded-3xl shadow-xl p-10 border border-slate-100">
          <div className="text-center mb-10">
            <div className="w-16 h-16 bg-teal-500 text-white rounded-2xl flex items-center justify-center mx-auto mb-6"><ShieldAlert size={32} /></div>
            <h1 className="text-3xl font-bold text-slate-900">SurgeLog</h1>
            <p className="text-slate-500 mt-2">Clinical Research & Media Management</p>
          </div>
          <form onSubmit={(e) => { e.preventDefault(); setIsLoggedIn(true); }} className="space-y-6">
            <input type="text" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none" placeholder="Surgeon ID" required />
            <input type="password" placeholder="Passcode" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none" required />
            <button type="submit" className="w-full bg-teal-600 text-white font-bold py-4 rounded-xl shadow-lg shadow-teal-100">Access System</button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 overflow-x-hidden">
      <Sidebar activeView={activeView} setActiveView={(v) => { setActiveView(v); setSelectedPatient(null); }} onLogout={() => setIsLoggedIn(false)} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="lg:hidden flex items-center justify-between p-4 bg-white border-b border-slate-200 sticky top-0 z-[100]">
          <div className="flex items-center gap-2"><div className="p-1.5 bg-teal-500 rounded-lg text-white"><Camera size={18} /></div><span className="font-bold">SurgeLog</span></div>
          <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-600"><Menu size={24} /></button>
        </div>
        <div className="p-4 md:p-10 max-w-7xl mx-auto w-full">{renderView()}</div>
      </main>
    </div>
  );
};

export default App;

