                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Primary Surgery Date</label>
                  <input value={newPatient.dateOfSurgery} onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} type="date" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-teal-500 transition-all font-medium" />
                </div>
              </div>

              <div className="flex items-center gap-3 p-4 bg-teal-50 rounded-2xl text-teal-700 text-xs font-medium">
                <AlertCircle size={16} />
                UHID and First Name are required for storage indexing.
