              <button type="submit" className="w-full bg-teal-600 text-white font-bold py-4 rounded-2xl hover:bg-teal-700 transition-all shadow-xl shadow-teal-500/20 text-lg">
                Create Patient Entry
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

