import React, { useState } from 'react';
import { ArrowLeft, Plus, Download, Tag, Calendar, User, Microscope, X, Edit, Save, Trash2 } from 'lucide-react';
import { Patient, SurgicalStage, MediaEntry, StudyGroup } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onDeletePatient?: (uhid: string) => void;
  studyGroups: StudyGroup[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient, studyGroups }) => {
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showTagModal, setShowTagModal] = useState(false);
  const [showStudyModal, setShowStudyModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editPatient, setEditPatient] = useState<Patient>({ ...patient });

  // Media local state for the patient
  const [patientMediaEntries, setPatientMediaEntries] = useState<MediaEntry[]>(
    MOCK_MEDIA.filter(m => m.uhid === patient.uhid)
  );

  // Sorting logic for Post-op: Arrange by time since surgery
  const sortedFilteredMedia = [...patientMediaEntries]
    .filter(m => m.stage === activeStage)
    .sort((a, b) => {
      if (activeStage === SurgicalStage.POST_OP && patient.dateOfSurgery) {
        return new Date(a.uploadedAt).getTime() - new Date(b.uploadedAt).getTime();
      }
      return new Date(b.uploadedAt).getTime() - new Date(a.uploadedAt).getTime(); // Default newest first
    });

  const handleAddToStudy = (groupId: string) => {
    if (patient.studyGroupIds.includes(groupId)) return;
    const updated = { ...patient, studyGroupIds: [...patient.studyGroupIds, groupId] };
    onUpdatePatient(updated);
    setShowStudyModal(false);
  };

  const handleSaveEdit = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdatePatient(editPatient);
    setShowEditModal(false);
  };

  const handleDownload = (media: MediaEntry) => {
    // Simulating hi-def download
    const link = document.createElement('a');
    link.href = media.url;
    link.download = `OPUS_${patient.uhid}_${media.stage}_${media.id}.jpg`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleAddTag = (mediaId: string, newTag: string) => {
    if (!newTag.trim()) return;
    setPatientMediaEntries(prev => prev.map(m => 
      m.id === mediaId ? { ...m, tags: [...new Set([...m.tags, newTag.trim()])] } : m
    ));
  };

  const handleRemoveTag = (mediaId: string, tagToRemove: string) => {
    setPatientMediaEntries(prev => prev.map(m => 
      m.id === mediaId ? { ...m, tags: m.tags.filter(t => t !== tagToRemove) } : m
    ));
  };

  const calculatePostOpDay = (uploadedAt: string) => {
    if (!patient.dateOfSurgery) return null;
    const surg = new Date(patient.dateOfSurgery);
    const upload = new Date(uploadedAt);
    const diff = Math.floor((upload.getTime() - surg.getTime()) / (1000 * 60 * 60 * 24));
    return diff >= 0 ? `POD ${diff}` : `Pre-op ${Math.abs(diff)}d`;
  };

  return (
