import React, { useState, useRef } from 'react';
import { Upload, Camera, Database, Tag, CheckCircle2, X, Trash2, PlayCircle } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [storage, setStorage] = useState<StorageLocation>(StorageLocation.LOCAL);
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryDate, setSurgeryDate] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  const generateVideoThumbnail = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;
      video.src = URL.createObjectURL(file);

      video.onloadeddata = () => {
        video.currentTime = 1; // Capture at 1 second mark
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          resolve(canvas.toDataURL('image/jpeg'));
        } else {
          resolve('');
        }
        URL.revokeObjectURL(video.src);
      };

      video.onerror = () => {
        resolve('');
        URL.revokeObjectURL(video.src);
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const newPreviews: PreviewFile[] = [];

      for (const file of files) {
        const type = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);
        let thumbnailUrl = undefined;

        if (type === 'video') {
          thumbnailUrl = await generateVideoThumbnail(file);
        }

        newPreviews.push({ url, file, type, thumbnailUrl });
      }

      setPreviewFiles(prev => [...prev, ...newPreviews]);
    }
  };

  const removeFile = (index: number) => {
    const fileToRemove = previewFiles[index];
    URL.revokeObjectURL(fileToRemove.url);
    setPreviewFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) {
      alert("Please select a patient and add media.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId,
        stage,
        surgeryDate: (stage !== SurgicalStage.PRE_OP) ? surgeryDate : null,
        storage,
        studyGroup: selectedGroup,
        tags: customTags.split(',').map(t => t.trim()).filter(t => t !== ''),
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length
      });
      setIsUploading(false);
      setShowSuccess(true);
      previewFiles.forEach(f => URL.revokeObjectURL(f.url));
      setPreviewFiles([]);
      setCustomTags('');
      setSelectedPatientId('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xl mx-auto py-20 text-center space-y-8 animate-in zoom-in-95">
        <div className="w-24 h-24 bg-teal-100 text-teal-600 rounded-[2rem] flex items-center justify-center mx-auto shadow-xl shadow-teal-500/10">
          <CheckCircle2 size={48} />
        </div>
        <div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">Securely Uploaded</h2>
          <p className="text-slate-500 mt-2 font-medium">Original resolution preserved in {storage}.</p>
        </div>
        <button 
          onClick={() => setShowSuccess(false)}
          className="w-full bg-teal-600 text-white font-black py-4 rounded-2xl hover:bg-teal-700 transition-all shadow-xl shadow-teal-500/20 text-lg"
        >
          Return to Upload
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto py-4">
      <div className="mb-10 text-center lg:text-left">
        <h1 className="text-4xl font-black text-slate-900 tracking-tight">Media Portal</h1>
        <p className="text-slate-500 mt-2 font-medium">Capture and categorize clinical microvascular documentation.</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-1 space-y-6">
          <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 tracking-tight flex items-center gap-2">
              <Database size={20} className="text-teal-500" />
              1. Target Data
            </h2>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Storage System</label>
                <div className="grid grid-cols-1 gap-2">
                  {[StorageLocation.GOOGLE_DRIVE, StorageLocation.LOCAL].map(loc => (
                    <button
                      key={loc}
                      type="button"
                      onClick={() => setStorage(loc as StorageLocation)}
                      className={`px-4 py-3 rounded-xl border-2 text-sm font-bold transition-all text-left flex justify-between items-center ${
                        storage === loc ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-500 bg-slate-50'
                      }`}
                    >
                      {loc}
                      {storage === loc && <CheckCircle2 size={16} />}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Select Patient (UHID)</label>
                <select 
                  className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm"
                  value={selectedPatientId}
                  onChange={e => setSelectedPatientId(e.target.value)}
                  required
                >
                  <option value="">Choose patient...</option>
                  {patients.map(p => (
                    <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 tracking-tight flex items-center gap-2">
              <Tag size={20} className="text-teal-500" />
              2. Surgical Context
            </h2>

            <div className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Clinical Stage</label>
                <div className="space-y-2">
                  {Object.values(SurgicalStage).map(s => (
                    <button
                      key={s}
                      type="button"
                      onClick={() => setStage(s)}
                      className={`w-full px-4 py-3 rounded-xl border-2 text-sm font-bold transition-all text-left flex justify-between items-center ${
                        stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-500 bg-slate-50'
                      }`}
                    >
                      {s}
                      {stage === s && <CheckCircle2 size={16} />}
                    </button>
                  ))}
                </div>
              </div>

              {stage !== SurgicalStage.PRE_OP && (
                <div className="animate-in slide-in-from-top-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Date of Surgery</label>
                  <input 
                    type="date"
                    required
                    className="w-full px-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm"
                    value={surgeryDate}
                    onChange={e => setSurgeryDate(e.target.value)}
                  />
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-2 space-y-8">
          <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-8 h-full flex flex-col">
            <h2 className="text-xl font-black text-slate-900 tracking-tight flex items-center gap-2">
              <Upload size={24} className="text-teal-500" />
              3. Select High-Definition Media
            </h2>

            <div className="flex-1 space-y-8">
              <div className="group relative p-12 border-4 border-dashed border-slate-100 rounded-[2rem] bg-slate-50/50 hover:bg-white hover:border-teal-200 transition-all flex flex-col items-center justify-center text-center cursor-pointer">
                <input 
                  type="file" 
                  multiple 
                  accept="image/*,video/*"
                  className="absolute inset-0 opacity-0 cursor-pointer" 
                  onChange={handleFileChange}
                />
                <div className="p-6 bg-white rounded-[2rem] shadow-xl shadow-slate-200/50 text-slate-400 mb-6 group-hover:scale-110 group-hover:text-teal-500 transition-all">
                  <Camera size={48} />
                </div>
                <h3 className="text-xl font-black text-slate-900 tracking-tight">Tap or Drag to Capture</h3>
                <p className="text-slate-500 text-sm font-medium mt-2">Upload surgical photos or hi-res procedure videos.</p>
              </div>

              {previewFiles.length > 0 && (
                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-5 gap-4 animate-in fade-in slide-in-from-bottom-4">
                  {previewFiles.map((fileData, i) => (
                    <div key={i} className="group relative aspect-square rounded-2xl overflow-hidden border border-slate-200 shadow-sm bg-black">
                      {fileData.type === 'video' ? (
                        <div className="relative w-full h-full">
                          {fileData.thumbnailUrl ? (
                            <img src={fileData.thumbnailUrl} className="w-full h-full object-cover opacity-80" alt="Video thumbnail" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center bg-slate-900 text-slate-500">
                              <PlayCircle size={32} />
                            </div>
                          )}
                          <div className="absolute inset-0 flex items-center justify-center">
                            <PlayCircle size={24} className="text-white drop-shadow-lg" />
                          </div>
                        </div>
                      ) : (
                        <img src={fileData.url} className="w-full h-full object-cover" alt="Preview" />
                      )}
                      <button 
                        type="button"
                        onClick={() => removeFile(i)}
                        className="absolute top-2 right-2 p-1.5 bg-black/60 text-white rounded-lg opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500"
                      >
                        <Trash2 size={14} />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Custom Tags (Comma Sep.)</label>
                  <input 
                    type="text" 
                    placeholder="e.g. successful, MedianNerve,POD3"
                    className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm"
                    value={customTags}
                    onChange={e => setCustomTags(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Assign Research Group</label>
                  <select 
                    className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm"
                    value={selectedGroup}
                    onChange={e => setSelectedGroup(e.target.value)}
                  >
                    <option value="">Unassigned</option>
                    {studyGroups.map(g => (
                      <option key={g.id} value={g.id}>{g.name}</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId}
              className={`w-full font-black py-5 rounded-[2rem] flex items-center justify-center gap-3 shadow-2xl transition-all text-xl ${
                isUploading || previewFiles.length === 0 || !selectedPatientId
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed'
                : 'bg-teal-600 text-white hover:bg-teal-700 shadow-teal-500/20'
              }`}
            >
              {isUploading ? (
                <>
                  <div className="w-6 h-6 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                  Encrypting & Uploading...
                </>
              ) : (
                <>
                  <CheckCircle2 size={24} />
                  Initiate OPUS Secure Storage
                </>
              )}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

export enum SurgicalStage {
  PRE_OP = 'Pre-operative',
  INTRA_OP = 'Intra-operative',
  POST_OP = 'Post-operative'
}

export enum MediaType {
  IMAGE = 'image',
  VIDEO = 'video'
}

export enum StorageLocation {
  GOOGLE_DRIVE = 'Google Drive',
  LOCAL = 'Local Storage'
}

export interface StudyGroup {
  id: string;
  name: string;
  description: string;
  patientCount: number;
  driveFolderId?: string; // Simulated link to Google Drive folder
  lastSync?: string;
}

export interface MediaEntry {
  id: string;
  uhid: string;
  stage: SurgicalStage;
  type: MediaType;
  url: string;
  thumbnailUrl?: string;
  uploadedAt: string;
  notes?: string;
  tags: string[];
  storageLocation: StorageLocation;
}

export interface Patient {
  uhid: string; // Unique Hospital ID - Primary Key
  firstName: string;
  lastName: string;
  ageYears: number;
  ageMonths?: number;
  diagnosis: string;
  primarySurgeon: string;
  studyGroupIds: string[];
  createdAt: string;
  dateOfSurgery?: string;
}

export interface AuthUser {
  id: string;
  name: string;
  role: 'Surgeon' | 'Fellow' | 'Researcher';
  email: string;
}

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { Patient, MediaEntry, StudyGroup, StorageLocation } from './types';
import { 
  LogIn, ShieldAlert, Menu, Library, Camera, Plus, FileSpreadsheet, 
  Download, X, User, HardDrive, CheckCircle2, ChevronRight, Edit3, Save 
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  // Modal states
  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);

  // Export selection state
  const [exportSelection, setExportSelection] = useState<string[]>([]);

  // New Study state
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleAddPatient = (newPatient: Patient) => setPatients(prev => [newPatient, ...prev]);

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleUpdateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudyGroup) {
      setStudyGroups(prev => prev.map(g => g.id === editingStudyGroup.id ? editingStudyGroup : g));
      setEditingStudyGroup(null);
    }
  };

  const handleExportToSheets = () => {
    if (exportSelection.length === 0) {
      alert("Please select at least one study group to export.");
      return;
    }
    const selectedNames = studyGroups.filter(g => exportSelection.includes(g.id)).map(g => g.name);
    alert(`Exporting data for ${selectedNames.join(', ')} to OPUS Research Spreadsheet in your Google Drive...`);
    setShowExportModal(false);
    setExportSelection([]);
  };

  const handleDownloadAllStudyData = (e: React.MouseEvent, groupId: string) => {
    e.stopPropagation();
    const groupName = studyGroups.find(g => g.id === groupId)?.name || 'Study';
    alert(`Compressing hi-def operative media for "${groupName}"... A secure download link will be sent to your Google ID email shortly.`);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
          <div className="flex justify-between items-center">
            <button 
              onClick={() => setSelectedStudyGroup(null)}
              className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors font-bold group"
            >
              <X size={20} className="group-hover:rotate-90 transition-transform" /> Close Study View
            </button>
            <button 
              onClick={() => setEditingStudyGroup(selectedStudyGroup)}
              className="flex items-center gap-2 bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold"
            >
              <Edit3 size={16} /> Edit Study Meta
            </button>
          </div>
          <div className="bg-white p-10 rounded-[2.5rem] border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-6">
            <div>
              <h2 className="text-4xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 mt-2 font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="flex items-center gap-4 bg-teal-50 px-6 py-4 rounded-3xl border border-teal-100">
              <HardDrive className="text-teal-600" size={24} />
              <div>
                <p className="text-[10px] font-black text-teal-700 uppercase tracking-widest leading-none">Drive Folder</p>
                <p className="font-mono text-xs text-teal-600 mt-1">{selectedStudyGroup.driveFolderId}</p>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {enrolledPatients.map(p => (
              <div 
                key={p.uhid}
                onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }}
                className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer flex items-center gap-5 group"
              >
                <div className="w-14 h-14 bg-teal-600 text-white rounded-2xl flex items-center justify-center text-xl font-black shadow-lg shadow-teal-500/20 group-hover:scale-110 transition-transform">
                  {p.lastName[0]}{p.firstName[0]}
                </div>
                <div>
                  <h4 className="font-bold text-slate-900 text-lg group-hover:text-teal-600 transition-colors">{p.lastName}, {p.firstName}</h4>
                  <p className="text-xs text-slate-500 font-mono tracking-wider">{p.uhid}</p>
                </div>
                <ChevronRight className="ml-auto text-slate-300" size={20} />
              </div>
            ))}
            {enrolledPatients.length === 0 && (
              <div className="col-span-full py-24 text-center text-slate-400 font-medium bg-slate-50 rounded-[2.5rem] border-2 border-dashed border-slate-200">
                <Library size={48} className="mx-auto mb-4 opacity-20" />
                No patients enrolled in this study group yet.
              </div>
            )}
          </div>
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard':
        return <Dashboard 
          patients={patients} 
          onAddPatient={handleAddPatient}
          onSelectPatient={(p) => setSelectedPatient(p)}
        />;
      case 'upload':
        return (
          <UploadMedia 
            patients={patients} 
            studyGroups={studyGroups}
            onUpload={(d) => {
              if (d.surgeryDate) {
                setPatients(prev => prev.map(p => 
                  p.uhid === d.uhid ? { ...p, dateOfSurgery: d.surgeryDate } : p
                ));
              }
              if (d.studyGroup) {
                setPatients(prev => prev.map(p => 
                  p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup)
                  ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] }
                  : p
                ));
              }
            }} 
          />
        );
      case 'research':
        return (
          <div className="py-6 space-y-10">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div>
                <h2 className="text-4xl font-black text-slate-900 tracking-tight">Research Groups</h2>
                <p className="text-slate-500 mt-2 font-medium">Orderly retrieval of clinical operative datasets.</p>
              </div>
              <div className="flex flex-wrap gap-3 w-full md:w-auto">
                <button onClick={() => setShowExportModal(true)} className="flex-1 md:flex-none flex items-center justify-center gap-2 border-2 border-slate-200 bg-white px-6 py-4 rounded-2xl text-sm font-black text-slate-700 hover:bg-slate-50 transition-all shadow-sm">
                  <FileSpreadsheet size={20} /> Export Data to Sheet
                </button>
                <button onClick={() => setShowAddStudyModal(true)} className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-teal-600 text-white px-6 py-4 rounded-2xl text-sm font-black shadow-2xl shadow-teal-500/20 hover:bg-teal-700 transition-all">
                  <Plus size={20} /> Create New Study
                </button>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
              {studyGroups.map(group => {
                const enrollmentCount = patients.filter(p => p.studyGroupIds.includes(group.id)).length;
                return (
                  <div 
                    key={group.id} 
                    onClick={() => setSelectedStudyGroup(group)}
                    className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm hover:shadow-2xl hover:-translate-y-1 transition-all group cursor-pointer relative overflow-hidden"
                  >
                    <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center mb-6 group-hover:scale-110 group-hover:bg-teal-600 group-hover:text-white transition-all shadow-sm"><Library size={32} /></div>
                    <h3 className="font-black text-slate-900 text-2xl tracking-tight leading-none mb-3">{group.name}</h3>
                    <p className="text-slate-500 text-sm font-medium mb-8 leading-relaxed h-10 line-clamp-2">{group.description}</p>
                    <div className="flex justify-between items-center pt-6 border-t border-slate-50">
                      <div className="flex items-center gap-2">
                        <div className="w-2.5 h-2.5 rounded-full bg-teal-500 shadow-sm"></div>
                        <span className="text-teal-700 font-black text-xs uppercase tracking-tight">
                          {enrollmentCount} Enrolled
                        </span>
                      </div>
                      <div className="flex items-center gap-2">
                        <button 
                          onClick={(e) => handleDownloadAllStudyData(e, group.id)}
                          className="p-2 text-slate-400 hover:text-teal-600 transition-colors"
                          title="Download Batch"
                        >
                          <Download size={18} />
                        </button>
                        <button 
                          onClick={(e) => { e.stopPropagation(); setEditingStudyGroup(group); }}
                          className="p-2 text-slate-400 hover:text-teal-600 transition-colors"
                          title="Edit Metadata"
                        >
                          <Edit3 size={18} />
                        </button>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        );
      default:
        return <Dashboard patients={patients} onAddPatient={handleAddPatient} onSelectPatient={(p) => setSelectedPatient(p)} />;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-[50rem] h-[50rem] bg-teal-500/10 -mr-96 -mt-96 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-0 left-0 w-[50rem] h-[50rem] bg-blue-500/10 -ml-96 -mb-96 rounded-full blur-[120px]"></div>

        <div className="max-w-md w-full bg-white rounded-[3.5rem] shadow-[0_32px_64px_-12px_rgba(0,0,0,0.5)] p-10 md:p-14 border border-white/20 relative z-10 text-center animate-in zoom-in-95 duration-500">
          <div className="mb-12">
            <div className="w-24 h-24 bg-teal-500 text-white rounded-[2.5rem] flex items-center justify-center mx-auto mb-8 shadow-2xl shadow-teal-500/30">
              <Camera size={48} />
            </div>
            <h1 className="text-6xl font-black text-slate-900 tracking-tighter mb-3 italic">OPUS</h1>
            <p className="text-slate-500 font-bold uppercase tracking-[0.3em] text-[10px]">Operative Photo Unite & Storage</p>
          </div>

          <div className="space-y-4">
            <button 
              type="button" 
              onClick={() => { setIsLoggedIn(true); }}
              className="w-full flex items-center justify-center gap-4 bg-white border-2 border-slate-100 py-5 rounded-[2rem] font-black text-slate-700 hover:bg-slate-50 hover:border-teal-500 transition-all group"
            >
              <img src="https://www.google.com/favicon.ico" className="w-6 h-6 grayscale group-hover:grayscale-0 transition-all" alt="Google" />
              Sign in with Google ID
            </button>
            <div className="relative py-4">
              <div className="absolute inset-0 flex items-center"><span className="w-full border-t border-slate-100"></span></div>
              <div className="relative flex justify-center text-[10px] uppercase tracking-widest font-black text-slate-300 bg-white px-4">Staff Terminal</div>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); setIsLoggedIn(true); }} className="space-y-4">
              <input type="text" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl outline-none focus:border-teal-500 transition-all font-bold text-slate-900" placeholder="Surgeon ID" required />
              <input type="password" placeholder="Passcode" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl outline-none focus:border-teal-500 transition-all font-bold text-slate-900" required />
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-4 rounded-[1.5rem] hover:bg-slate-800 transition-all text-lg shadow-xl shadow-slate-900/20">
                Access Core
              </button>
            </form>
          </div>
          <div className="mt-14 pt-8 border-t border-slate-50">
            <p className="text-[9px] text-slate-300 font-bold uppercase tracking-[0.2em] leading-relaxed">
              Medical Informatics • Clinical Research Compliance • High Definition Cloud Retrieval
            </p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 overflow-x-hidden selection:bg-teal-100">
      <Sidebar 
        activeView={activeView} 
        setActiveView={(v) => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} 
        onLogout={() => setIsLoggedIn(false)} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen} 
      />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between p-6 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md bg-white/80">
          <div className="flex items-center gap-3">
            <div className="lg:hidden p-2 bg-teal-500 rounded-xl text-white shadow-lg shadow-teal-500/20">
              <Camera size={20} />
            </div>
            <div className="lg:hidden font-black text-2xl tracking-tighter text-slate-900 italic">OPUS</div>
            {!selectedPatient && !selectedStudyGroup && <div className="hidden lg:block font-black text-slate-900 text-sm tracking-tight uppercase tracking-[0.2em] opacity-30">Staff Terminal • Dr. Smith</div>}
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-3 bg-teal-50 px-4 py-2 rounded-2xl border border-teal-100">
              <HardDrive className="text-teal-600" size={16} />
              <span className="text-[9px] font-black text-teal-700 uppercase tracking-widest">Drive Connected</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600 hover:bg-slate-50 rounded-xl transition-colors">
              <Menu size={28} />
            </button>
          </div>
        </div>

        <div className="p-6 md:p-12 max-w-[1440px] mx-auto w-full animate-in fade-in duration-500">
          {renderView()}
        </div>
      </main>

      {/* Add Study Modal */}
      {showAddStudyModal && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">Create New Study</h2>
              <button onClick={() => setShowAddStudyModal(false)} className="text-slate-400 p-2 hover:bg-white rounded-full transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleCreateStudy} className="p-10 space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Study Name</label>
                <input required value={newStudy.name} onChange={e => setNewStudy({...newStudy, name: e.target.value})} type="text" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold outline-none focus:border-teal-500 transition-all" placeholder="e.g. Tendon Repair 2026" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Research Objective</label>
                <textarea value={newStudy.description} onChange={e => setNewStudy({...newStudy, description: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl h-24 font-bold outline-none focus:border-teal-500 transition-all resize-none" placeholder="Describe clinical goals..."></textarea>
              </div>
              <button type="submit" className="w-full bg-teal-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-teal-500/20 text-lg">
                Initialize Research Cluster
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Edit Study Modal */}
      {editingStudyGroup && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">Edit Study Details</h2>
              <button onClick={() => setEditingStudyGroup(null)} className="text-slate-400 p-2 hover:bg-white rounded-full transition-colors"><X size={24} /></button>
            </div>
            <form onSubmit={handleUpdateStudy} className="p-10 space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Study Name</label>
                <input required value={editingStudyGroup.name} onChange={e => setEditingStudyGroup({...editingStudyGroup, name: e.target.value})} type="text" className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold outline-none focus:border-teal-500 transition-all" />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Objective</label>
                <textarea value={editingStudyGroup.description} onChange={e => setEditingStudyGroup({...editingStudyGroup, description: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl h-24 font-bold outline-none focus:border-teal-500 transition-all resize-none"></textarea>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl shadow-slate-900/20 text-lg flex items-center justify-center gap-2">
                <Save size={20} /> Save Study Meta
              </button>
            </form>
          </div>
        </div>
      )}

      {/* Export Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">Select Data Groups</h2>
              <button onClick={() => setShowExportModal(false)} className="text-slate-400 p-2 hover:bg-slate-50 rounded-full transition-colors"><X size={24} /></button>
            </div>
            <p className="text-slate-500 font-medium mb-6 text-sm">Choose the study clusters to sync with your linked Google Research Spreadsheet.</p>

            <div className="space-y-3 mb-10 max-h-60 overflow-y-auto pr-2">
              {studyGroups.map(group => (
                <button 
                  key={group.id}
                  onClick={() => setExportSelection(prev => 
                    prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id]
                  )}
                  className={`w-full text-left p-4 rounded-2xl border-2 transition-all flex items-center justify-between ${
                    exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 hover:border-slate-200'
                  }`}
                >
                  <span className="font-bold text-sm">{group.name}</span>
                  {exportSelection.includes(group.id) && <CheckCircle2 size={18} />}
                </button>
              ))}
