            <button onClick={handleExportToSheets} className="w-full bg-teal-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-teal-500/20 flex items-center justify-center gap-3 text-lg">
              <FileSpreadsheet size={20} />
              Export Selection to Drive
            </button>
          </div>
        </div>
      )}
