import React, { useState, useRef } from 'react';
import { Upload, Camera, Database, Tag, CheckCircle2, X, Trash2, PlayCircle, HardDrive } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [storage, setStorage] = useState<StorageLocation>(StorageLocation.GOOGLE_DRIVE);
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryDate, setSurgeryDate] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const generateVideoThumbnail = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;
      video.src = URL.createObjectURL(file);

      video.onloadedmetadata = () => {
        // Attempt to seek to 1 second once metadata is ready
        video.currentTime = Math.min(video.duration, 1);
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
          resolve(dataUrl);
        } else {
          resolve('');
        }
        URL.revokeObjectURL(video.src);
      };

      video.onerror = () => {
        console.error("Video thumbnail generation failed");
        resolve('');
        URL.revokeObjectURL(video.src);
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const newPreviews: PreviewFile[] = [];

      for (const file of files) {
        const type = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);
        let thumbnailUrl = undefined;

        if (type === 'video') {
          thumbnailUrl = await generateVideoThumbnail(file);
        }

        newPreviews.push({ url, file, type, thumbnailUrl });
      }

      setPreviewFiles(prev => [...prev, ...newPreviews]);
    }
  };

  const removeFile = (index: number) => {
    const fileToRemove = previewFiles[index];
    URL.revokeObjectURL(fileToRemove.url);
    setPreviewFiles(prev => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) {
      alert("Please select a patient and add media.");
      return;
    }

    setIsUploading(true);
    // Mimic secure Google Drive upload
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId,
        stage,
        surgeryDate: (stage !== SurgicalStage.PRE_OP) ? surgeryDate : null,
        storage,
        studyGroup: selectedGroup,
        tags: customTags.split(',').map(t => t.trim()).filter(t => t !== ''),
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length,
        driveLink: storage === StorageLocation.GOOGLE_DRIVE ? `https://drive.google.com/opus-id-${Math.random().toString(36).substr(2, 9)}` : null
      });
      setIsUploading(false);
      setShowSuccess(true);
      previewFiles.forEach(f => URL.revokeObjectURL(f.url));
      setPreviewFiles([]);
      setCustomTags('');
      setSelectedPatientId('');
    }, 1800);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xl mx-auto py-20 text-center space-y-10 animate-in zoom-in-95 duration-500">
        <div className="w-28 h-28 bg-teal-100 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-2xl shadow-teal-500/10">
          <CheckCircle2 size={56} />
        </div>
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Sync Complete</h2>
          <p className="text-slate-500 mt-2 font-medium text-lg">Media securely channeled to your Google ID vault.</p>
        </div>
        <div className="p-6 bg-slate-50 border border-slate-100 rounded-[2rem] flex items-center gap-4 text-left">
          <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center shadow-sm text-teal-600">
            <HardDrive size={24} />
          </div>
          <div>
            <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Storage Status</p>
            <p className="text-sm font-bold text-slate-800">Verified hi-def copy in {storage}</p>
          </div>
        </div>
        <button 
          onClick={() => setShowSuccess(false)}
          className="w-full bg-teal-600 text-white font-black py-5 rounded-2xl hover:bg-teal-700 transition-all shadow-2xl shadow-teal-500/20 text-xl"
        >
          Begin New Capture
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-5xl mx-auto py-4">
      <div className="mb-10 text-center lg:text-left">
        <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Media Portal</h1>
        <p className="text-slate-500 mt-2 font-medium text-lg">Direct pipeline to secure operative storage.</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 tracking-tight flex items-center gap-2">
              <Database size={20} className="text-teal-500" />
              1. Storage Destination
            </h2>

            <div className="space-y-4">
              <div className="grid grid-cols-1 gap-2">
                {[StorageLocation.GOOGLE_DRIVE, StorageLocation.LOCAL].map(loc => (
                  <button
                    key={loc}
                    type="button"
                    onClick={() => setStorage(loc as StorageLocation)}
                    className={`px-5 py-4 rounded-2xl border-2 text-sm font-black transition-all text-left flex justify-between items-center ${
                      storage === loc ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-500 bg-slate-50'
                    }`}
                  >
                    <span className="flex items-center gap-3">
                      {loc === StorageLocation.GOOGLE_DRIVE && <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />}
                      {loc}
                    </span>
                    {storage === loc && <CheckCircle2 size={18} />}
                  </button>
                ))}
              </div>

              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Target Patient Record</label>
                <select 
                  className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm appearance-none shadow-sm"
                  value={selectedPatientId}
                  onChange={e => setSelectedPatientId(e.target.value)}
                  required
                >
                  <option value="">Choose by UHID / Name...</option>
                  {patients.map(p => (
                    <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>
                  ))}
                </select>
              </div>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 tracking-tight flex items-center gap-2">
              <Tag size={20} className="text-teal-500" />
              2. Clinical Context
            </h2>

            <div className="space-y-4">
              <div className="space-y-2">
                {Object.values(SurgicalStage).map(s => (
                  <button
                    key={s}
                    type="button"
                    onClick={() => setStage(s)}
                    className={`w-full px-5 py-4 rounded-2xl border-2 text-sm font-black transition-all text-left flex justify-between items-center ${
                      stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-500 bg-slate-50'
                    }`}
                  >
                    {s}
                    {stage === s && <CheckCircle2 size={18} />}
                  </button>
                ))}
              </div>

              {stage !== SurgicalStage.PRE_OP && (
                <div className="animate-in slide-in-from-top-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Surgical Procedure Date</label>
                  <input 
                    type="date"
                    required
                    className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm"
                    value={surgeryDate}
                    onChange={e => setSurgeryDate(e.target.value)}
                  />
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="bg-white p-10 md:p-14 rounded-[3.5rem] border border-slate-200 shadow-sm space-y-10 h-full flex flex-col">
            <h2 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-3">
              <Upload size={28} className="text-teal-500" />
              3. HD Media Channel
            </h2>

            <div className="flex-1 space-y-10">
              <div className="group relative p-16 border-4 border-dashed border-slate-100 rounded-[3rem] bg-slate-50/50 hover:bg-white hover:border-teal-200 transition-all flex flex-col items-center justify-center text-center cursor-pointer shadow-sm">
                <input 
                  type="file" 
                  multiple 
                  accept="image/*,video/*"
                  className="absolute inset-0 opacity-0 cursor-pointer" 
                  onChange={handleFileChange}
                />
                <div className="p-8 bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 text-slate-400 mb-8 group-hover:scale-110 group-hover:text-teal-500 transition-all">
                  <Camera size={56} />
                </div>
                <h3 className="text-2xl font-black text-slate-900 tracking-tight">Tap to Source</h3>
                <p className="text-slate-500 font-medium mt-3">Upload hi-res procedure photos or surgical video reels.</p>
              </div>

              {previewFiles.length > 0 && (
                <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-6 animate-in fade-in slide-in-from-bottom-4">
                  {previewFiles.map((fileData, i) => (
                    <div key={i} className="group relative aspect-square rounded-[1.5rem] overflow-hidden border border-slate-200 shadow-lg bg-slate-900">
                      {fileData.type === 'video' ? (
                        <div className="relative w-full h-full">
                          {fileData.thumbnailUrl ? (
                            <img src={fileData.thumbnailUrl} className="w-full h-full object-cover opacity-80" alt="Video thumbnail" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center bg-slate-900 text-slate-600">
                              <PlayCircle size={40} />
                            </div>
                          )}
                          <div className="absolute inset-0 flex items-center justify-center bg-black/10 group-hover:bg-black/40 transition-colors">
                            <PlayCircle size={32} className="text-white drop-shadow-2xl opacity-80" />
                          </div>
                          <div className="absolute bottom-2 left-2 right-2 flex justify-between items-center">
                            <span className="text-[8px] font-black text-white/70 uppercase tracking-widest bg-black/40 px-1.5 py-0.5 rounded backdrop-blur-md">MP4 HD</span>
                          </div>
                        </div>
                      ) : (
                        <img src={fileData.url} className="w-full h-full object-cover" alt="Preview" />
                      )}
                      <button 
                        type="button"
                        onClick={() => removeFile(i)}
                        className="absolute top-3 right-3 p-2 bg-black/60 text-white rounded-xl opacity-0 group-hover:opacity-100 transition-opacity hover:bg-red-500 backdrop-blur-md shadow-lg"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  ))}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-6">
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Clinical Metadata Tags</label>
                  <input 
                    type="text" 
                    placeholder="e.g. trauma, microsurgery, POD1"
                    className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm shadow-sm"
                    value={customTags}
                    onChange={e => setCustomTags(e.target.value)}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Research Study Assignment</label>
                  <select 
                    className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 transition-all text-sm appearance-none shadow-sm"
