                    {studyGroups.map(g => (
                      <option key={g.id} value={g.id}>{g.name}</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId}
              className={`w-full font-black py-6 rounded-[2rem] flex items-center justify-center gap-4 shadow-2xl transition-all text-2xl mt-10 ${
                isUploading || previewFiles.length === 0 || !selectedPatientId
                ? 'bg-slate-100 text-slate-400 cursor-not-allowed shadow-none'
                : 'bg-teal-600 text-white hover:bg-teal-700 shadow-teal-500/20 active:scale-[0.98]'
              }`}
            >
              {isUploading ? (
                <>
                  <div className="w-7 h-7 border-4 border-white/30 border-t-white rounded-full animate-spin"></div>
                  Channelling to Drive Vault...
                </>
              ) : (
                <>
                  <CheckCircle2 size={28} />
                  Initiate OPUS Sync
                </>
              )}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

