import React, { useState, useRef } from 'react';
import { Upload, Camera, Database, Tag, CheckCircle2, X, Trash2, PlayCircle, HardDrive, Sparkles, BrainCircuit } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';
import { analyzeSurgicalImage } from '../services/geminiService';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
  base64?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [storage, setStorage] = useState<StorageLocation>(StorageLocation.GOOGLE_DRIVE);
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryDate, setSurgeryDate] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(',')[1] || '');
      reader.onerror = error => reject(error);
    });
  };

  const generateVideoThumbnail = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;
      video.src = URL.createObjectURL(file);
      video.onloadedmetadata = () => { video.currentTime = Math.min(video.duration, 1); };
      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          resolve(canvas.toDataURL('image/jpeg', 0.8));
        } else resolve('');
        URL.revokeObjectURL(video.src);
      };
      video.onerror = () => { resolve(''); URL.revokeObjectURL(video.src); };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const newPreviews: PreviewFile[] = [];
      for (const file of files) {
        const type = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);
        const base64 = type === 'image' ? await fileToBase64(file) : undefined;
        const thumbnailUrl = type === 'video' ? await generateVideoThumbnail(file) : undefined;
        newPreviews.push({ url, file, type, thumbnailUrl, base64 });
      }
      setPreviewFiles(prev => [...prev, ...newPreviews]);
    }
  };

  const handleAISuggestTags = async () => {
    const firstImage = previewFiles.find(f => f.type === 'image' && f.base64);
    if (!firstImage) {
      alert("Please upload at least one image to use AI tagging.");
      return;
    }
    setIsAnalyzing(true);
    try {
      const suggestion = await analyzeSurgicalImage(firstImage.base64!, "List 5 surgical or anatomical keywords found in this image, separated by commas. Focus on microvascular surgery context.");
      if (suggestion && !suggestion.includes("Error")) {
        setCustomTags(prev => prev ? `${prev}, ${suggestion}` : suggestion);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;
    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId,
        stage,
        surgeryDate: (stage !== SurgicalStage.PRE_OP) ? surgeryDate : null,
        storage,
        studyGroup: selectedGroup,
        tags: customTags.split(',').map(t => t.trim()).filter(t => t !== ''),
        timestamp: new Date().toISOString()
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setCustomTags('');
      setSelectedPatientId('');
    }, 1800);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xl mx-auto py-20 text-center space-y-10 animate-in zoom-in-95">
        <div className="w-28 h-28 bg-teal-100 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-2xl shadow-teal-500/10">
          <CheckCircle2 size={56} />
        </div>
        <div>
          <h2 className="text-4xl font-black text-slate-900 tracking-tight">Sync Complete</h2>
          <p className="text-slate-500 mt-2 font-medium">Data channeled to {storage}.</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-black py-5 rounded-2xl hover:bg-teal-700 shadow-2xl text-xl">
          Begin New Capture
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto py-4">
      <div className="mb-10 flex flex-col md:flex-row justify-between items-center gap-6">
        <div className="text-center lg:text-left">
          <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Media Portal</h1>
          <p className="text-slate-500 mt-2 font-medium text-lg">Direct pipeline to secure operative storage.</p>
        </div>
        {previewFiles.length > 0 && (
          <button 
            type="button" 
            onClick={handleAISuggestTags} 
            disabled={isAnalyzing}
            className={`flex items-center gap-3 px-6 py-3 rounded-2xl font-black text-sm shadow-xl transition-all ${isAnalyzing ? 'bg-slate-100 text-slate-400' : 'bg-gradient-to-r from-purple-600 to-blue-600 text-white hover:scale-105'}`}
          >
            {isAnalyzing ? <div className="w-4 h-4 border-2 border-slate-300 border-t-slate-800 rounded-full animate-spin" /> : <Sparkles size={18} />}
            {isAnalyzing ? 'Analyzing Image...' : 'Suggest Tags with Gemini AI'}
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 flex items-center gap-2"><Database size={20} className="text-teal-500" /> 1. Storage</h2>
            <div className="grid grid-cols-1 gap-2">
              {[StorageLocation.GOOGLE_DRIVE, StorageLocation.LOCAL].map(loc => (
                <button key={loc} type="button" onClick={() => setStorage(loc as StorageLocation)} className={`px-5 py-4 rounded-2xl border-2 text-sm font-black text-left flex justify-between items-center transition-all ${storage === loc ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-500 bg-slate-50'}`}>
                  <span className="flex items-center gap-3">{loc === StorageLocation.GOOGLE_DRIVE && <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />}{loc}</span>
                  {storage === loc && <CheckCircle2 size={18} />}
                </button>
              ))}
            </div>
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Target Patient Record</label>
              <select className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm shadow-sm" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)} required>
                <option value="">Choose by UHID / Name...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
              </select>
            </div>
          </div>
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 flex items-center gap-2"><Tag size={20} className="text-teal-500" /> 2. Stage</h2>
            <div className="space-y-2">
              {Object.values(SurgicalStage).map(s => (
                <button key={s} type="button" onClick={() => setStage(s)} className={`w-full px-5 py-4 rounded-2xl border-2 text-sm font-black text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-500 bg-slate-50'}`}>
                  {s}{stage === s && <CheckCircle2 size={18} />}
                </button>
              ))}
            </div>
            {stage !== SurgicalStage.PRE_OP && (
              <div className="animate-in slide-in-from-top-2">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Surgical Procedure Date</label>
                <input type="date" required className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm" value={surgeryDate} onChange={e => setSurgeryDate(e.target.value)} />
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-8 space-y-8">
          <div className="bg-white p-10 md:p-14 rounded-[3.5rem] border border-slate-200 shadow-sm space-y-10 flex flex-col min-h-full">
            <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3"><Upload size={28} className="text-teal-500" /> 3. Media Upload</h2>
            <div className="flex-1 space-y-8">
              <div className="group relative p-16 border-4 border-dashed border-slate-100 rounded-[3rem] bg-slate-50/50 hover:bg-white hover:border-teal-200 transition-all flex flex-col items-center justify-center text-center cursor-pointer">
                <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
                <div className="p-8 bg-white rounded-[2.5rem] shadow-xl text-slate-400 mb-8 group-hover:scale-110 group-hover:text-teal-500 transition-all"><Camera size={56} /></div>
                <h3 className="text-2xl font-black text-slate-900">HD Procedure Source</h3>
                <p className="text-slate-500 font-medium mt-3">Upload hi-res photos or intra-op video reels.</p>
              </div>

              {previewFiles.length > 0 && (
                <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-6 animate-in fade-in slide-in-from-bottom-4">
                  {previewFiles.map((fileData, i) => (
                    <div key={i} className="group relative aspect-square rounded-[1.5rem] overflow-hidden border border-slate-200 shadow-lg bg-slate-900">
                      {fileData.type === 'video' ? (
                        <div className="relative w-full h-full">
                          {fileData.thumbnailUrl ? <img src={fileData.thumbnailUrl} className="w-full h-full object-cover opacity-80" alt="" /> : <div className="w-full h-full flex items-center justify-center"><PlayCircle size={40} className="text-slate-600" /></div>}
                          <div className="absolute inset-0 flex items-center justify-center group-hover:bg-black/40 transition-all"><PlayCircle size={32} className="text-white opacity-80" /></div>
                        </div>
                      ) : <img src={fileData.url} className="w-full h-full object-cover" alt="" />}
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-3 right-3 p-2 bg-black/60 text-white rounded-xl opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500"><Trash2 size={16} /></button>
                    </div>
                  ))}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-6">
                <div className="relative">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Clinical Tags</label>
                  <input type="text" placeholder="e.g. median nerve, anastomosis..." className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm" value={customTags} onChange={e => setCustomTags(e.target.value)} />
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Study Assignment</label>
                  <select className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm shadow-sm" value={selectedGroup} onChange={e => setSelectedGroup(e.target.value)}>
                    <option value="">Unassigned</option>
                    {studyGroups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                  </select>
                </div>
              </div>
            </div>
            <button type="submit" disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} className={`w-full font-black py-6 rounded-[2rem] flex items-center justify-center gap-4 shadow-2xl transition-all text-2xl mt-10 ${isUploading || previewFiles.length === 0 || !selectedPatientId ? 'bg-slate-100 text-slate-400' : 'bg-teal-600 text-white hover:bg-teal-700 active:scale-[0.98]'}`}>
              {isUploading ? <><div className="w-7 h-7 border-4 border-white/30 border-t-white rounded-full animate-spin" /> Syncing Drive...</> : <><CheckCircle2 size={28} /> Initiate OPUS Sync</>}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

