import React, { useState } from 'react';
import { ArrowLeft, Plus, Download, Tag, Calendar, User, Microscope, X, Edit, Save, Trash2, Columns } from 'lucide-react';
import { Patient, SurgicalStage, MediaEntry, StudyGroup } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  studyGroups: StudyGroup[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient, studyGroups }) => {
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showTagModal, setShowTagModal] = useState(false);
  const [showStudyModal, setShowStudyModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [isCompareMode, setIsCompareMode] = useState(false);
  const [editPatient, setEditPatient] = useState<Patient>({ ...patient });

  const patientMedia = MOCK_MEDIA.filter(m => m.uhid === patient.uhid);
  const filteredMedia = patientMedia.filter(m => m.stage === activeStage);

  const preOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.PRE_OP);
  const postOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.POST_OP);

  const handleAddToStudy = (groupId: string) => {
    if (patient.studyGroupIds.includes(groupId)) return;
    onUpdatePatient({ ...patient, studyGroupIds: [...patient.studyGroupIds, groupId] });
    setShowStudyModal(false);
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto pb-20">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors font-bold group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> Back to Dashboard
        </button>
        <button 
          onClick={() => setIsCompareMode(!isCompareMode)}
          className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all ${isCompareMode ? 'bg-teal-600 text-white shadow-lg' : 'bg-slate-100 text-slate-600'}`}
        >
          <Columns size={18} /> {isCompareMode ? 'Normal View' : 'Compare Mode'}
        </button>
      </div>

      <div className="bg-white p-8 md:p-10 rounded-[2.5rem] border border-slate-200 shadow-sm relative overflow-hidden">
        <div className="flex flex-col lg:flex-row justify-between items-start gap-8">
          <div className="flex gap-6 items-center">
            <div className="w-20 h-20 md:w-28 bg-teal-600 text-white rounded-[2rem] flex items-center justify-center text-3xl font-black shadow-2xl">
              {patient.lastName[0]}{patient.firstName[0]}
            </div>
            <div className="space-y-1">
              <div className="flex items-center gap-3 flex-wrap">
                <h1 className="text-3xl font-black text-slate-900 tracking-tight">{patient.lastName}, {patient.firstName}</h1>
                <span className="bg-slate-100 px-3 py-1.5 rounded-xl font-mono font-bold text-xs text-slate-600">{patient.uhid}</span>
              </div>
              <div className="flex gap-4 text-slate-500 font-semibold text-sm">
                <span>Age: {patient.ageYears}y {patient.ageYears < 2 ? `${patient.ageMonths}m` : ''}</span>
                {patient.dateOfSurgery && <span className="text-orange-600">Surg: {patient.dateOfSurgery}</span>}
              </div>
            </div>
          </div>
          <div className="flex flex-wrap gap-2 w-full lg:w-auto">
            <button onClick={onAddMedia} className="flex-1 lg:flex-none flex items-center justify-center gap-2 bg-teal-600 text-white px-6 py-3 rounded-2xl font-bold shadow-lg shadow-teal-500/10">
              <Plus size={18} /> Add Media
            </button>
            <button onClick={() => setShowEditModal(true)} className="flex-1 lg:flex-none flex items-center justify-center gap-2 border border-slate-200 bg-white px-6 py-3 rounded-2xl font-bold">
              <Edit size={18} /> Edit
            </button>
          </div>
        </div>
      </div>

      {!isCompareMode ? (
        <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
          <div className="flex border-b border-slate-100 bg-slate-50/50 p-2">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-4 text-xs font-black tracking-widest uppercase transition-all rounded-2xl ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-10">
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative bg-slate-100 rounded-[2rem] overflow-hidden aspect-square border border-slate-200 hover:shadow-2xl transition-all">
                  <img src={m.url} className="w-full h-full object-cover" alt="" />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity p-6 flex flex-col justify-end">
                    <button className="absolute top-4 right-4 p-2 bg-white/20 backdrop-blur-md rounded-lg text-white"><Download size={16} /></button>
                    <p className="text-[10px] text-white/70 uppercase font-black tracking-widest">{new Date(m.uploadedAt).toLocaleDateString()}</p>
                    <div className="flex flex-wrap gap-1.5 mt-2">
                      {m.tags.map(t => <span key={t} className="text-[8px] bg-white/10 text-white px-2 rounded-md font-bold uppercase">{t}</span>)}
                    </div>
                  </div>
                </div>
              ))}
              {filteredMedia.length === 0 && <div className="col-span-full py-20 text-center text-slate-400 font-bold">No media available for this phase.</div>}
            </div>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 animate-in slide-in-from-right-4 duration-500">
          <div className="space-y-4">
            <h3 className="text-xl font-black text-slate-800 px-2 uppercase tracking-widest">Pre-Operative Baseline</h3>
            <div className="bg-white p-6 rounded-[2.5rem] border border-slate-200 h-[500px] overflow-y-auto space-y-4">
              {preOpMedia.map(m => <div key={m.id} className="rounded-3xl overflow-hidden border-2 border-slate-100"><img src={m.url} className="w-full object-cover" alt="" /></div>)}
              {preOpMedia.length === 0 && <div className="h-full flex items-center justify-center text-slate-300 font-bold italic">No Pre-op assets.</div>}
            </div>
          </div>
          <div className="space-y-4">
            <h3 className="text-xl font-black text-slate-800 px-2 uppercase tracking-widest">Post-Operative Progress</h3>
            <div className="bg-white p-6 rounded-[2.5rem] border border-slate-200 h-[500px] overflow-y-auto space-y-4">
              {postOpMedia.map(m => <div key={m.id} className="rounded-3xl overflow-hidden border-2 border-slate-100 shadow-sm"><img src={m.url} className="w-full object-cover" alt="" /></div>)}
              {postOpMedia.length === 0 && <div className="h-full flex items-center justify-center text-slate-300 font-bold italic">No Post-op assets.</div>}
            </div>
          </div>
        </div>
      )}

      {/* Edit Patient Modal */}
      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xl rounded-[2.5rem] shadow-2xl overflow-hidden p-10">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black text-slate-900">Edit Patient Details</h2>
              <button onClick={() => setShowEditModal(false)} className="text-slate-400"><X size={24} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="col-span-2"><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">UHID</label><input value={editPatient.uhid} onChange={e => setEditPatient({...editPatient, uhid: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl border-2 border-slate-100 font-bold" /></div>
                <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">First Name</label><input value={editPatient.firstName} onChange={e => setEditPatient({...editPatient, firstName: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl border-2 border-slate-100 font-bold" /></div>
                <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Last Name</label><input value={editPatient.lastName} onChange={e => setEditPatient({...editPatient, lastName: e.target.value})} className="w-full p-4 bg-slate-50 rounded-2xl border-2 border-slate-100 font-bold" /></div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl">Save Changes</button>
            </form>
          </div>
        </div>
      )}

      {/* Study Modal */}
      {showStudyModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95">
            <h3 className="text-2xl font-black mb-8">Study Groups</h3>
            <div className="space-y-3">
              {studyGroups.map(g => (
                <button key={g.id} onClick={() => handleAddToStudy(g.id)} className={`w-full text-left p-4 rounded-2xl border-2 transition-all font-bold ${patient.studyGroupIds.includes(g.id) ? 'bg-teal-50 border-teal-200 text-teal-800' : 'border-slate-50 hover:bg-slate-50'}`}>
                  {g.name}
                </button>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

