                <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center mb-6 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={32} /></div>
                <h3 className="font-black text-slate-900 text-2xl tracking-tight leading-none mb-3">{group.name}</h3>
                <p className="text-slate-500 text-sm font-medium leading-relaxed h-10 line-clamp-2">{group.description}</p>
