                    <button onClick={e => { e.stopPropagation(); setEditingStudyGroup(group); }} className="p-2 text-slate-400 hover:text-teal-600"><Edit3 size={18} /></button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-0 right-0 w-[50rem] h-[50rem] bg-teal-500/10 -mr-96 -mt-96 rounded-full blur-[120px]" />
        <div className="absolute bottom-0 left-0 w-[50rem] h-[50rem] bg-blue-500/10 -ml-96 -mb-96 rounded-full blur-[120px]" />
        <div className="max-w-md w-full bg-white rounded-[3.5rem] shadow-2xl p-10 md:p-14 relative z-10 text-center animate-in zoom-in-95 duration-500 border border-white/20">
          <div className="mb-12">
            <OpusLogo size="lg" className="mx-auto mb-8 shadow-2xl shadow-teal-500/20 rounded-[2.5rem]" />
            <OpusTextLogo className="justify-center text-4xl" />
            <p className="text-slate-500 font-bold uppercase tracking-[0.3em] text-[10px] mt-4">Operative Photo Unite & Storage</p>
          </div>
          <div className="space-y-4">
            <button onClick={() => setIsLoggedIn(true)} className="w-full flex items-center justify-center gap-4 bg-white border-2 border-slate-100 py-5 rounded-[2rem] font-black text-slate-700 hover:border-teal-500 transition-all group">
              <img src="https://www.google.com/favicon.ico" className="w-6 h-6 grayscale group-hover:grayscale-0 transition-all" alt="" /> Sign in with Google ID
            </button>
            <div className="relative py-4"><div className="absolute inset-0 flex items-center"><span className="w-full border-t border-slate-100" /></div><div className="relative flex justify-center text-[10px] uppercase tracking-widest font-black text-slate-300 bg-white px-4">Terminal Access</div></div>
            <form onSubmit={e => { e.preventDefault(); setIsLoggedIn(true); }} className="space-y-4">
