  }

  return (
    <div className="flex min-h-screen bg-slate-50">
      <Sidebar activeView={activeView} setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} onLogout={() => setIsLoggedIn(false)} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />
      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between p-6 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md bg-white/80">
          <div className="flex items-center gap-3">
            <div className="lg:hidden p-2 bg-teal-500 rounded-xl text-white shadow-lg shadow-teal-500/20"><Camera size={20} /></div>
            <div className="lg:hidden font-black text-2xl tracking-tighter text-slate-900 italic">OPUS</div>
            {!selectedPatient && !selectedStudyGroup && <div className="hidden lg:block font-black text-slate-900 text-sm uppercase tracking-[0.2em] opacity-30">Surgeon Console • Dr. Smith</div>}
          </div>
          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-3 bg-teal-50 px-4 py-2 rounded-2xl border border-teal-100">
              <HardDrive className="text-teal-600" size={16} /><span className="text-[9px] font-black text-teal-700 uppercase">Drive Synced</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-600"><Menu size={28} /></button>
          </div>
        </div>
        <div className="p-6 md:p-12 max-w-[1440px] mx-auto w-full animate-in fade-in duration-500">{renderView()}</div>
      </main>

      {showAddStudyModal && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] p-10 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-10"><h2 className="text-3xl font-black">Create Study</h2><button onClick={() => setShowAddStudyModal(false)}><X size={24} /></button></div>
            <form onSubmit={handleCreateStudy} className="space-y-6">
              <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Study Name</label><input required value={newStudy.name} onChange={e => setNewStudy({...newStudy, name: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold outline-none focus:border-teal-500" placeholder="e.g. Nerve Cluster 2026" /></div>
              <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Description</label><textarea value={newStudy.description} onChange={e => setNewStudy({...newStudy, description: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl h-24 font-bold outline-none focus:border-teal-500 resize-none" placeholder="Research clinical goals..." /></div>
              <button type="submit" className="w-full bg-teal-600 text-white font-black py-5 rounded-2xl shadow-xl shadow-teal-500/20 text-lg">Initialize Cluster</button>
            </form>
          </div>
        </div>
      )}

      {editingStudyGroup && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-8"><h2 className="text-2xl font-black">Edit Study Details</h2><button onClick={() => setEditingStudyGroup(null)}><X size={24} /></button></div>
            <form onSubmit={handleUpdateStudy} className="space-y-6">
              <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Name</label><input required value={editingStudyGroup.name} onChange={e => setEditingStudyGroup({...editingStudyGroup, name: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl font-bold" /></div>
              <div><label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2">Objective</label><textarea value={editingStudyGroup.description} onChange={e => setEditingStudyGroup({...editingStudyGroup, description: e.target.value})} className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl h-24 font-bold" /></div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl shadow-slate-900/20 text-lg flex items-center justify-center gap-2"><Save size={20} /> Save Study Meta</button>
            </form>
          </div>
        </div>
      )}

      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-8"><h2 className="text-2xl font-black">Select Research Groups</h2><button onClick={() => setShowExportModal(false)}><X size={24} /></button></div>
            <p className="text-slate-500 font-medium mb-6 text-sm">Choose clusters to sync with your linked Google Research vault.</p>
            <div className="space-y-3 mb-10 max-h-60 overflow-y-auto pr-2">
              {studyGroups.map(group => (
                <button key={group.id} onClick={() => setExportSelection(prev => prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id])} className={`w-full text-left p-4 rounded-2xl border-2 transition-all flex items-center justify-between ${exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 hover:border-slate-200'}`}>
                  <span className="font-bold text-sm">{group.name}</span>{exportSelection.includes(group.id) && <CheckCircle2 size={18} />}
                </button>
              ))}
            </div>
            <button onClick={handleExportToSheets} className="w-full bg-teal-600 text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 text-lg"><FileSpreadsheet size={20} /> Export to Drive</button>
          </div>
        </div>
      )}
    </div>
  );
};

