              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-2xl shadow-xl shadow-slate-900/20 text-lg flex items-center justify-center gap-2"><Save size={20} /> Update Metadata</button>
            </form>
          </div>
        </div>
      )}

      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-8"><h2 className="text-2xl font-black">Sync Research Unit</h2><button onClick={() => setShowExportModal(false)}><X size={24} /></button></div>
            <p className="text-slate-500 font-medium mb-6 text-sm">Select clusters to synchronize with the institutional Drive Sheet.</p>
            <div className="space-y-3 mb-10 max-h-60 overflow-y-auto pr-2">
              {studyGroups.map(group => (
                <button key={group.id} onClick={() => setExportSelection(prev => prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id])} className={`w-full text-left p-4 rounded-2xl border-2 transition-all flex items-center justify-between ${exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 hover:border-slate-200'}`}>
                  <span className="text-sm">{group.name}</span>{exportSelection.includes(group.id) && <CheckCircle2 size={18} />}
                </button>
              ))}
            </div>
            <button onClick={handleExportToSheets} className="w-full bg-teal-600 text-white font-black py-5 rounded-2xl shadow-xl flex items-center justify-center gap-3 text-lg hover:bg-teal-700 transition-all"><FileSpreadsheet size={20} /> Sync to Research Vault</button>
          </div>
        </div>
      )}
    </div>
  );
};

