  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);
  const [autoSync, setAutoSync] = useState(true);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(',')[1] || '');
      reader.onerror = error => reject(error);
    });
  };

  const generateVideoThumbnail = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;
      video.src = URL.createObjectURL(file);
      video.onloadedmetadata = () => { video.currentTime = Math.min(video.duration, 0.5); };
      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          resolve(canvas.toDataURL('image/jpeg', 0.8));
        } else resolve('');
        URL.revokeObjectURL(video.src);
      };
      video.onerror = () => { resolve(''); URL.revokeObjectURL(video.src); };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const newPreviews: PreviewFile[] = [];
      for (const file of files) {
        const type = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);
        const base64 = type === 'image' ? await fileToBase64(file) : undefined;
        const thumbnailUrl = type === 'video' ? await generateVideoThumbnail(file) : undefined;
        newPreviews.push({ url, file, type, thumbnailUrl, base64 });
      }
      setPreviewFiles(prev => [...prev, ...newPreviews]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleAISuggestTags = async () => {
    const firstImage = previewFiles.find(f => f.type === 'image' && f.base64);
    if (!firstImage) {
      alert("Please upload at least one image to use AI tagging.");
      return;
    }
    setIsAnalyzing(true);
    try {
      const suggestion = await analyzeSurgicalImage(firstImage.base64!, "List 5 microvascular keywords found in this image, separated by commas.");
      if (suggestion && !suggestion.includes("Error")) {
        setCustomTags(prev => prev ? `${prev}, ${suggestion}` : suggestion);
      }
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;
    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId,
        stage,
        surgeryDate: (stage !== SurgicalStage.PRE_OP) ? surgeryDate : null,
        storage,
        studyGroup: selectedGroup,
        tags: customTags.split(',').map(t => t.trim()).filter(t => t !== ''),
        timestamp: new Date().toISOString()
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setCustomTags('');
      setSelectedPatientId('');
    }, 2000);
  };

  if (showSuccess) {
    return (
      <div className="max-w-2xl mx-auto py-20 text-center space-y-12 animate-in zoom-in-95 duration-500">
        <div className="w-32 h-32 bg-teal-50 text-teal-600 rounded-[3rem] flex items-center justify-center mx-auto shadow-2xl shadow-teal-500/10 border border-teal-100">
          <CheckCircle2 size={64} />
        </div>
        <div className="space-y-4">
          <h2 className="text-5xl font-black text-slate-900 tracking-tighter italic">Vault Locked</h2>
          <p className="text-slate-400 font-medium text-xl">Operational documentation securely channeled to the Drive Cloud.</p>
        </div>
        <div className="grid grid-cols-2 gap-4 max-w-md mx-auto">
          <button onClick={() => setShowSuccess(false)} className="bg-teal-600 text-white font-black py-5 rounded-[2rem] hover:bg-teal-700 shadow-2xl shadow-teal-500/20 text-lg transition-all active:scale-[0.98]">
            New Entry
          </button>
          <button onClick={() => window.open('https://drive.google.com', '_blank')} className="bg-white border-2 border-slate-100 text-slate-600 font-black py-5 rounded-[2rem] hover:bg-slate-50 text-lg transition-all flex items-center justify-center gap-2">
            <CloudUpload size={20} /> Drive View
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-6xl mx-auto py-4">
      <div className="mb-12 flex flex-col md:flex-row justify-between items-center gap-8">
        <div className="text-center lg:text-left">
          <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Media Portal</h1>
          <p className="text-slate-400 mt-2 font-medium text-lg">Hi-res clinical capture & research pipeline.</p>
        </div>
        <div className="flex gap-4">
          <button 
            type="button" 
            onClick={handleAISuggestTags} 
            disabled={isAnalyzing || previewFiles.length === 0}
            className={`flex items-center gap-3 px-8 py-4 rounded-[2rem] font-black text-sm shadow-xl transition-all ${isAnalyzing || previewFiles.length === 0 ? 'bg-slate-100 text-slate-400 opacity-50' : 'bg-slate-900 text-white hover:bg-slate-800'}`}
          >
            {isAnalyzing ? <div className="w-4 h-4 border-2 border-slate-300 border-t-white rounded-full animate-spin" /> : <Sparkles size={18} className="text-teal-400" />}
            AI Assist
          </button>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 flex items-center gap-3">
              <div className="w-10 h-10 bg-teal-50 rounded-xl flex items-center justify-center text-teal-600"><Database size={20} /></div>
              Indexing
            </h2>
            <div className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Sync Strategy</label>
                <div className="flex bg-slate-50 p-1.5 rounded-2xl border border-slate-100">
                  <button type="button" onClick={() => setStorage(StorageLocation.GOOGLE_DRIVE)} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all ${storage === StorageLocation.GOOGLE_DRIVE ? 'bg-white text-teal-600 shadow-sm' : 'text-slate-400'}`}>Cloud</button>
                  <button type="button" onClick={() => setStorage(StorageLocation.LOCAL)} className={`flex-1 py-3 rounded-xl text-xs font-black transition-all ${storage === StorageLocation.LOCAL ? 'bg-white text-slate-700 shadow-sm' : 'text-slate-400'}`}>Local Only</button>
                </div>
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Target UHID</label>
                <select className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm appearance-none cursor-pointer" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)} required>
                  <option value="">Search patient...</option>
                  {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="bg-white p-8 rounded-[3rem] border border-slate-200 shadow-sm space-y-6">
            <h2 className="text-lg font-black text-slate-900 flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-50 rounded-xl flex items-center justify-center text-blue-600"><Tag size={20} /></div>
              Surgical Data
            </h2>
            <div className="space-y-4">
              <div className="space-y-2">
                {Object.values(SurgicalStage).map(s => (
                  <button key={s} type="button" onClick={() => setStage(s)} className={`w-full px-5 py-4 rounded-2xl border-2 text-sm font-black text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                    {s}{stage === s && <CheckCircle2 size={18} />}
                  </button>
                ))}
              </div>
              {stage !== SurgicalStage.PRE_OP && (
                <div className="animate-in slide-in-from-top-2">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Procedure Date</label>
                  <input type="date" required className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm" value={surgeryDate} onChange={e => setSurgeryDate(e.target.value)} />
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="lg:col-span-8 space-y-8 h-full">
          <div className="bg-white p-10 rounded-[3.5rem] border border-slate-200 shadow-sm space-y-10 flex flex-col h-full min-h-[600px]">
            <div className="flex justify-between items-center">
               <h2 className="text-2xl font-black text-slate-900 flex items-center gap-3">
                 <div className="w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-600"><Camera size={24} /></div>
                 Media Hub
               </h2>
               <div className="flex items-center gap-3 bg-slate-50 px-4 py-2 rounded-2xl border border-slate-100">
                  <span className="text-[10px] font-black text-slate-400 uppercase">Auto-Sync</span>
                  <button type="button" onClick={() => setAutoSync(!autoSync)} className={`w-10 h-6 rounded-full p-1 transition-all flex ${autoSync ? 'bg-teal-500 justify-end' : 'bg-slate-300 justify-start'}`}>
                    <div className="w-4 h-4 bg-white rounded-full shadow-sm" />
                  </button>
               </div>
            </div>

            <div className="flex-1 space-y-10">
              <div className="group relative p-16 border-4 border-dashed border-slate-100 rounded-[3rem] bg-slate-50/30 hover:bg-white hover:border-teal-200 transition-all flex flex-col items-center justify-center text-center cursor-pointer shadow-inner">
                <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
                <div className="p-10 bg-white rounded-[2.5rem] shadow-2xl text-slate-400 mb-8 group-hover:scale-110 group-hover:text-teal-500 transition-all duration-500 border border-slate-50"><Camera size={64} /></div>
                <h3 className="text-3xl font-black text-slate-900 italic tracking-tight">Source HD Assets</h3>
                <p className="text-slate-400 font-medium mt-3">Hi-res procedure photography or operative reel clips.</p>
              </div>

              {previewFiles.length > 0 && (
                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 gap-6 animate-in fade-in slide-in-from-bottom-6 duration-500">
                  {previewFiles.map((fileData, i) => (
                    <div key={i} className="group relative aspect-square rounded-[1.5rem] overflow-hidden border border-slate-200 shadow-xl bg-slate-900 transition-transform hover:scale-105 active:scale-95">
                      {fileData.type === 'video' ? (
                        <div className="relative w-full h-full">
                          {fileData.thumbnailUrl ? <img src={fileData.thumbnailUrl} className="w-full h-full object-cover opacity-80" alt="" /> : <div className="w-full h-full flex items-center justify-center"><PlayCircle size={40} className="text-slate-600" /></div>}
                          <div className="absolute inset-0 flex items-center justify-center group-hover:bg-black/30 transition-all"><PlayCircle size={28} className="text-white opacity-90 drop-shadow-lg" /></div>
                        </div>
                      ) : <img src={fileData.url} className="w-full h-full object-cover" alt="" />}
                      <button type="button" onClick={() => removeFile(i)} className="absolute top-2 right-2 p-2 bg-black/60 text-white rounded-xl opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500 backdrop-blur-md shadow-lg"><Trash2 size={14} /></button>
                    </div>
                  ))}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-6 border-t border-slate-50">
                <div className="relative">
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Research Tags</label>
                  <div className="relative">
                    <Tag className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input type="text" placeholder="e.g.MedianNerve, Microsurgery..." className="w-full pl-12 pr-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm" value={customTags} onChange={e => setCustomTags(e.target.value)} />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Study Cluster Assignment</label>
                  <select className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 outline-none focus:border-teal-500 text-sm appearance-none shadow-sm cursor-pointer" value={selectedGroup} onChange={e => setSelectedGroup(e.target.value)}>
                    <option value="">Institutional Pool (Unassigned)</option>
                    {studyGroups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                  </select>
                </div>
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className={`w-full font-black py-7 rounded-[2.5rem] flex items-center justify-center gap-4 shadow-2xl transition-all text-2xl mt-12 mb-2 ${isUploading || previewFiles.length === 0 || !selectedPatientId ? 'bg-slate-100 text-slate-300' : 'bg-teal-600 text-white hover:bg-teal-700 hover:shadow-teal-500/30 active:scale-[0.98]'}`}
            >
              {isUploading ? <><div className="w-7 h-7 border-4 border-white/30 border-t-white rounded-full animate-spin" /> Locked Syncing...</> : <><CloudUpload size={32} /> Commit to Google Drive</>}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

