  const [editPatient, setEditPatient] = useState<Patient>({ ...patient });
  const [syncingIds, setSyncingIds] = useState<Set<string>>(new Set());

  const patientMedia = MOCK_MEDIA.filter(m => m.uhid === patient.uhid);
  const filteredMedia = patientMedia.filter(m => m.stage === activeStage);

  const preOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.PRE_OP);
  const postOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.POST_OP);

