import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  Download, X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinking, setIsLinking] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleLinkGoogle = () => {
    setIsLinking(true);
    setTimeout(() => {
      setIsLinking(false);
      setIsLinked(true);
    }, 1200);
  };

  const handleAddPatient = (newPatient: Patient) => setPatients(prev => [newPatient, ...prev]);

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleUpdateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingStudyGroup) {
      setStudyGroups(prev => prev.map(g => g.id === editingStudyGroup.id ? editingStudyGroup : g));
      setEditingStudyGroup(null);
    }
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-sm font-semibold">
              <X size={18} /> Close Study
            </button>
            <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold transition-transform hover:scale-105">
              <Edit3 size={14} className="inline mr-2" /> Edit Meta
            </button>
          </div>
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-sm font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-5 py-3 rounded-xl border border-slate-100 flex items-center gap-3">
              <HardDrive className="text-slate-400" size={18} />
              <p className="font-mono text-[10px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {enrolledPatients.map(p => (
              <div key={p.uhid} onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }} className="bg-white p-4 rounded-xl border border-slate-200 hover:border-teal-500 transition-all cursor-pointer flex items-center gap-4 group">
                <div className="w-10 h-10 bg-teal-600 text-white rounded-lg flex items-center justify-center text-sm font-black">{p.lastName[0]}{p.firstName[0]}</div>
                <div><h4 className="font-bold text-slate-900 text-sm">{p.lastName}, {p.firstName}</h4><p className="text-[10px] text-slate-400 font-mono">{p.uhid}</p></div>
                <ChevronRight className="ml-auto text-slate-300 group-hover:text-teal-600" size={16} />
              </div>
            ))}
            {enrolledPatients.length === 0 && (
              <div className="col-span-full py-10 text-center border border-dashed border-slate-200 rounded-2xl text-slate-400 text-sm font-medium">
                No patients enrolled in this cluster.
              </div>
            )}
          </div>
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={patients} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={patients} studyGroups={studyGroups} onUpload={d => { d.studyGroup && setPatients(prev => prev.map(p => p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup) ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] } : p)); }} />;
      case 'research': return (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <div><h2 className="text-2xl font-black text-slate-900 tracking-tight">Research Clusters</h2></div>
            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 border border-slate-200 bg-white px-4 py-2 rounded-xl text-xs font-bold text-slate-700 hover:bg-slate-50 transition-all"><FileSpreadsheet size={16} /> Sync Sheets</button>
              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-4 py-2 rounded-xl text-xs font-bold hover:bg-teal-700 transition-all"><Plus size={16} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-10 h-10 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-4 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={20} /></div>
                <h3 className="font-bold text-slate-900 text-lg mb-1">{group.name}</h3>
                <p className="text-slate-500 text-xs font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-4 border-t border-slate-50 mt-4">
                  <span className="text-teal-700 font-bold text-[10px] uppercase">{patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <div className="flex gap-2">
                    <button onClick={e => { e.stopPropagation(); setEditingStudyGroup(group); }} className="text-slate-400 hover:text-teal-600"><Edit3 size={14} /></button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-white flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-sm w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-8">
            <OpusLogo size="md" className="mx-auto mb-4 shadow-xl rounded-2xl" />
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
