import React, { useState } from 'react';
import { Camera, Database, Tag, CheckCircle2, Trash2, PlayCircle, Sparkles, CloudUpload } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';
import { analyzeSurgicalImage } from '../services/geminiService';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
  base64?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [storage, setStorage] = useState<StorageLocation>(StorageLocation.GOOGLE_DRIVE);
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryDate, setSurgeryDate] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(',')[1] || '');
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const newPreviews: PreviewFile[] = [];
      for (const file of files) {
        const type = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);
        const base64 = type === 'image' ? await fileToBase64(file) : undefined;
        newPreviews.push({ url, file, type, base64 });
      }
      setPreviewFiles(prev => [...prev, ...newPreviews]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleAISuggestTags = async () => {
    const firstImage = previewFiles.find(f => f.type === 'image' && f.base64);
    if (!firstImage) return;
    setIsAnalyzing(true);
    try {
      const suggestion = await analyzeSurgicalImage(firstImage.base64!, "List 5 microvascular keywords found in this image, separated by commas.");
      if (suggestion && !suggestion.includes("Error")) {
        setCustomTags(prev => prev ? `${prev}, ${suggestion}` : suggestion);
      }
    } finally { setIsAnalyzing(false); }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;
    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, stage, surgeryDate, storage,
        studyGroup: selectedGroup, tags: customTags.split(',').filter(t => t.trim()),
        timestamp: new Date().toISOString()
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setCustomTags('');
      setSelectedPatientId('');
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-md mx-auto py-16 text-center space-y-8 animate-in zoom-in-95">
        <div className="w-20 h-20 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center mx-auto shadow-sm border border-teal-100">
          <CheckCircle2 size={40} />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-black text-slate-900 tracking-tight italic">Vault Synced</h2>
          <p className="text-slate-400 font-medium text-sm">Media securely locked in the Cloud Repository.</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-4 rounded-xl shadow-lg transition-all active:scale-[0.98]">
          Capture New Entry
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight">Media Portal</h1>
          <p className="text-slate-400 text-xs font-semibold uppercase tracking-widest">Operative Documentation Intake</p>
        </div>
        <button 
          onClick={handleAISuggestTags} 
          disabled={isAnalyzing || previewFiles.length === 0}
          className="flex items-center gap-2 px-4 py-2 bg-slate-900 text-white rounded-xl text-xs font-bold transition-all disabled:opacity-50"
        >
          {isAnalyzing ? <div className="w-3 h-3 border-2 border-slate-300 border-t-white rounded-full animate-spin" /> : <Sparkles size={14} className="text-teal-400" />}
          AI Assist
        </button>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-6 items-start">
        <div className="lg:col-span-4 space-y-4">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <h2 className="text-sm font-black text-slate-900 flex items-center gap-2">
              <Database size={16} className="text-teal-600" /> Indexing
            </h2>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID *</label>
              <select className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 text-xs" value={selectedPatientId} onChange={e => setSelectedPatientId(e.target.value)} required>
                <option value="">Choose Patient...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
              </select>
            </div>
            <div>
              <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Stage</label>
              <div className="grid grid-cols-1 gap-1">
                {Object.values(SurgicalStage).map(s => (
                  <button key={s} type="button" onClick={() => setStage(s)} className={`px-4 py-2 rounded-lg border text-[11px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                    {s}{stage === s && <CheckCircle2 size={12} />}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        <div className="lg:col-span-8 space-y-4">
          <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm space-y-8 flex flex-col">
            <div className="group relative p-12 border-2 border-dashed border-slate-100 rounded-2xl bg-slate-50/50 hover:bg-white hover:border-teal-200 transition-all flex flex-col items-center justify-center text-center cursor-pointer">
              <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-5 bg-white rounded-xl shadow-md text-slate-300 mb-4 group-hover:text-teal-500 transition-colors"><Camera size={32} /></div>
              <h3 className="text-lg font-bold text-slate-900">Source Assets</h3>
              <p className="text-slate-400 text-xs font-medium mt-1">Select photography or intra-op video clips</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-4 sm:grid-cols-5 md:grid-cols-6 gap-3">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-xl overflow-hidden border border-slate-200 shadow-sm bg-slate-900">
                    {fileData.type === 'video' ? (
                      <div className="w-full h-full flex items-center justify-center bg-slate-800 text-white"><PlayCircle size={24} /></div>
                    ) : <img src={fileData.url} className="w-full h-full object-cover" alt="" />}
                    <button type="button" onClick={() => removeFile(i)} className="absolute top-1.5 right-1.5 p-1 bg-black/50 text-white rounded-lg opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500"><Trash2 size={12} /></button>
                  </div>
                ))}
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Research Tags</label>
                <input type="text" placeholder="e.g. Nerve, Artery..." className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 text-xs" value={customTags} onChange={e => setCustomTags(e.target.value)} />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Study Assignment</label>
                <select className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl font-bold text-slate-900 text-xs" value={selectedGroup} onChange={e => setSelectedGroup(e.target.value)}>
                  <option value="">Unassigned Pool</option>
                  {studyGroups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                </select>
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-teal-600 text-white font-bold py-4 rounded-xl shadow-lg flex items-center justify-center gap-3 text-base mt-4 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isUploading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={20} />}
              Commit to Google Drive
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

