import React, { useState } from 'react';
import { ArrowLeft, Plus, Download, X, Edit, Columns, CloudUpload, HardDrive, CheckCircle2, Camera } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  studyGroups: StudyGroup[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient, studyGroups }) => {
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showEditModal, setShowEditModal] = useState(false);
  const [isCompareMode, setIsCompareMode] = useState(false);
  const [editPatient, setEditPatient] = useState<Patient>({ ...patient });
  const [syncingIds, setSyncingIds] = useState<Set<string>>(new Set());

  const patientMedia = MOCK_MEDIA.filter(m => m.uhid === patient.uhid);
  const filteredMedia = patientMedia.filter(m => m.stage === activeStage);
  const preOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.PRE_OP);
  const postOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.POST_OP);

  const handleSyncToDrive = (mediaId: string) => {
    setSyncingIds(prev => new Set(prev).add(mediaId));
    setTimeout(() => {
      setSyncingIds(prev => { const next = new Set(prev); next.delete(mediaId); return next; });
      alert(`Synced to Drive.`);
    }, 1200);
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-400 hover:text-slate-900 transition-colors font-bold text-[11px] uppercase tracking-widest group">
          <ArrowLeft size={14} className="group-hover:-translate-x-1 transition-transform" /> Dashboard
        </button>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsCompareMode(!isCompareMode)}
            className={`flex items-center gap-2 px-4 py-2 rounded-xl text-xs font-bold transition-all ${isCompareMode ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-600 border border-slate-200'}`}
          >
            <Columns size={16} /> Compare
