        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-6">
        <div className="flex gap-5 items-center w-full lg:w-auto">
          <div className="w-16 h-16 bg-teal-600 text-white rounded-xl flex items-center justify-center text-2xl font-black shadow-lg shadow-teal-500/10">
            {patient.lastName[0]}{patient.firstName[0]}
          </div>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-xl font-black text-slate-900 tracking-tight">{patient.lastName}, {patient.firstName}</h1>
              <span className="bg-slate-50 px-3 py-1 rounded-lg font-mono font-bold text-[9px] text-slate-400 border border-slate-100">{patient.uhid}</span>
