          </div>
        </div>

        <div className="flex items-center gap-4 w-full lg:w-auto">
           <div className="flex-1 bg-slate-50 border border-slate-100 px-4 py-3 rounded-xl flex items-center gap-3 min-w-[200px]">
              <div className="text-teal-600"><HardDrive size={18} /></div>
              <p className="text-xs font-bold text-slate-700 italic truncate line-clamp-1">{patient.diagnosis}</p>
           </div>
           <button onClick={() => setShowEditModal(true)} className="text-slate-300 hover:text-slate-600 transition-colors">
              <Edit size={16} />
           </button>
        </div>
      </div>

      {!isCompareMode ? (
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
          <div className="flex bg-slate-50/50 p-1.5 gap-1">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-3 text-[10px] font-black tracking-widest uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-6">
            <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-5 gap-4">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative bg-slate-100 rounded-xl overflow-hidden aspect-square border border-slate-100">
                  <img src={m.url} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" alt="" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900/80 to-transparent opacity-0 group-hover:opacity-100 transition-all p-4 flex flex-col justify-between">
                    <div className="flex justify-between">
                       <div className={`p-1.5 rounded-lg backdrop-blur-md text-white border border-white/20 ${syncingIds.has(m.id) ? 'bg-teal-500 animate-pulse' : 'bg-black/20'}`}>
                          {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? <CheckCircle2 size={12} /> : <button onClick={(e) => { e.stopPropagation(); handleSyncToDrive(m.id); }}><CloudUpload size={12} /></button>}
                       </div>
                       <button className="p-1.5 bg-black/20 backdrop-blur-md rounded-lg text-white"><Download size={12} /></button>
