          <div className="space-y-4">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Pre-Operative</h3>
            <div className="bg-white p-4 rounded-2xl border border-slate-200 h-[500px] overflow-y-auto space-y-4 custom-scrollbar">
              {preOpMedia.map(m => <div key={m.id} className="rounded-xl overflow-hidden border border-slate-100"><img src={m.url} className="w-full object-cover" alt="" /></div>)}
              {preOpMedia.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-200"><Camera size={32} opacity={0.2} /></div>}
            </div>
          </div>
          <div className="space-y-4">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Post-Operative</h3>
            <div className="bg-white p-4 rounded-2xl border border-slate-200 h-[500px] overflow-y-auto space-y-4 custom-scrollbar">
              {postOpMedia.map(m => <div key={m.id} className="rounded-xl overflow-hidden border border-slate-100"><img src={m.url} className="w-full object-cover" alt="" /></div>)}
              {postOpMedia.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-200"><Camera size={32} opacity={0.2} /></div>}
            </div>
          </div>
        </div>
      )}

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-8 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6"><h2 className="text-lg font-black">Edit Record</h2><button onClick={() => setShowEditModal(false)}><X size={20} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-4">
              <div><label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID</label><input value={editPatient.uhid} onChange={e => setEditPatient({...editPatient, uhid: e.target.value})} className="w-full px-4 py-2 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs" /></div>
              <div className="grid grid-cols-2 gap-4">
                <div><label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">First Name</label><input value={editPatient.firstName} onChange={e => setEditPatient({...editPatient, firstName: e.target.value})} className="w-full px-4 py-2 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs" /></div>
                <div><label className="block text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">Last Name</label><input value={editPatient.lastName} onChange={e => setEditPatient({...editPatient, lastName: e.target.value})} className="w-full px-4 py-2 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs" /></div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-3.5 rounded-xl font-bold text-sm">Save Changes</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

