import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut, Fingerprint
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleGoogleAuth = () => {
    setIsLinked(true);
    // Auto-login after linking for smoother flow
    setTimeout(() => setIsLoggedIn(true), 800);
  };

  const handleAddPatient = (newPatient: Patient) => setPatients(prev => [newPatient, ...prev]);

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-[11px] font-bold uppercase tracking-wider">
              <X size={14} /> Close Study View
            </button>
            <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-transform hover:scale-105">
              <Edit3 size={12} className="inline mr-1" /> Edit Meta
            </button>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-xs font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 flex items-center gap-2">
              <HardDrive className="text-slate-400" size={14} />
              <p className="font-mono text-[9px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
            {enrolledPatients.map(p => (
              <div key={p.uhid} onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }} className="bg-white p-3 rounded-xl border border-slate-100 hover:border-teal-500 transition-all cursor-pointer flex items-center gap-3 group">
                <div className="w-8 h-8 bg-teal-600 text-white rounded-lg flex items-center justify-center text-xs font-black">{p.lastName[0]}{p.firstName[0]}</div>
                <div><h4 className="font-bold text-slate-900 text-xs">{p.lastName}, {p.firstName}</h4><p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p></div>
                <ChevronRight className="ml-auto text-slate-200 group-hover:text-teal-600" size={14} />
              </div>
            ))}
          </div>
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={patients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={patients} studyGroups={studyGroups} onUpload={d => { 
          // Update patient surgery date if provided during upload
          if (d.surgeryDate) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid ? { ...p, dateOfSurgery: d.surgeryDate } : p));
          }
          // Add to study group if assigned
          if (d.studyGroup) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup) ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] } : p));
          }
        }} />;
      case 'research': return (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div><h2 className="text-xl font-black text-slate-900 tracking-tight">Research Clusters</h2></div>
            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 border border-slate-200 bg-white px-3 py-1.5 rounded-lg text-[10px] font-black text-slate-700 uppercase tracking-widest hover:bg-slate-50 transition-all"><FileSpreadsheet size={14} /> Export Sheet</button>
              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-teal-700 transition-all"><Plus size={14} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-8 h-8 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-3 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={16} /></div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{group.name}</h3>
                <p className="text-slate-400 text-[11px] font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-3 border-t border-slate-50 mt-3">
                  <span className="text-teal-700 font-bold text-[9px] uppercase tracking-tighter">{patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <Edit3 size={12} className="text-slate-300 group-hover:text-teal-600" />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-xs w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-6">
            <OpusLogo size="md" className="mx-auto mb-3 shadow-lg rounded-xl" />
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[8px]">Operative Photo Unite and Store</p>
          </div>

          <div className="bg-white rounded-[2rem] p-8 border border-slate-100 shadow-xl">
            {!isLinked ? (
              <div className="space-y-4">
                <button 
                  onClick={handleGoogleAuth} 
                  className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Sign in with Google
                </button>
                <div className="flex items-center justify-center gap-2 text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2">
                  <Fingerprint size={14} /> Biometric Ready
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 bg-teal-50 p-3 rounded-xl border border-teal-100">
                  <img src="https://ui-avatars.com/api/?name=Dr+Smith&background=0d9488&color=fff" className="w-10 h-10 rounded-lg" alt="Profile" />
                  <div className="text-left">
                    <p className="font-bold text-slate-900 text-sm">Dr. Alexander Smith</p>
                    <p className="text-[9px] text-teal-600 font-black uppercase tracking-widest">Authenticated</p>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 text-slate-400">
                   <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-teal-500 animate-pulse">
                      <Fingerprint size={24} />
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.2em]">Touch to Unlock</p>
                </div>
              </div>
            )}
          </div>

          <p className="mt-6 text-[8px] text-slate-300 font-bold uppercase tracking-[0.4em]">
            Hand & Microvascular Surgery Core
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar activeView={activeView} setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md">
          <div className="flex items-center gap-2">
            <div className="lg:hidden"><OpusLogo size="sm" className="rounded-lg shadow-sm" /></div>
            <div className="hidden lg:block font-bold text-slate-300 text-[9px] uppercase tracking-[0.3em]">Dr. Smith • Microvascular Terminal</div>
          </div>
          <div className="flex items-center gap-3">
