  // Rule: Sort media by uploadedAt timestamp in descending order
  const patientMedia = [...MOCK_MEDIA]
    .filter(m => m.uhid === patient.uhid)
    .sort((a, b) => new Date(b.uploadedAt).getTime() - new Date(a.uploadedAt).getTime());

  const filteredMedia = patientMedia.filter(m => m.stage === activeStage);
  const preOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.PRE_OP);
  const postOpMedia = patientMedia.filter(m => m.stage === SurgicalStage.POST_OP);

  const handleSyncToDrive = (mediaId: string) => {
    setSyncingIds(prev => new Set(prev).add(mediaId));
    setTimeout(() => {
      setSyncingIds(prev => { const next = new Set(prev); next.delete(mediaId); return next; });
      alert(`Synced to Drive.`);
    }, 1200);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-400 hover:text-slate-900 transition-colors font-bold text-[9px] uppercase tracking-widest group">
          <ArrowLeft size={12} className="group-hover:-translate-x-1 transition-transform" /> Dashboard
        </button>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsCompareMode(!isCompareMode)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${isCompareMode ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-600 border border-slate-200'}`}
          >
            <Columns size={14} /> Compare Phases
          </button>
          <button onClick={onAddMedia} className="flex items-center gap-1.5 bg-teal-600 text-white px-3 py-1.5 rounded-lg font-black text-[9px] uppercase tracking-widest shadow-md">
            <Plus size={14} /> Capture Media
          </button>
        </div>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-4">
        <div className="flex gap-4 items-center w-full lg:w-auto">
          <div className="w-12 h-12 bg-teal-600 text-white rounded-xl flex items-center justify-center text-lg font-black">
            {patient.lastName[0]}{patient.firstName[0]}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-base font-black text-slate-900 tracking-tight">{patient.lastName}, {patient.firstName}</h1>
              <span className="bg-slate-50 px-2 py-0.5 rounded-md font-mono font-bold text-[8px] text-slate-400 border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest mt-0.5">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} • Surg: {patient.dateOfSurgery || 'Pending'}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 w-full lg:w-auto">
           <div className="flex-1 bg-slate-50 border border-slate-100 px-3 py-2 rounded-xl flex items-center gap-2 min-w-[200px]">
              <HardDrive size={14} className="text-teal-600" />
              <p className="text-[10px] font-bold text-slate-600 italic truncate line-clamp-1">{patient.diagnosis}</p>
           </div>
           <button onClick={() => setShowEditModal(true)} className="text-slate-300 hover:text-slate-600 p-1">
              <Edit size={14} />
           </button>
        </div>
      </div>

      {!isCompareMode ? (
        <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
          <div className="flex bg-slate-50/50 p-1 gap-1">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-2.5 text-[9px] font-black tracking-widest uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-4">
            <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative bg-slate-100 rounded-xl overflow-hidden aspect-square border border-slate-100">
                  <img src={m.url} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" alt="" />
                  <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all p-3 flex flex-col justify-between">
                    <div className="flex justify-between">
                       <div className={`p-1 rounded-md backdrop-blur-md text-white border border-white/20 ${syncingIds.has(m.id) ? 'bg-teal-500 animate-pulse' : 'bg-black/20'}`}>
                          {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? <CheckCircle2 size={10} /> : <button onClick={(e) => { e.stopPropagation(); handleSyncToDrive(m.id); }}><CloudUpload size={10} /></button>}
                       </div>
                       <button className="p-1 bg-black/20 backdrop-blur-md rounded-md text-white"><Download size={10} /></button>
                    </div>
                    <div className="space-y-1">
                       {m.notes && <p className="text-[7px] text-white font-bold truncate"><FileText size={8} className="inline mr-0.5" /> {m.notes}</p>}
                       <p className="text-[7px] text-teal-400 uppercase font-black tracking-widest">{new Date(m.uploadedAt).toLocaleDateString()}</p>
                    </div>
                  </div>
                </div>
              ))}
              {filteredMedia.length === 0 && (
                <div className="col-span-full py-16 text-center text-slate-200 font-black italic text-[10px] uppercase tracking-[0.2em] border border-dashed border-slate-100 rounded-2xl">
                   No clinical documentation
                </div>
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4 animate-in fade-in duration-300">
          <div className="space-y-2">
            <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Phase I: Pre-Op (Recent First)</h3>
            <div className="bg-white p-3 rounded-2xl border border-slate-200 h-[400px] overflow-y-auto space-y-3 custom-scrollbar">
              {preOpMedia.map(m => (
                <div key={m.id} className="rounded-xl overflow-hidden border border-slate-100 relative group">
                  <img src={m.url} className="w-full object-cover" alt="" />
                  <div className="absolute top-2 right-2 bg-black/50 backdrop-blur-md text-white text-[7px] px-1.5 py-0.5 rounded font-bold">{new Date(m.uploadedAt).toLocaleDateString()}</div>
                </div>
              ))}
              {preOpMedia.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-200"><Camera size={24} opacity={0.2} /></div>}
            </div>
          </div>
          <div className="space-y-2">
            <h3 className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1">Phase III: Post-Op (Recent First)</h3>
            <div className="bg-white p-3 rounded-2xl border border-slate-200 h-[400px] overflow-y-auto space-y-3 custom-scrollbar">
              {postOpMedia.map(m => (
                <div key={m.id} className="rounded-xl overflow-hidden border border-slate-100 relative group">
                  <img src={m.url} className="w-full object-cover" alt="" />
                  <div className="absolute top-2 right-2 bg-black/50 backdrop-blur-md text-white text-[7px] px-1.5 py-0.5 rounded font-bold">{new Date(m.uploadedAt).toLocaleDateString()}</div>
                </div>
              ))}
              {postOpMedia.length === 0 && <div className="h-full flex flex-col items-center justify-center text-slate-200"><Camera size={24} opacity={0.2} /></div>}
            </div>
          </div>
        </div>
      )}

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4"><h2 className="text-sm font-black uppercase tracking-widest">Update Master Record</h2><button onClick={() => setShowEditModal(false)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID</label><input value={editPatient.uhid} onChange={e => setEditPatient({...editPatient, uhid: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" /></div>
              <div className="grid grid-cols-2 gap-3">
                <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">First Name</label><input value={editPatient.firstName} onChange={e => setEditPatient({...editPatient, firstName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" /></div>
                <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Last Name</label><input value={editPatient.lastName} onChange={e => setEditPatient({...editPatient, lastName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" /></div>
                <div className="col-span-2">
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Surgery Date</label>
                  <input type="date" value={editPatient.dateOfSurgery} onChange={e => setEditPatient({...editPatient, dateOfSurgery: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
                </div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">Commit Changes</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React from 'react';
import { LayoutDashboard, Upload, Library, LogOut, X } from 'lucide-react';

interface SidebarProps {
  activeView: string;
  setActiveView: (view: string) => void;
  onLogout: () => void;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, setActiveView, onLogout, isOpen, setIsOpen }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'upload', label: 'Upload Media', icon: Upload },
    { id: 'research', label: 'Study Group', icon: Library },
  ];

  return (
    <>
      {isOpen && (
        <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsOpen(false)} />
      )}

      <div className={`fixed left-0 top-0 h-screen w-64 bg-white border-r border-slate-100 flex flex-col z-50 transition-transform duration-300 ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-6 flex items-center justify-between border-b border-slate-50">
          <div className="flex items-center gap-2">
            <span className="font-black text-2xl tracking-tighter italic text-teal-600">OPUS</span>
          </div>
          <button className="lg:hidden text-slate-400" onClick={() => setIsOpen(false)}><X size={20} /></button>
        </div>

        <nav className="flex-1 mt-6 px-4 space-y-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => { setActiveView(item.id); setIsOpen(false); }}
              className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl transition-all text-sm font-bold ${
                activeView === item.id 
                  ? 'bg-teal-600 text-white shadow-md shadow-teal-500/10' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'
              }`}
            >
              <item.icon size={18} />
              <span>{item.label}</span>
            </button>
          ))}
        </nav>

        <div className="p-4 border-t border-slate-50">
          <button 
            onClick={onLogout}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all text-xs font-bold uppercase tracking-widest"
          >
            <LogOut size={16} />
            <span>Sign Out</span>
          </button>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut, Fingerprint, FileText
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleGoogleAuth = () => {
    setIsLinked(true);
    // Auto-login after linking for smoother flow
    setTimeout(() => setIsLoggedIn(true), 800);
  };

  const handleAddPatient = (newPatient: Patient) => setPatients(prev => [newPatient, ...prev]);

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleExportAction = () => {
    if (exportSelection.length === 0) {
      alert("Please select at least one study group to export.");
      return;
    }
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      setShowExportModal(false);
      setExportSelection([]);
      alert(`Export Successful: Clinical Data compiled for ${exportSelection.length} groups. Downloaded as PDF and Excel (.xlsx) to your research drive.`);
    }, 2000);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-[11px] font-bold uppercase tracking-wider">
              <X size={14} /> Close Study View
            </button>
            <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-transform hover:scale-105">
              <Edit3 size={12} className="inline mr-1" /> Edit Meta
            </button>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-xs font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 flex items-center gap-2">
              <HardDrive className="text-slate-400" size={14} />
              <p className="font-mono text-[9px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
            {enrolledPatients.map(p => (
              <div key={p.uhid} onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }} className="bg-white p-3 rounded-xl border border-slate-100 hover:border-teal-500 transition-all cursor-pointer flex items-center gap-3 group">
                <div className="w-8 h-8 bg-teal-600 text-white rounded-lg flex items-center justify-center text-xs font-black">{p.lastName[0]}{p.firstName[0]}</div>
                <div><h4 className="font-bold text-slate-900 text-xs">{p.lastName}, {p.firstName}</h4><p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p></div>
                <ChevronRight className="ml-auto text-slate-200 group-hover:text-teal-600" size={14} />
              </div>
            ))}
          </div>
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={patients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={patients} studyGroups={studyGroups} onUpload={d => { 
          // Update patient surgery date if provided during upload
          if (d.surgeryDate) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid ? { ...p, dateOfSurgery: d.surgeryDate } : p));
          }
          // Add to study group if assigned
          if (d.studyGroup) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup) ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] } : p));
          }
        }} />;
      case 'research': return (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div><h2 className="text-xl font-black text-slate-900 tracking-tight">Research Clusters</h2></div>
            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 border border-slate-200 bg-white px-3 py-1.5 rounded-lg text-[10px] font-black text-slate-700 uppercase tracking-widest hover:bg-slate-50 transition-all"><FileSpreadsheet size={14} /> Export Sheet</button>
              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-teal-700 transition-all"><Plus size={14} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-8 h-8 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-3 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={16} /></div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{group.name}</h3>
                <p className="text-slate-400 text-[11px] font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-3 border-t border-slate-50 mt-3">
                  <span className="text-teal-700 font-bold text-[9px] uppercase tracking-tighter">{patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <Edit3 size={12} className="text-slate-300 group-hover:text-teal-600" />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-xs w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-6">
            <OpusLogo size="md" className="mx-auto mb-3 shadow-lg rounded-xl" />
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[8px]">Operative Photo Unite and Store</p>
          </div>

          <div className="bg-white rounded-[2rem] p-8 border border-slate-100 shadow-xl">
            {!isLinked ? (
              <div className="space-y-4">
                <button 
                  onClick={handleGoogleAuth} 
                  className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Sign in with Google
                </button>
                <div className="flex items-center justify-center gap-2 text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2">
                  <Fingerprint size={14} /> Biometric Ready
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 bg-teal-50 p-3 rounded-xl border border-teal-100">
                  <img src="https://ui-avatars.com/api/?name=Dr+Smith&background=0d9488&color=fff" className="w-10 h-10 rounded-lg" alt="Profile" />
                  <div className="text-left">
                    <p className="font-bold text-slate-900 text-sm">Dr. Alexander Smith</p>
                    <p className="text-[9px] text-teal-600 font-black uppercase tracking-widest">Authenticated</p>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 text-slate-400">
                   <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-teal-500 animate-pulse">
                      <Fingerprint size={24} />
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.2em]">Touch to Unlock</p>
                </div>
              </div>
            )}
          </div>

          <p className="mt-6 text-[8px] text-slate-300 font-bold uppercase tracking-[0.4em]">
            Hand & Microvascular Surgery Core
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar activeView={activeView} setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md">
          <div className="flex items-center gap-2">
            <div className="lg:hidden"><OpusLogo size="sm" className="rounded-lg shadow-sm" /></div>
