export default App;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut, Fingerprint, FileText,
  Download
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleGoogleAuth = () => {
    setIsLinked(true);
    // Auto-login after linking for smoother flow
    setTimeout(() => setIsLoggedIn(true), 800);
  };

  const handleAddPatient = (newPatient: Patient) => setPatients(prev => [newPatient, ...prev]);

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleExportAction = () => {
    if (exportSelection.length === 0) {
      alert("Please select at least one study group to export.");
      return;
    }
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      setShowExportModal(false);
      setExportSelection([]);
      alert(`Export Successful: Clinical Data compiled for ${exportSelection.length} groups. Downloaded as PDF and Excel (.xlsx) to your research drive.`);
    }, 2000);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-[11px] font-bold uppercase tracking-wider">
              <X size={14} /> Close Study View
            </button>
            <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-transform hover:scale-105">
              <Edit3 size={12} className="inline mr-1" /> Edit Meta
            </button>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-xs font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 flex items-center gap-2">
              <HardDrive className="text-slate-400" size={14} />
              <p className="font-mono text-[9px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
            {enrolledPatients.map(p => (
              <div key={p.uhid} onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }} className="bg-white p-3 rounded-xl border border-slate-100 hover:border-teal-500 transition-all cursor-pointer flex items-center gap-3 group">
                <div className="w-8 h-8 bg-teal-600 text-white rounded-lg flex items-center justify-center text-xs font-black">{p.lastName[0]}{p.firstName[0]}</div>
