              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-teal-700 transition-all"><Plus size={14} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-8 h-8 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-3 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={16} /></div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{group.name}</h3>
                <p className="text-slate-400 text-[11px] font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-3 border-t border-slate-50 mt-3">
                  <span className="text-teal-700 font-bold text-[9px] uppercase tracking-tighter">{patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <Edit3 size={12} className="text-slate-300 group-hover:text-teal-600" />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-xs w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-6">
            <OpusLogo size="md" className="mx-auto mb-3 shadow-lg rounded-xl" />
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[8px]">Operative Photo Unite and Store</p>
          </div>

          <div className="bg-white rounded-[2rem] p-8 border border-slate-100 shadow-xl">
            {!isLinked ? (
              <div className="space-y-4">
                <button 
                  onClick={handleGoogleAuth} 
                  className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Sign in with Google
                </button>
                <div className="flex items-center justify-center gap-2 text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2">
                  <Fingerprint size={14} /> Biometric Ready
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 bg-teal-50 p-3 rounded-xl border border-teal-100">
                  <img src="https://ui-avatars.com/api/?name=Dr+Smith&background=0d9488&color=fff" className="w-10 h-10 rounded-lg" alt="Profile" />
                  <div className="text-left">
                    <p className="font-bold text-slate-900 text-sm">Dr. Alexander Smith</p>
                    <p className="text-[9px] text-teal-600 font-black uppercase tracking-widest">Authenticated</p>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 text-slate-400">
                   <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-teal-500 animate-pulse">
                      <Fingerprint size={24} />
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.2em]">Touch to Unlock</p>
                </div>
              </div>
            )}
          </div>

          <p className="mt-6 text-[8px] text-slate-300 font-bold uppercase tracking-[0.4em]">
            Hand & Microvascular Surgery Core
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar activeView={activeView} setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md">
          <div className="flex items-center gap-2">
            <div className="lg:hidden"><OpusLogo size="sm" className="rounded-lg shadow-sm" /></div>
            <div className="hidden lg:block font-bold text-slate-300 text-[9px] uppercase tracking-[0.3em]">Dr. Smith • Microvascular Terminal</div>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5 bg-teal-50 px-2 py-1 rounded-lg border border-teal-100">
              <div className="w-1 h-1 rounded-full bg-teal-500 animate-pulse"></div>
              <span className="text-[8px] font-black text-teal-700 uppercase">Drive Secure</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-600"><Menu size={18} /></button>
          </div>
        </div>

        <div className="px-6 py-4 max-w-[1200px] mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Initialize Study Modal */}
      {showAddStudyModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-sm uppercase tracking-widest"><h2>Initialize Study</h2><button onClick={() => setShowAddStudyModal(false)}><X size={16} /></button></div>
            <form onSubmit={handleCreateStudy} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Study Name</label><input required value={newStudy.name} onChange={e => setNewStudy({...newStudy, name: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs outline-none focus:border-teal-500" placeholder="e.g. Nerve Repair 2024" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={newStudy.description} onChange={e => setNewStudy({...newStudy, description: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs outline-none focus:border-teal-500 resize-none" /></div>
