      )}

      {/* Export Selection Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest">
              <h2>Select Groups to Export</h2>
              <button onClick={() => setShowExportModal(false)} className="text-slate-400 hover:text-slate-600"><X size={16} /></button>
            </div>
            <div className="space-y-2 mb-6 max-h-60 overflow-y-auto pr-1">
              {studyGroups.map(group => (
                <button 
                  key={group.id} 
                  onClick={() => setExportSelection(prev => prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id])} 
                  className={`w-full text-left p-3 rounded-xl border transition-all flex items-center justify-between text-[11px] ${exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 hover:border-slate-200'}`}
                >
                  <span>{group.name}</span>
                  {exportSelection.includes(group.id) ? <CheckCircle2 size={14} /> : <div className="w-3.5 h-3.5 rounded-full border border-slate-200" />}
                </button>
              ))}
            </div>
            <button 
              onClick={handleExportAction} 
              disabled={isExporting}
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest hover:bg-teal-700 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isExporting ? <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Download size={16} />}
              Generate Clinical Report (.pdf / .xlsx)
            </button>
          </div>
        </div>
      )}

      {editingStudyGroup && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4"><h2 className="text-sm font-bold">Edit Study</h2><button onClick={() => setEditingStudyGroup(null)}><X size={16} /></button></div>
