            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

export enum SurgicalStage {
  PRE_OP = 'Pre-operative',
  INTRA_OP = 'Intra-operative',
  POST_OP = 'Post-operative'
}

export enum MediaType {
  IMAGE = 'image',
  VIDEO = 'video'
}

export enum StorageLocation {
  GOOGLE_DRIVE = 'Google Drive',
  LOCAL = 'Local Storage'
}

export interface StudyGroup {
  id: string;
  name: string;
  description: string;
  patientCount: number;
  driveFolderId?: string;
  lastSync?: string;
}

export interface SurgeryEvent {
  id: string;
  title: string;
  date: string;
  notes?: string;
}

export interface MediaEntry {
  id: string;
  uhid: string;
  surgeryId: string; // Links to a specific surgery event
  stage: SurgicalStage;
  type: MediaType;
  url: string;
  thumbnailUrl?: string;
  uploadedAt: string;
  notes?: string;
  tags: string[];
  storageLocation: StorageLocation;
}

export interface Patient {
  uhid: string;
  firstName: string;
  lastName: string;
  ageYears: number;
  ageMonths?: number;
  diagnosis: string;
  primarySurgeon: string;
  studyGroupIds: string[];
  createdAt: string;
  surgeries: SurgeryEvent[]; // Historical list of surgeries
  dateOfSurgery?: string; // Most recent surgery date
}

export interface AuthUser {
  id: string;
  name: string;
  role: 'Surgeon' | 'Fellow' | 'Researcher';
  email: string;
}

import React, { useState } from 'react';
import { ArrowLeft, Plus, Download, X, Edit, Columns, CloudUpload, HardDrive, CheckCircle2, Camera, FileText, ChevronDown, ChevronRight } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, MediaEntry, SurgeryEvent } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient }) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showEditModal, setShowEditModal] = useState(false);
  const [isCompareMode, setIsCompareMode] = useState(false);
  const [editPatient, setEditPatient] = useState<Patient>({ ...patient });
  const [syncingIds, setSyncingIds] = useState<Set<string>>(new Set());

  const patientMedia = [...MOCK_MEDIA]
    .filter(m => m.uhid === patient.uhid)
    .sort((a, b) => new Date(b.uploadedAt).getTime() - new Date(a.uploadedAt).getTime());

  const filteredMedia = patientMedia.filter(m => m.surgeryId === activeSurgeryId && m.stage === activeStage);
  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);

  const handleDownload = async (media: MediaEntry) => {
    // Simulate high-quality download
    try {
      const response = await fetch(media.url);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `OPUS_${patient.uhid}_${media.stage}_${media.id}.jpg`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (e) {
      alert("High-quality master download failed. Retrying...");
    }
  };

  const handleSyncToDrive = (mediaId: string) => {
    setSyncingIds(prev => new Set(prev).add(mediaId));
    setTimeout(() => {
      setSyncingIds(prev => { const next = new Set(prev); next.delete(mediaId); return next; });
    }, 1200);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-400 hover:text-slate-900 transition-colors font-bold text-[9px] uppercase tracking-widest group">
          <ArrowLeft size={12} className="group-hover:-translate-x-1 transition-transform" /> Dashboard
        </button>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsCompareMode(!isCompareMode)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${isCompareMode ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-600 border border-slate-200'}`}
          >
            <Columns size={14} /> Compare Phases
          </button>
          <button onClick={onAddMedia} className="flex items-center gap-1.5 bg-teal-600 text-white px-3 py-1.5 rounded-lg font-black text-[9px] uppercase tracking-widest shadow-md">
            <Plus size={14} /> Capture Media
          </button>
        </div>
      </div>

      {/* Header Info */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-4">
        <div className="flex gap-4 items-center w-full lg:w-auto">
          <div className="w-12 h-12 bg-teal-600 text-white rounded-xl flex items-center justify-center text-lg font-black">
            {patient.lastName[0]}{patient.firstName[0]}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-base font-black text-slate-900 tracking-tight">{patient.lastName}, {patient.firstName}</h1>
              <span className="bg-slate-50 px-2 py-0.5 rounded-md font-mono font-bold text-[8px] text-slate-400 border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest mt-0.5">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} • {patient.surgeries.length} Historical Procedures
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 w-full lg:w-auto">
           <div className="flex-1 bg-slate-50 border border-slate-100 px-3 py-2 rounded-xl flex items-center gap-2 min-w-[200px]">
              <HardDrive size={14} className="text-teal-600" />
              <p className="text-[10px] font-bold text-slate-600 italic truncate line-clamp-1">{patient.diagnosis}</p>
           </div>
           <button onClick={() => setShowEditModal(true)} className="text-slate-300 hover:text-slate-600 p-1 transition-colors">
              <Edit size={14} />
           </button>
        </div>
      </div>

      {/* Surgery Selection Timeline */}
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} 
            onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-4 py-2 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
          >
            <div className="flex flex-col items-start">
               <span className="opacity-60 text-[7px] mb-0.5">{s.date}</span>
               {s.title}
            </div>
          </button>
        ))}
      </div>

      {/* Media View */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="flex bg-slate-50/50 p-1 gap-1">
          {Object.values(SurgicalStage).map(stage => (
            <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-2.5 text-[9px] font-black tracking-widest uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
              {stage}
            </button>
          ))}
        </div>
        <div className="p-4">
          <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-6 gap-3">
            {filteredMedia.map(m => (
              <div key={m.id} className="group relative bg-slate-100 rounded-xl overflow-hidden aspect-square border border-slate-100">
                <img src={m.url} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" alt="" />
                <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all p-3 flex flex-col justify-between">
                  <div className="flex justify-between">
                     <div className={`p-1 rounded-md backdrop-blur-md text-white border border-white/20 ${syncingIds.has(m.id) ? 'bg-teal-500 animate-pulse' : 'bg-black/20'}`}>
                        {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? <CheckCircle2 size={10} /> : <button onClick={(e) => { e.stopPropagation(); handleSyncToDrive(m.id); }}><CloudUpload size={10} /></button>}
                     </div>
                     <button onClick={(e) => { e.stopPropagation(); handleDownload(m); }} className="p-1 bg-white/20 backdrop-blur-md rounded-md text-white hover:bg-white/40 transition-colors">
                        <Download size={10} />
                     </button>
                  </div>
                  <div className="space-y-1">
                     {m.notes && <p className="text-[7px] text-white font-bold truncate"><FileText size={8} className="inline mr-0.5" /> {m.notes}</p>}
                     <p className="text-[7px] text-teal-400 uppercase font-black tracking-widest">{new Date(m.uploadedAt).toLocaleDateString()}</p>
                  </div>
                </div>
              </div>
            ))}
            {filteredMedia.length === 0 && (
              <div className="col-span-full py-16 text-center text-slate-200 font-black italic text-[10px] uppercase tracking-[0.2em] border border-dashed border-slate-100 rounded-2xl">
                 No documentation for this phase
              </div>
            )}
          </div>
        </div>
      </div>

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest"><h2>Edit Clinical Core</h2><button onClick={() => setShowEditModal(false)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID</label><input value={editPatient.uhid} readOnly className="w-full px-3 py-1.5 bg-slate-100 rounded-lg border border-slate-100 font-bold text-[11px] outline-none" /></div>
              <div className="grid grid-cols-2 gap-3">
                <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">First Name</label><input value={editPatient.firstName} onChange={e => setEditPatient({...editPatient, firstName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" /></div>
                <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Last Name</label><input value={editPatient.lastName} onChange={e => setEditPatient({...editPatient, lastName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" /></div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">Save Patient Data</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React, { useState } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, Sparkles, CloudUpload, FileText, Calendar, Plus } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup, SurgeryEvent } from '../types';
import { analyzeSurgicalImage } from '../services/geminiService';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
  base64?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [notes, setNotes] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = patients.find(p => p.uhid === selectedPatientId);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(',')[1] || '');
      reader.onerror = error => reject(error);
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      const newPreviews: PreviewFile[] = [];
      for (const file of files) {
        const type = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);
        const base64 = type === 'image' ? await fileToBase64(file) : undefined;
        newPreviews.push({ url, file, type, base64 });
      }
      setPreviewFiles(prev => [...prev, ...newPreviews]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;

    // Validate surgery link
    if (!surgeryId && !showNewSurgeryForm) {
      alert("Please select or register a surgery event.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        surgeryId: showNewSurgeryForm ? `new_${Date.now()}` : surgeryId,
        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate } : null,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        tags: customTags.split(',').filter(t => t.trim()),
        notes,
        timestamp: new Date().toISOString()
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setCustomTags('');
      setNotes('');
      setSelectedPatientId('');
      setSurgeryId('');
      setShowNewSurgeryForm(false);
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xs mx-auto py-12 text-center space-y-6 animate-in zoom-in-95">
        <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center mx-auto shadow-sm border border-teal-100">
          <CheckCircle2 size={32} />
        </div>
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-900 tracking-tight italic">Vault Entry Created</h2>
          <p className="text-slate-400 font-medium text-[10px] uppercase tracking-widest">Locked in Cloud Repository</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg transition-all active:scale-[0.98] text-[10px] uppercase tracking-widest">
          Begin New Capture
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-xl font-black text-slate-900 tracking-tight">Intake Portal</h1>
        <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest">Longitudinal Operative Intake</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
        <div className="lg:col-span-4 space-y-4">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-900 flex items-center gap-2">
              <Database size={14} className="text-teal-600" /> Intake Context
            </h2>
            <div>
              <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Target Patient *</label>
              <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Search patient...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-3 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center">
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest">Surgery Event</label>
                  <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-black text-teal-600 uppercase flex items-center gap-1">
                    {showNewSurgeryForm ? 'Select Existing' : <><Plus size={10} /> Register New Surgery</>}
                  </button>
                </div>

                {!showNewSurgeryForm ? (
                  <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                    <option value="">Select Procedure...</option>
                    {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                  </select>
                ) : (
                  <div className="space-y-2 p-3 bg-teal-50/50 rounded-xl border border-teal-100">
                     <input required placeholder="Procedure Title (e.g. Nerve Graft)" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                     <input required type="date" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                  </div>
                )}

                <div>
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-1">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-3 py-2 rounded-lg border text-[10px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                        {s}{stage === s && <CheckCircle2 size={10} />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-8 space-y-4">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6 flex flex-col">
            <div className="group relative p-8 border-2 border-dashed border-slate-100 rounded-xl bg-slate-50/30 hover:bg-white hover:border-teal-100 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[160px]">
              <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-3 bg-white rounded-lg shadow-sm text-slate-300 mb-3 group-hover:text-teal-500 transition-colors"><Camera size={24} /></div>
              <h3 className="text-sm font-bold text-slate-900">Operative Media</h3>
              <p className="text-slate-400 text-[9px] font-medium mt-0.5 uppercase tracking-widest">High-quality master files for archival</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-6 sm:grid-cols-8 gap-2">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-lg overflow-hidden border border-slate-200 bg-slate-900">
                    {fileData.type === 'video' ? (
                      <div className="w-full h-full flex items-center justify-center bg-slate-800 text-white"><PlayCircle size={16} /></div>
                    ) : <img src={fileData.url} className="w-full h-full object-cover" alt="" />}
                    <button type="button" onClick={() => removeFile(i)} className="absolute top-1 right-1 p-1 bg-black/50 text-white rounded-md opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={10} /></button>
                  </div>
                ))}
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <div className="col-span-2">
                <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1"><FileText size={10} /> Operative Observation</label>
                <textarea value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-20 font-bold text-xs outline-none focus:border-teal-500 resize-none" placeholder="Enter findings or procedure steps..." />
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-[0.2em] mt-2 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isUploading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={16} />}
              Commit to Secure Vault
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

