        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate } : null,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        tags: customTags.split(',').filter(t => t.trim()),
        notes,
        timestamp: new Date().toISOString()
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
      setCustomTags('');
      setNotes('');
      setSelectedPatientId('');
      setSurgeryId('');
      setShowNewSurgeryForm(false);
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xs mx-auto py-12 text-center space-y-6 animate-in zoom-in-95">
        <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center mx-auto shadow-sm border border-teal-100">
          <CheckCircle2 size={32} />
        </div>
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-900 tracking-tight italic">Vault Entry Created</h2>
          <p className="text-slate-400 font-medium text-[10px] uppercase tracking-widest">Locked in Cloud Repository</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg transition-all active:scale-[0.98] text-[10px] uppercase tracking-widest">
          Begin New Capture
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-xl font-black text-slate-900 tracking-tight">Intake Portal</h1>
        <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest">Longitudinal Operative Intake</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
        <div className="lg:col-span-4 space-y-4">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-900 flex items-center gap-2">
              <Database size={14} className="text-teal-600" /> Intake Context
            </h2>
            <div>
              <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Target Patient *</label>
              <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Search patient...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-3 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center">
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest">Surgery Event</label>
                  <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-black text-teal-600 uppercase flex items-center gap-1">
                    {showNewSurgeryForm ? 'Select Existing' : <><Plus size={10} /> Register New Surgery</>}
                  </button>
                </div>

                {!showNewSurgeryForm ? (
                  <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                    <option value="">Select Procedure...</option>
                    {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                  </select>
                ) : (
                  <div className="space-y-2 p-3 bg-teal-50/50 rounded-xl border border-teal-100">
                     <input required placeholder="Procedure Title (e.g. Nerve Graft)" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                     <input required type="date" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                  </div>
                )}

                <div>
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-1">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-3 py-2 rounded-lg border text-[10px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                        {s}{stage === s && <CheckCircle2 size={10} />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-8 space-y-4">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6 flex flex-col">
            <div className="group relative p-8 border-2 border-dashed border-slate-100 rounded-xl bg-slate-50/30 hover:bg-white hover:border-teal-100 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[160px]">
              <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-3 bg-white rounded-lg shadow-sm text-slate-300 mb-3 group-hover:text-teal-500 transition-colors"><Camera size={24} /></div>
              <h3 className="text-sm font-bold text-slate-900">Operative Media</h3>
              <p className="text-slate-400 text-[9px] font-medium mt-0.5 uppercase tracking-widest">High-quality master files for archival</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-6 sm:grid-cols-8 gap-2">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-lg overflow-hidden border border-slate-200 bg-slate-900">
                    {fileData.type === 'video' ? (
                      <div className="w-full h-full flex items-center justify-center bg-slate-800 text-white"><PlayCircle size={16} /></div>
                    ) : <img src={fileData.url} className="w-full h-full object-cover" alt="" />}
                    <button type="button" onClick={() => removeFile(i)} className="absolute top-1 right-1 p-1 bg-black/50 text-white rounded-md opacity-0 group-hover:opacity-100 transition-all"><Trash2 size={10} /></button>
                  </div>
                ))}
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <div className="col-span-2">
                <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1"><FileText size={10} /> Operative Observation</label>
                <textarea value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-20 font-bold text-xs outline-none focus:border-teal-500 resize-none" placeholder="Enter findings or procedure steps..." />
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-[0.2em] mt-2 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isUploading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={16} />}
              Commit to Secure Vault
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

import React, { useState } from 'react';
import { Search, Plus, User, X, Tag, Calendar } from 'lucide-react';
import { Patient, StudyGroup, SurgeryEvent } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: StudyGroup[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, studyGroups, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '',
    firstName: '',
    lastName: '',
    ageYears: 0,
    ageMonths: 0,
    diagnosis: '',
    primarySurgeon: 'Dr. Smith',
    studyGroupIds: [],
    dateOfSurgery: ''
  });

  const filteredPatients = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.firstName.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.lastName.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.firstName) {
      alert("UHID and First Name are mandatory.");
      return;
    }

    // Initialize surgeries array
    const surgeries: SurgeryEvent[] = [];
    if (newPatient.dateOfSurgery) {
      surgeries.push({
        id: `surg_${Date.now()}`,
        title: 'Planned Procedure',
        date: newPatient.dateOfSurgery,
        notes: 'Automatically generated during registration.'
      });
    }

    const patientToAdd: Patient = {
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries: surgeries // Crucial: Fixes the crash in PatientDetails
    };

    onAddPatient(patientToAdd);
    setShowModal(false);
    setNewPatient({
      uhid: '', firstName: '', lastName: '', ageYears: 0, ageMonths: 0,
      diagnosis: '', primarySurgeon: 'Dr. Smith', studyGroupIds: [], dateOfSurgery: ''
    });
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-xl font-black text-slate-900 tracking-tight">Patient Records</h1>
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.2em]">Institutional Longitudinal Database</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-2 bg-teal-600 text-white px-4 py-2 rounded-lg hover:bg-teal-700 transition-all text-[10px] font-black uppercase tracking-widest shadow-md"
        >
          <Plus size={14} /> Register Patient
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
        <input 
          type="text"
          placeholder="Search UHID, name, diagnosis..."
          className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:border-teal-500 transition-all text-xs font-medium shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {filteredPatients.map(p => (
          <div 
            key={p.uhid}
            onClick={() => onSelectPatient(p)}
            className="bg-white p-4 rounded-2xl border border-slate-100 hover:border-teal-500 transition-all cursor-pointer group shadow-sm"
          >
            <div className="flex justify-between items-start mb-2">
              <div className="w-8 h-8 bg-slate-50 rounded-lg flex items-center justify-center text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 transition-colors">
                <User size={16} />
              </div>
              <span className="font-mono font-bold text-[8px] text-slate-300 tracking-wider">
                {p.uhid}
              </span>
            </div>
            <h3 className="font-bold text-slate-900 text-xs mb-0.5 truncate">{p.lastName}, {p.firstName}</h3>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-tight mb-2">
              Age: {p.ageYears}y {p.ageYears <= 2 ? `${p.ageMonths || 0}m` : ''}
            </p>
            <div className="bg-slate-50 p-2 rounded-lg mb-2 h-10 overflow-hidden">
              <p className="text-slate-500 text-[10px] font-medium leading-tight line-clamp-2 italic">"{p.diagnosis}"</p>
            </div>

            <div className="flex justify-between items-center">
              {p.dateOfSurgery ? (
                <div className="text-[8px] font-black text-orange-600 uppercase tracking-widest flex items-center gap-1">
                  <Calendar size={10} /> {p.dateOfSurgery}
                </div>
              ) : (
                <div className="text-[8px] font-bold text-slate-300 uppercase tracking-widest">Surg: TBD</div>
              )}
              <div className="flex gap-1">
                {p.studyGroupIds.slice(0, 1).map(id => (
                  <span key={id} className="bg-teal-50 text-teal-600 text-[7px] font-black px-1.5 py-0.5 rounded border border-teal-100 uppercase">{id}</span>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-5 py-3 border-b border-slate-50 flex justify-between items-center bg-slate-50">
              <h2 className="text-xs font-black uppercase tracking-widest text-slate-900">Patient Registration</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400"><X size={16} /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-5 space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div className="col-span-2">
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID *</label>
                  <input required value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} type="text" className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg outline-none focus:border-teal-500 transition-all text-xs font-bold" placeholder="HOSP-XXXXX" />
                </div>
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">First Name *</label>
                  <input required value={newPatient.firstName} onChange={e => setNewPatient({...newPatient, firstName: e.target.value})} type="text" className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg outline-none focus:border-teal-500 text-xs font-bold" />
                </div>
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Last Name</label>
                  <input value={newPatient.lastName} onChange={e => setNewPatient({...newPatient, lastName: e.target.value})} type="text" className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg outline-none focus:border-teal-500 text-xs font-bold" />
                </div>
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Age (Years)</label>
                  <input type="number" value={newPatient.ageYears} onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold" />
                </div>
                {/* Conditional Age in Months logic */}
                {newPatient.ageYears !== undefined && newPatient.ageYears <= 2 && (
                  <div className="animate-in slide-in-from-left-2 duration-300">
                    <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Age (Months)</label>
                    <input type="number" max="24" value={newPatient.ageMonths} onChange={e => setNewPatient({...newPatient, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 bg-teal-50 border border-teal-100 rounded-lg text-xs font-bold" />
                  </div>
                )}
                <div className="col-span-2">
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Date of Surgery (Optional)</label>
                  <input type="date" value={newPatient.dateOfSurgery} onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold" />
                </div>
                <div className="col-span-2">
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Assign Study Cluster</label>
                  <select 
                    value={newPatient.studyGroupIds?.[0] || ''} 
                    onChange={e => setNewPatient({...newPatient, studyGroupIds: e.target.value ? [e.target.value] : []})}
                    className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold"
                  >
                    <option value="">No specific group</option>
                    {studyGroups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Clinical Diagnosis</label>
                <textarea required value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 outline-none focus:border-teal-500 text-xs font-bold resize-none" />
              </div>

              <button type="submit" className="w-full bg-teal-600 text-white font-black py-3 rounded-xl hover:bg-teal-700 transition-all shadow-md text-[11px] uppercase tracking-[0.2em]">
                Commit to Vault
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut, Fingerprint, FileText,
  Download
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleGoogleAuth = () => {
    setIsLinked(true);
    // Auto-login after linking for smoother flow
    setTimeout(() => setIsLoggedIn(true), 800);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient); // Auto-navigate to the new patient's dashboard
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleExportAction = () => {
    if (exportSelection.length === 0) {
      alert("Please select at least one study group to export.");
      return;
    }
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      setShowExportModal(false);
      setExportSelection([]);
      alert(`Export Successful: Clinical Data compiled for ${exportSelection.length} groups. Downloaded as PDF and Excel (.xlsx) to your research drive.`);
    }, 2000);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-[11px] font-bold uppercase tracking-wider">
              <X size={14} /> Close Study View
            </button>
            <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-transform hover:scale-105">
              <Edit3 size={12} className="inline mr-1" /> Edit Meta
            </button>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-xs font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 flex items-center gap-2">
              <HardDrive className="text-slate-400" size={14} />
              <p className="font-mono text-[9px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
            {enrolledPatients.map(p => (
              <div key={p.uhid} onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }} className="bg-white p-3 rounded-xl border border-slate-100 hover:border-teal-500 transition-all cursor-pointer flex items-center gap-3 group">
                <div className="w-8 h-8 bg-teal-600 text-white rounded-lg flex items-center justify-center text-xs font-black">{p.lastName[0]}{p.firstName[0]}</div>
                <div><h4 className="font-bold text-slate-900 text-xs">{p.lastName}, {p.firstName}</h4><p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p></div>
                <ChevronRight className="ml-auto text-slate-200 group-hover:text-teal-600" size={14} />
              </div>
            ))}
          </div>
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={patients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={patients} studyGroups={studyGroups} onUpload={d => { 
          // Update patient surgery date if provided during upload
          if (d.surgeryDate) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid ? { ...p, dateOfSurgery: d.surgeryDate } : p));
          }
          // Add to study group if assigned
          if (d.studyGroup) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup) ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] } : p));
          }
        }} />;
      case 'research': return (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div><h2 className="text-xl font-black text-slate-900 tracking-tight">Research Clusters</h2></div>
            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 border border-slate-200 bg-white px-3 py-1.5 rounded-lg text-[10px] font-black text-slate-700 uppercase tracking-widest hover:bg-slate-50 transition-all"><FileSpreadsheet size={14} /> Export Sheet</button>
              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-teal-700 transition-all"><Plus size={14} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-8 h-8 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-3 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={16} /></div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{group.name}</h3>
                <p className="text-slate-400 text-[11px] font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-3 border-t border-slate-50 mt-3">
                  <span className="text-teal-700 font-bold text-[9px] uppercase tracking-tighter">{patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <Edit3 size={12} className="text-slate-300 group-hover:text-teal-600" />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-xs w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-6">
            <OpusLogo size="md" className="mx-auto mb-3 shadow-lg rounded-xl" />
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[8px]">Operative Photo Unite and Store</p>
          </div>

          <div className="bg-white rounded-[2rem] p-8 border border-slate-100 shadow-xl">
            {!isLinked ? (
              <div className="space-y-4">
                <button 
                  onClick={handleGoogleAuth} 
                  className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Sign in with Google
                </button>
                <div className="flex items-center justify-center gap-2 text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2">
                  <Fingerprint size={14} /> Biometric Ready
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 bg-teal-50 p-3 rounded-xl border border-teal-100">
                  <img src="https://ui-avatars.com/api/?name=Dr+Smith&background=0d9488&color=fff" className="w-10 h-10 rounded-lg" alt="Profile" />
                  <div className="text-left">
                    <p className="font-bold text-slate-900 text-sm">Dr. Alexander Smith</p>
                    <p className="text-[9px] text-teal-600 font-black uppercase tracking-widest">Authenticated</p>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 text-slate-400">
                   <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-teal-500 animate-pulse">
                      <Fingerprint size={24} />
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.2em]">Touch to Unlock</p>
                </div>
              </div>
            )}
          </div>

          <p className="mt-6 text-[8px] text-slate-300 font-bold uppercase tracking-[0.4em]">
            Hand & Microvascular Surgery Core
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar activeView={activeView} setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md">
          <div className="flex items-center gap-2">
            <div className="lg:hidden"><OpusLogo size="sm" className="rounded-lg shadow-sm" /></div>
            <div className="hidden lg:block font-bold text-slate-300 text-[9px] uppercase tracking-[0.3em]">Dr. Smith • Microvascular Terminal</div>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5 bg-teal-50 px-2 py-1 rounded-lg border border-teal-100">
              <div className="w-1 h-1 rounded-full bg-teal-500 animate-pulse"></div>
              <span className="text-[8px] font-black text-teal-700 uppercase">Drive Secure</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-600"><Menu size={18} /></button>
          </div>
        </div>

        <div className="px-6 py-4 max-w-[1200px] mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Initialize Study Modal */}
      {showAddStudyModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-sm uppercase tracking-widest"><h2>Initialize Study</h2><button onClick={() => setShowAddStudyModal(false)}><X size={16} /></button></div>
            <form onSubmit={handleCreateStudy} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Study Name</label><input required value={newStudy.name} onChange={e => setNewStudy({...newStudy, name: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs outline-none focus:border-teal-500" placeholder="e.g. Nerve Repair 2024" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={newStudy.description} onChange={e => setNewStudy({...newStudy, description: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs outline-none focus:border-teal-500 resize-none" /></div>
              <button type="submit" className="w-full bg-teal-600 text-white font-black py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest">Create Research Unit</button>
            </form>
          </div>
        </div>
      )}

      {/* Export Selection Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest">
              <h2>Select Groups to Export</h2>
              <button onClick={() => setShowExportModal(false)} className="text-slate-400 hover:text-slate-600"><X size={16} /></button>
            </div>
            <div className="space-y-2 mb-6 max-h-60 overflow-y-auto pr-1">
              {studyGroups.map(group => (
                <button 
                  key={group.id} 
                  onClick={() => setExportSelection(prev => prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id])} 
                  className={`w-full text-left p-3 rounded-xl border transition-all flex items-center justify-between text-[11px] ${exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 hover:border-slate-200'}`}
                >
                  <span>{group.name}</span>
                  {exportSelection.includes(group.id) ? <CheckCircle2 size={14} /> : <div className="w-3.5 h-3.5 rounded-full border border-slate-200" />}
                </button>
              ))}
            </div>
            <button 
              onClick={handleExportAction} 
              disabled={isExporting}
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest hover:bg-teal-700 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isExporting ? <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Download size={16} />}
              Generate Clinical Report (.pdf / .xlsx)
            </button>
          </div>
        </div>
      )}

      {editingStudyGroup && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4"><h2 className="text-sm font-bold">Edit Study</h2><button onClick={() => setEditingStudyGroup(null)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); setEditingStudyGroup(null); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Name</label><input required value={editingStudyGroup.name} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={editingStudyGroup.description} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs" /></div>
              <button type="submit" className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest"><Save size={14} className="inline mr-1" /> Update Metadata</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, Sparkles, CloudUpload, FileText, Calendar, Plus } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup, SurgeryEvent } from '../types';
import { analyzeSurgicalImage } from '../services/geminiService';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
  base64?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [notes, setNotes] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = patients.find(p => p.uhid === selectedPatientId);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(',')[1] || '');
      reader.onerror = error => reject(error);
    });
  };

  /**
   * Generates a thumbnail for a video file by seeking to a specific frame.
   */
  const generateVideoThumbnail = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      const videoUrl = URL.createObjectURL(file);
      video.src = videoUrl;
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;

      video.onloadedmetadata = () => {
        // Seek to 0.5 seconds or half duration to get a representative frame
        video.currentTime = Math.min(0.5, video.duration / 2);
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL('image/jpeg');
          URL.revokeObjectURL(videoUrl);
          resolve(dataUrl);
        } else {
          URL.revokeObjectURL(videoUrl);
          resolve('');
        }
      };

      video.onerror = () => {
        URL.revokeObjectURL(videoUrl);
        resolve('');
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const newPreviews: PreviewFile[] = [];

      // Process files in parallel for better performance with multiple selections
      const processPromises = files.map(async (file) => {
        const type = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);

        let thumbnailUrl: string | undefined;
        let base64: string | undefined;

        if (type === 'video') {
          thumbnailUrl = await generateVideoThumbnail(file);
        } else {
          base64 = await fileToBase64(file);
        }

        return { url, file, type, thumbnailUrl, base64 };
      });

      const processedFiles = await Promise.all(processPromises);
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;

    // Validate surgery link
    if (!surgeryId && !showNewSurgeryForm) {
      alert("Please select or register a surgery event.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        surgeryId: showNewSurgeryForm ? `new_${Date.now()}` : surgeryId,
        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate } : null,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        tags: customTags.split(',').filter(t => t.trim()),
        notes,
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length
      });
      setIsUploading(false);
      setShowSuccess(true);
      // Revoke all preview URLs to prevent memory leaks
      previewFiles.forEach(f => URL.revokeObjectURL(f.url));
      setPreviewFiles([]);
      setCustomTags('');
      setNotes('');
      setSelectedPatientId('');
      setSurgeryId('');
      setShowNewSurgeryForm(false);
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xs mx-auto py-12 text-center space-y-6 animate-in zoom-in-95">
        <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center mx-auto shadow-sm border border-teal-100">
          <CheckCircle2 size={32} />
        </div>
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-900 tracking-tight italic">Vault Entry Created</h2>
          <p className="text-slate-400 font-medium text-[10px] uppercase tracking-widest">Locked in Cloud Repository</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg transition-all active:scale-[0.98] text-[10px] uppercase tracking-widest">
          Begin New Capture
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-xl font-black text-slate-900 tracking-tight">Intake Portal</h1>
        <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest">Longitudinal Operative Intake</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
        <div className="lg:col-span-4 space-y-4">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-900 flex items-center gap-2">
              <Database size={14} className="text-teal-600" /> Intake Context
            </h2>
            <div>
              <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Target Patient *</label>
              <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Search patient...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-3 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center">
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest">Surgery Event</label>
                  <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-black text-teal-600 uppercase flex items-center gap-1">
                    {showNewSurgeryForm ? 'Select Existing' : <><Plus size={10} /> Register New Surgery</>}
                  </button>
                </div>

                {!showNewSurgeryForm ? (
                  <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                    <option value="">Select Procedure...</option>
                    {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                  </select>
                ) : (
                  <div className="space-y-2 p-3 bg-teal-50/50 rounded-xl border border-teal-100">
                     <input required placeholder="Procedure Title (e.g. Nerve Graft)" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                     <input required type="date" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                  </div>
                )}

                <div>
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-1">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-3 py-2 rounded-lg border text-[10px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                        {s}{stage === s && <CheckCircle2 size={10} />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-8 space-y-4">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6 flex flex-col">
            <div className="group relative p-8 border-2 border-dashed border-slate-100 rounded-xl bg-slate-50/30 hover:bg-white hover:border-teal-100 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[160px]">
              <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-3 bg-white rounded-lg shadow-sm text-slate-300 mb-3 group-hover:text-teal-500 transition-colors"><Camera size={24} /></div>
              <h3 className="text-sm font-bold text-slate-900">Operative Media</h3>
              <p className="text-slate-400 text-[9px] font-medium mt-0.5 uppercase tracking-widest">High-quality master files for archival</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-4 sm:grid-cols-6 lg:grid-cols-8 gap-2">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-lg overflow-hidden border border-slate-200 bg-slate-900 shadow-sm">
                    {fileData.type === 'video' ? (
                      <div className="relative w-full h-full">
                        {fileData.thumbnailUrl ? (
                          <img src={fileData.thumbnailUrl} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-opacity" alt="" />
                        ) : (
                          <div className="w-full h-full bg-slate-800" />
                        )}
                        <div className="absolute inset-0 flex items-center justify-center text-white drop-shadow-md">
                          <PlayCircle size={20} className="fill-white/20" />
                        </div>
                      </div>
                    ) : (
                      <img src={fileData.url} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" alt="" />
                    )}
                    <button 
                      type="button" 
                      onClick={() => removeFile(i)} 
                      className="absolute top-1 right-1 p-1 bg-black/60 text-white rounded-md opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500"
                    >
                      <Trash2 size={10} />
                    </button>
                    <div className="absolute bottom-1 left-1 bg-black/40 px-1 rounded text-[7px] text-white font-black uppercase tracking-tighter">
                      {fileData.type}
                    </div>
                  </div>
                ))}
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <div className="col-span-2">
                <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1"><FileText size={10} /> Operative Observation</label>
                <textarea value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-20 font-bold text-xs outline-none focus:border-teal-500 resize-none" placeholder="Enter findings or procedure steps..." />
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-[0.2em] mt-2 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isUploading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={16} />}
              Commit {previewFiles.length > 0 ? `(${previewFiles.length} files)` : ''} to Secure Vault
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

import React, { useState } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, Sparkles, CloudUpload, FileText, Calendar, Plus } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup, SurgeryEvent } from '../types';
import { analyzeSurgicalImage } from '../services/geminiService';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
  base64?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [notes, setNotes] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = patients.find(p => p.uhid === selectedPatientId);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(',')[1] || '');
      reader.onerror = error => reject(error);
    });
  };

  /**
   * Generates a thumbnail for a video file by seeking to a specific frame.
   */
  const generateVideoThumbnail = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      const videoUrl = URL.createObjectURL(file);
      video.src = videoUrl;
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;

      video.onloadedmetadata = () => {
        // Seek to 0.5 seconds or half duration to get a representative frame
        video.currentTime = Math.min(0.5, video.duration / 2);
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL('image/jpeg');
          URL.revokeObjectURL(videoUrl);
          resolve(dataUrl);
        } else {
          URL.revokeObjectURL(videoUrl);
          resolve('');
        }
      };

      video.onerror = () => {
        URL.revokeObjectURL(videoUrl);
        resolve('');
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);

      // Process files in parallel for better performance with multiple selections
      // Fix: Explicitly define the return type as Promise<PreviewFile> to satisfy TypeScript and match PreviewFile interface.
      const processPromises = files.map(async (file): Promise<PreviewFile> => {
        // Fix: Explicitly cast type to 'image' | 'video' to ensure literal string typing.
        const type: 'image' | 'video' = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);

        let thumbnailUrl: string | undefined;
        let base64: string | undefined;

        if (type === 'video') {
          thumbnailUrl = await generateVideoThumbnail(file);
        } else {
          base64 = await fileToBase64(file);
        }

        return { url, file, type, thumbnailUrl, base64 };
      });

      const processedFiles = await Promise.all(processPromises);
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;

    // Validate surgery link
    if (!surgeryId && !showNewSurgeryForm) {
      alert("Please select or register a surgery event.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        surgeryId: showNewSurgeryForm ? `new_${Date.now()}` : surgeryId,
        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate } : null,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        tags: customTags.split(',').filter(t => t.trim()),
        notes,
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length
      });
      setIsUploading(false);
      setShowSuccess(true);
      // Revoke all preview URLs to prevent memory leaks
      previewFiles.forEach(f => URL.revokeObjectURL(f.url));
      setPreviewFiles([]);
      setCustomTags('');
      setNotes('');
      setSelectedPatientId('');
      setSurgeryId('');
      setShowNewSurgeryForm(false);
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xs mx-auto py-12 text-center space-y-6 animate-in zoom-in-95">
        <div className="w-16 h-16 bg-teal-50 text-teal-600 rounded-xl flex items-center justify-center mx-auto shadow-sm border border-teal-100">
          <CheckCircle2 size={32} />
        </div>
        <div className="space-y-1">
          <h2 className="text-xl font-black text-slate-900 tracking-tight italic">Vault Entry Created</h2>
          <p className="text-slate-400 font-medium text-[10px] uppercase tracking-widest">Locked in Cloud Repository</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg transition-all active:scale-[0.98] text-[10px] uppercase tracking-widest">
          Begin New Capture
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-xl font-black text-slate-900 tracking-tight">Intake Portal</h1>
        <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest">Longitudinal Operative Intake</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
        <div className="lg:col-span-4 space-y-4">
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
            <h2 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-900 flex items-center gap-2">
              <Database size={14} className="text-teal-600" /> Intake Context
            </h2>
            <div>
              <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Target Patient *</label>
              <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Search patient...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.lastName}, {p.firstName} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-3 animate-in slide-in-from-top-2 duration-300">
                <div className="flex justify-between items-center">
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest">Surgery Event</label>
                  <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-black text-teal-600 uppercase flex items-center gap-1">
                    {showNewSurgeryForm ? 'Select Existing' : <><Plus size={10} /> Register New Surgery</>}
                  </button>
                </div>

                {!showNewSurgeryForm ? (
                  <select className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-slate-900 text-xs" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                    <option value="">Select Procedure...</option>
                    {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                  </select>
                ) : (
                  <div className="space-y-2 p-3 bg-teal-50/50 rounded-xl border border-teal-100">
                     <input required placeholder="Procedure Title (e.g. Nerve Graft)" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                     <input required type="date" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                  </div>
                )}

                <div>
                  <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-1">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-3 py-2 rounded-lg border text-[10px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                        {s}{stage === s && <CheckCircle2 size={10} />}
                      </button>
                    ))}
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-8 space-y-4">
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm space-y-6 flex flex-col">
            <div className="group relative p-8 border-2 border-dashed border-slate-100 rounded-xl bg-slate-50/30 hover:bg-white hover:border-teal-100 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[160px]">
              <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-3 bg-white rounded-lg shadow-sm text-slate-300 mb-3 group-hover:text-teal-500 transition-colors"><Camera size={24} /></div>
              <h3 className="text-sm font-bold text-slate-900">Operative Media</h3>
              <p className="text-slate-400 text-[9px] font-medium mt-0.5 uppercase tracking-widest">High-quality master files for archival</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-4 sm:grid-cols-6 lg:grid-cols-8 gap-2">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-lg overflow-hidden border border-slate-200 bg-slate-900 shadow-sm">
                    {fileData.type === 'video' ? (
                      <div className="relative w-full h-full">
                        {fileData.thumbnailUrl ? (
                          <img src={fileData.thumbnailUrl} className="w-full h-full object-cover opacity-70 group-hover:opacity-100 transition-opacity" alt="" />
                        ) : (
                          <div className="w-full h-full bg-slate-800" />
                        )}
                        <div className="absolute inset-0 flex items-center justify-center text-white drop-shadow-md">
                          <PlayCircle size={20} className="fill-white/20" />
                        </div>
                      </div>
                    ) : (
                      <img src={fileData.url} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" alt="" />
                    )}
                    <button 
                      type="button" 
                      onClick={() => removeFile(i)} 
                      className="absolute top-1 right-1 p-1 bg-black/60 text-white rounded-md opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500"
                    >
                      <Trash2 size={10} />
                    </button>
                    <div className="absolute bottom-1 left-1 bg-black/40 px-1 rounded text-[7px] text-white font-black uppercase tracking-tighter">
                      {fileData.type}
                    </div>
                  </div>
                ))}
              </div>
            )}

            <div className="grid grid-cols-2 gap-4">
              <div className="col-span-2">
                <label className="block text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1"><FileText size={10} /> Operative Observation</label>
                <textarea value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-20 font-bold text-xs outline-none focus:border-teal-500 resize-none" placeholder="Enter findings or procedure steps..." />
              </div>
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-[0.2em] mt-2 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isUploading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={16} />}
              Commit {previewFiles.length > 0 ? `(${previewFiles.length} files)` : ''} to Secure Vault
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

