import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut, Fingerprint, FileText,
  Download, UserPlus, Trash2, Edit
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showEnrollModal, setShowEnrollModal] = useState(false);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleGoogleAuth = () => {
    setIsLinked(true);
    // Auto-login after linking for smoother flow
    setTimeout(() => setIsLoggedIn(true), 800);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient); // Auto-navigate to the new patient's dashboard
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
    if (patientToEdit?.uhid === updated.uhid) {
      setPatientToEdit(null);
    }
  };

  const handleEnrollPatient = (patientUhid: string) => {
    if (!selectedStudyGroup) return;
    setPatients(prev => prev.map(p => {
      if (p.uhid === patientUhid && !p.studyGroupIds.includes(selectedStudyGroup.id)) {
        return { ...p, studyGroupIds: [...p.studyGroupIds, selectedStudyGroup.id] };
      }
      return p;
    }));
  };

  const handleUnenrollPatient = (patientUhid: string, studyGroupId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === patientUhid) {
        return { ...p, studyGroupIds: p.studyGroupIds.filter(id => id !== studyGroupId) };
      }
      return p;
    }));
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleExportAction = () => {
    if (exportSelection.length === 0) {
      alert("Please select at least one study group to export.");
      return;
    }
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      setShowExportModal(false);
      setExportSelection([]);
      alert(`Export Successful: Clinical Data compiled for ${exportSelection.length} groups. Downloaded as PDF and Excel (.xlsx) to your research drive.`);
    }, 2000);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      const unenrolledPatients = patients.filter(p => !p.studyGroupIds.includes(selectedStudyGroup.id));

      return (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-[11px] font-bold uppercase tracking-wider">
              <X size={14} /> Close Study View
            </button>
            <div className="flex gap-2">
              <button onClick={() => setShowEnrollModal(true)} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all hover:bg-teal-700 flex items-center gap-1.5 shadow-sm">
                <UserPlus size={12} /> Enroll Patient
              </button>
              <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-transform hover:scale-105">
                <Edit3 size={12} className="inline mr-1" /> Edit Meta
              </button>
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-xs font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 flex items-center gap-2">
              <HardDrive className="text-slate-400" size={14} />
              <p className="font-mono text-[9px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>

          <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">
            <FileText size={12} /> Enrolled Candidates ({enrolledPatients.length})
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {enrolledPatients.map(p => (
              <div key={p.uhid} className="bg-white p-3 rounded-xl border border-slate-100 hover:border-teal-500 transition-all flex flex-col gap-3 group relative overflow-hidden">
                <div className="flex items-center gap-3 cursor-pointer" onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }}>
                  <div className="w-10 h-10 bg-teal-600 text-white rounded-lg flex items-center justify-center text-xs font-black shrink-0">{p.lastName[0]}{p.firstName[0]}</div>
                  <div className="overflow-hidden">
                    <h4 className="font-bold text-slate-900 text-xs truncate">{p.lastName}, {p.firstName}</h4>
                    <p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p>
                  </div>
                </div>

                <div className="flex border-t border-slate-50 pt-2 gap-1.5">
                   <button 
                    onClick={() => setPatientToEdit(p)}
                    className="flex-1 py-1.5 rounded-md bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-900 transition-all flex items-center justify-center gap-1 text-[8px] font-black uppercase"
                   >
                     <Edit size={10} /> Edit
                   </button>
                   <button 
                    onClick={() => handleUnenrollPatient(p.uhid, selectedStudyGroup.id)}
                    className="p-1.5 rounded-md bg-red-50 text-red-400 hover:bg-red-500 hover:text-white transition-all"
                    title="Remove from Study"
                   >
                     <Trash2 size={10} />
                   </button>
                </div>
              </div>
            ))}
            {enrolledPatients.length === 0 && (
              <div className="col-span-full py-12 text-center bg-slate-50/50 border border-dashed border-slate-200 rounded-2xl">
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">No candidates enrolled in this cluster</p>
              </div>
            )}
          </div>

          {showEnrollModal && (
            <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl animate-in zoom-in-95 flex flex-col max-h-[80vh]">
                <div className="p-4 border-b border-slate-50 flex justify-between items-center">
                  <h2 className="text-xs font-black uppercase tracking-widest">Enroll Patient to {selectedStudyGroup.name}</h2>
                  <button onClick={() => setShowEnrollModal(false)}><X size={16} /></button>
                </div>
                <div className="p-4 overflow-y-auto space-y-2">
                  {unenrolledPatients.length > 0 ? unenrolledPatients.map(p => (
                    <div key={p.uhid} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-slate-100 transition-all">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-slate-200 text-slate-500 rounded-lg flex items-center justify-center text-[10px] font-black">{p.lastName[0]}{p.firstName[0]}</div>
                        <div>
                          <p className="text-[11px] font-bold text-slate-900">{p.lastName}, {p.firstName}</p>
                          <p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p>
                        </div>
                      </div>
                      <button 
                        onClick={() => { handleEnrollPatient(p.uhid); setShowEnrollModal(false); }}
                        className="bg-teal-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-teal-700"
                      >
                        Enroll
                      </button>
                    </div>
                  )) : (
                    <p className="text-center text-[10px] font-bold text-slate-400 py-8 uppercase tracking-widest italic">All patients are currently enrolled</p>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={patients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={patients} studyGroups={studyGroups} onUpload={d => { 
          // Update patient surgery date if provided during upload
          if (d.surgeryDate) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid ? { ...p, dateOfSurgery: d.surgeryDate } : p));
          }
          // Add to study group if assigned
          if (d.studyGroup) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup) ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] } : p));
          }
        }} />;
      case 'research': return (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div><h2 className="text-xl font-black text-slate-900 tracking-tight">Research Clusters</h2></div>
            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 border border-slate-200 bg-white px-3 py-1.5 rounded-lg text-[10px] font-black text-slate-700 uppercase tracking-widest hover:bg-slate-50 transition-all"><FileSpreadsheet size={14} /> Export Sheet</button>
              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-teal-700 transition-all"><Plus size={14} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-8 h-8 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-3 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={16} /></div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{group.name}</h3>
                <p className="text-slate-400 text-[11px] font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-3 border-t border-slate-50 mt-3">
                  <span className="text-teal-700 font-bold text-[9px] uppercase tracking-tighter">{patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <Edit3 size={12} className="text-slate-300 group-hover:text-teal-600" />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-xs w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-6">
            <OpusLogo size="md" className="mx-auto mb-3 shadow-lg rounded-xl" />
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[8px]">Operative Photo Unite and Store</p>
          </div>

          <div className="bg-white rounded-[2rem] p-8 border border-slate-100 shadow-xl">
            {!isLinked ? (
              <div className="space-y-4">
                <button 
                  onClick={handleGoogleAuth} 
                  className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Sign in with Google
                </button>
                <div className="flex items-center justify-center gap-2 text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2">
                  <Fingerprint size={14} /> Biometric Ready
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 bg-teal-50 p-3 rounded-xl border border-teal-100">
                  <img src="https://ui-avatars.com/api/?name=Dr+Smith&background=0d9488&color=fff" className="w-10 h-10 rounded-lg" alt="Profile" />
                  <div className="text-left">
                    <p className="font-bold text-slate-900 text-sm">Dr. Alexander Smith</p>
                    <p className="text-[9px] text-teal-600 font-black uppercase tracking-widest">Authenticated</p>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 text-slate-400">
                   <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-teal-500 animate-pulse">
                      <Fingerprint size={24} />
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.2em]">Touch to Unlock</p>
                </div>
              </div>
            )}
          </div>

          <p className="mt-6 text-[8px] text-slate-300 font-bold uppercase tracking-[0.4em]">
            Hand & Microvascular Surgery Core
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar activeView={activeView} setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md">
          <div className="flex items-center gap-2">
            <div className="lg:hidden"><OpusLogo size="sm" className="rounded-lg shadow-sm" /></div>
            <div className="hidden lg:block font-bold text-slate-300 text-[9px] uppercase tracking-[0.3em]">Dr. Smith • Microvascular Terminal</div>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5 bg-teal-50 px-2 py-1 rounded-lg border border-teal-100">
              <div className="w-1 h-1 rounded-full bg-teal-500 animate-pulse"></div>
              <span className="text-[8px] font-black text-teal-700 uppercase">Drive Secure</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-600"><Menu size={18} /></button>
          </div>
        </div>

        <div className="px-6 py-4 max-w-[1200px] mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Initialize Study Modal */}
      {showAddStudyModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-sm uppercase tracking-widest"><h2>Initialize Study</h2><button onClick={() => setShowAddStudyModal(false)}><X size={16} /></button></div>
            <form onSubmit={handleCreateStudy} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Study Name</label><input required value={newStudy.name} onChange={e => setNewStudy({...newStudy, name: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs outline-none focus:border-teal-500" placeholder="e.g. Nerve Repair 2024" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={newStudy.description} onChange={e => setNewStudy({...newStudy, description: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs outline-none focus:border-teal-500 resize-none" /></div>
              <button type="submit" className="w-full bg-teal-600 text-white font-black py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest">Create Research Unit</button>
            </form>
          </div>
        </div>
      )}

      {/* Export Selection Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest">
              <h2>Select Groups to Export</h2>
              <button onClick={() => setShowExportModal(false)} className="text-slate-400 hover:text-slate-600"><X size={16} /></button>
            </div>
            <div className="space-y-2 mb-6 max-h-60 overflow-y-auto pr-1">
              {studyGroups.map(group => (
                <button 
                  key={group.id} 
                  onClick={() => setExportSelection(prev => prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id])} 
                  className={`w-full text-left p-3 rounded-xl border transition-all flex items-center justify-between text-[11px] ${exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 hover:border-slate-200'}`}
                >
                  <span>{group.name}</span>
                  {exportSelection.includes(group.id) ? <CheckCircle2 size={14} /> : <div className="w-3.5 h-3.5 rounded-full border border-slate-200" />}
                </button>
              ))}
            </div>
            <button 
              onClick={handleExportAction} 
              disabled={isExporting}
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest hover:bg-teal-700 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isExporting ? <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Download size={16} />}
              Generate Clinical Report (.pdf / .xlsx)
            </button>
          </div>
        </div>
      )}

      {editingStudyGroup && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4"><h2 className="text-sm font-bold">Edit Study</h2><button onClick={() => setEditingStudyGroup(null)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); setEditingStudyGroup(null); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Name</label><input required value={editingStudyGroup.name} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={editingStudyGroup.description} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs" /></div>
              <button type="submit" className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest"><Save size={14} className="inline mr-1" /> Update Metadata</button>
            </form>
          </div>
        </div>
      )}

      {/* Direct Patient Edit Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-[10px] font-black uppercase tracking-widest">Edit Patient Clinical Data</h2>
              <button onClick={() => setPatientToEdit(null)}><X size={16} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-4">
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID (Read Only)</label>
                <input value={patientToEdit.uhid} readOnly className="w-full px-3 py-1.5 bg-slate-100 rounded-lg border border-slate-100 font-bold text-[11px] outline-none" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">First Name</label>
                  <input value={patientToEdit.firstName} onChange={e => setPatientToEdit({...patientToEdit, firstName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
                </div>
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Last Name</label>
                  <input value={patientToEdit.lastName} onChange={e => setPatientToEdit({...patientToEdit, lastName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
                </div>
              </div>
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px] h-16 resize-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">Update Core Registry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ArrowLeft, Plus, Download, X, Edit, Columns, CloudUpload, HardDrive, CheckCircle2, Camera, FileText, PlayCircle, PauseCircle, Maximize2 } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, MediaEntry, SurgeryEvent, MediaType } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient }) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showEditModal, setShowEditModal] = useState(false);
  const [isCompareMode, setIsCompareMode] = useState(false);
  const [editPatient, setEditPatient] = useState<Patient>({ ...patient });
  const [syncingIds, setSyncingIds] = useState<Set<string>>(new Set());
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);

  const patientMedia = [...MOCK_MEDIA]
    .filter(m => m.uhid === patient.uhid)
    .sort((a, b) => new Date(b.uploadedAt).getTime() - new Date(a.uploadedAt).getTime());

  const filteredMedia = patientMedia.filter(m => m.surgeryId === activeSurgeryId && m.stage === activeStage);
  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);

  const handleDownload = async (media: MediaEntry) => {
    try {
      const response = await fetch(media.url);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `OPUS_${patient.uhid}_${media.stage}_${media.id}.${media.type === MediaType.VIDEO ? 'mp4' : 'jpg'}`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (e) {
      alert("High-quality master download failed. Retrying...");
    }
  };

  const handleSyncToDrive = (mediaId: string) => {
    setSyncingIds(prev => new Set(prev).add(mediaId));
    setTimeout(() => {
      setSyncingIds(prev => { const next = new Set(prev); next.delete(mediaId); return next; });
    }, 1200);
  };

  const toggleVideoPlayback = (mediaId: string) => {
    if (playingVideoId === mediaId) {
      setPlayingVideoId(null);
    } else {
      setPlayingVideoId(mediaId);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-400 hover:text-slate-900 transition-colors font-bold text-[9px] uppercase tracking-widest group">
          <ArrowLeft size={12} className="group-hover:-translate-x-1 transition-transform" /> Dashboard
        </button>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsCompareMode(!isCompareMode)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${isCompareMode ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-600 border border-slate-200'}`}
          >
            <Columns size={14} /> Compare Phases
          </button>
          <button onClick={onAddMedia} className="flex items-center gap-1.5 bg-teal-600 text-white px-3 py-1.5 rounded-lg font-black text-[9px] uppercase tracking-widest shadow-md">
            <Plus size={14} /> Capture Media
          </button>
        </div>
      </div>

      {/* Header Info */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-4">
        <div className="flex gap-4 items-center w-full lg:w-auto">
          <div className="w-12 h-12 bg-teal-600 text-white rounded-xl flex items-center justify-center text-lg font-black">
            {patient.lastName[0]}{patient.firstName[0]}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-base font-black text-slate-900 tracking-tight">{patient.lastName}, {patient.firstName}</h1>
              <span className="bg-slate-50 px-2 py-0.5 rounded-md font-mono font-bold text-[8px] text-slate-400 border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest mt-0.5">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} • {patient.surgeries.length} Historical Procedures
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 w-full lg:w-auto">
           <div className="flex-1 bg-slate-50 border border-slate-100 px-3 py-2 rounded-xl flex items-center gap-2 min-w-[200px]">
              <HardDrive size={14} className="text-teal-600" />
              <p className="text-[10px] font-bold text-slate-600 italic truncate line-clamp-1">{patient.diagnosis}</p>
           </div>
           <button onClick={() => setShowEditModal(true)} className="text-slate-300 hover:text-slate-600 p-1 transition-colors">
              <Edit size={14} />
           </button>
        </div>
      </div>

      {/* Surgery Selection Timeline */}
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} 
            onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-4 py-2 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
          >
            <div className="flex flex-col items-start">
               <span className="opacity-60 text-[7px] mb-0.5">{s.date}</span>
               {s.title}
            </div>
          </button>
        ))}
      </div>

      {/* Media View */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="flex bg-slate-50/50 p-1 gap-1">
          {Object.values(SurgicalStage).map(stage => (
            <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-2.5 text-[9px] font-black tracking-widest uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
              {stage}
            </button>
          ))}
        </div>
        <div className="p-4">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
            {filteredMedia.map(m => (
              <div key={m.id} className="group relative bg-slate-100 rounded-xl overflow-hidden aspect-square border border-slate-100">
                {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                  <div className="w-full h-full bg-black relative">
                    <video 
                      src={m.url} 
                      className="w-full h-full object-contain" 
                      autoPlay 
                      controls 
                      onEnded={() => setPlayingVideoId(null)}
                    />
                    <button 
                      onClick={() => setPlayingVideoId(null)}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 text-white rounded-full hover:bg-black/80 transition-colors z-20"
                    >
                      <X size={12} />
                    </button>
                  </div>
                ) : (
                  <>
                    <img 
                      src={m.thumbnailUrl || m.url} 
                      className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" 
                      alt="" 
                    />

                    {/* Video Indicator */}
                    {m.type === MediaType.VIDEO && (
                      <div 
                        onClick={() => toggleVideoPlayback(m.id)}
                        className="absolute inset-0 flex items-center justify-center cursor-pointer z-10"
                      >
                        <div className="bg-black/40 backdrop-blur-sm p-3 rounded-full text-white transform transition-transform group-hover:scale-110">
                          <PlayCircle size={32} />
                        </div>
                      </div>
                    )}

                    <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all p-3 flex flex-col justify-between z-20">
                      <div className="flex justify-between items-start">
                         <div className={`p-1 rounded-md backdrop-blur-md text-white border border-white/20 ${syncingIds.has(m.id) ? 'bg-teal-500 animate-pulse' : 'bg-black/20'}`}>
                            {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? <CheckCircle2 size={10} /> : <button onClick={(e) => { e.stopPropagation(); handleSyncToDrive(m.id); }}><CloudUpload size={10} /></button>}
                         </div>
                         <div className="flex gap-1">
                           {m.type === MediaType.VIDEO && (
                             <button 
                               onClick={(e) => { e.stopPropagation(); toggleVideoPlayback(m.id); }}
                               className="p-1 bg-white/20 backdrop-blur-md rounded-md text-white hover:bg-white/40 transition-colors"
                               title="Preview Video"
                             >
                               <PlayCircle size={10} />
                             </button>
                           )}
                           <button onClick={(e) => { e.stopPropagation(); handleDownload(m); }} className="p-1 bg-white/20 backdrop-blur-md rounded-md text-white hover:bg-white/40 transition-colors">
                              <Download size={10} />
                           </button>
                         </div>
                      </div>
                      <div className="space-y-1">
                         {m.notes && <p className="text-[7px] text-white font-bold truncate"><FileText size={8} className="inline mr-0.5" /> {m.notes}</p>}
                         <div className="flex justify-between items-center">
                            <p className="text-[7px] text-teal-400 uppercase font-black tracking-widest">{new Date(m.uploadedAt).toLocaleDateString()}</p>
                            {m.type === MediaType.VIDEO && <span className="text-[6px] bg-teal-600 text-white px-1 rounded font-black uppercase tracking-tighter">Video</span>}
                         </div>
                      </div>
                    </div>
                  </>
                )}
              </div>
            ))}
            {filteredMedia.length === 0 && (
              <div className="col-span-full py-16 text-center text-slate-200 font-black italic text-[10px] uppercase tracking-[0.2em] border border-dashed border-slate-100 rounded-2xl">
                 No documentation for this phase
              </div>
            )}
          </div>
        </div>
      </div>

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest"><h2>Edit Clinical Core</h2><button onClick={() => setShowEditModal(false)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID</label><input value={editPatient.uhid} readOnly className="w-full px-3 py-1.5 bg-slate-100 rounded-lg border border-slate-100 font-bold text-[11px] outline-none" /></div>
              <div className="grid grid-cols-2 gap-3">
                <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">First Name</label><input value={editPatient.firstName} onChange={e => setEditPatient({...editPatient, firstName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" /></div>
                <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Last Name</label><input value={editPatient.lastName} onChange={e => setEditPatient({...editPatient, lastName: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" /></div>
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">Save Patient Data</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

export enum SurgicalStage {
  PRE_OP = 'Pre-operative',
  INTRA_OP = 'Intra-operative',
  POST_OP = 'Post-operative'
}

export enum MediaType {
  IMAGE = 'image',
  VIDEO = 'video'
}

export enum StorageLocation {
  GOOGLE_DRIVE = 'Google Drive',
  LOCAL = 'Local Storage'
}

export interface StudyGroup {
  id: string;
  name: string;
  description: string;
  patientCount: number;
  driveFolderId?: string;
  lastSync?: string;
}

export interface SurgeryEvent {
  id: string;
  title: string;
  date: string;
  notes?: string;
}

export interface MediaEntry {
  id: string;
  uhid: string;
  surgeryId: string; // Links to a specific surgery event
  stage: SurgicalStage;
  type: MediaType;
  url: string;
  thumbnailUrl?: string;
  uploadedAt: string;
  notes?: string;
  tags: string[];
  storageLocation: StorageLocation;
}

export interface Patient {
  uhid: string;
  name: string;
  ageYears: number;
  ageMonths?: number;
  diagnosis: string;
  primarySurgeon: string;
  studyGroupIds: string[];
  createdAt: string;
  surgeries: SurgeryEvent[]; // Historical list of surgeries
  dateOfSurgery?: string; // Most recent surgery date
}

export interface AuthUser {
  id: string;
  name: string;
  role: 'Surgeon' | 'Fellow' | 'Researcher';
  email: string;
}

import React, { useState } from 'react';
import { Search, Plus, User, X, Tag, Calendar } from 'lucide-react';
import { Patient, StudyGroup, SurgeryEvent } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: StudyGroup[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, studyGroups, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '',
    name: '',
    ageYears: 0,
    ageMonths: 0,
    diagnosis: '',
    primarySurgeon: 'Dr. Smith',
    studyGroupIds: [],
    dateOfSurgery: ''
  });

  const filteredPatients = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) {
      alert("UHID and Name are mandatory.");
      return;
    }

    // Initialize surgeries array
    const surgeries: SurgeryEvent[] = [];
    if (newPatient.dateOfSurgery) {
      surgeries.push({
        id: `surg_${Date.now()}`,
        title: 'Planned Procedure',
        date: newPatient.dateOfSurgery,
        notes: 'Automatically generated during registration.'
      });
    }

    const patientToAdd: Patient = {
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries: surgeries // Crucial: Fixes the crash in PatientDetails
    };

    onAddPatient(patientToAdd);
    setShowModal(false);
    setNewPatient({
      uhid: '', name: '', ageYears: 0, ageMonths: 0,
      diagnosis: '', primarySurgeon: 'Dr. Smith', studyGroupIds: [], dateOfSurgery: ''
    });
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <div>
          <h1 className="text-xl font-black text-slate-900 tracking-tight">Patient Records</h1>
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.2em]">Institutional Longitudinal Database</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="flex items-center gap-2 bg-teal-600 text-white px-4 py-2 rounded-lg hover:bg-teal-700 transition-all text-[10px] font-black uppercase tracking-widest shadow-md"
        >
          <Plus size={14} /> Register Patient
        </button>
      </div>

      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
        <input 
          type="text"
          placeholder="Search UHID, name, diagnosis..."
          className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl outline-none focus:border-teal-500 transition-all text-xs font-medium shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
        {filteredPatients.map(p => (
          <div 
            key={p.uhid}
            onClick={() => onSelectPatient(p)}
            className="bg-white p-4 rounded-2xl border border-slate-100 hover:border-teal-500 transition-all cursor-pointer group shadow-sm"
          >
            <div className="flex justify-between items-start mb-2">
              <div className="w-8 h-8 bg-slate-50 rounded-lg flex items-center justify-center text-slate-400 group-hover:bg-teal-50 group-hover:text-teal-600 transition-colors">
                <User size={16} />
              </div>
              <span className="font-mono font-bold text-[8px] text-slate-300 tracking-wider">
                {p.uhid}
              </span>
            </div>
            <h3 className="font-bold text-slate-900 text-xs mb-0.5 truncate">{p.name}</h3>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-tight mb-2">
              Age: {p.ageYears}y {p.ageYears <= 2 ? `${p.ageMonths || 0}m` : ''}
            </p>
            <div className="bg-slate-50 p-2 rounded-lg mb-2 h-10 overflow-hidden">
              <p className="text-slate-500 text-[10px] font-medium leading-tight line-clamp-2 italic">"{p.diagnosis}"</p>
            </div>

            <div className="flex justify-between items-center">
              {p.dateOfSurgery ? (
                <div className="text-[8px] font-black text-orange-600 uppercase tracking-widest flex items-center gap-1">
                  <Calendar size={10} /> {p.dateOfSurgery}
                </div>
              ) : (
                <div className="text-[8px] font-bold text-slate-300 uppercase tracking-widest">Surg: TBD</div>
              )}
              <div className="flex gap-1">
                {p.studyGroupIds.slice(0, 1).map(id => (
                  <span key={id} className="bg-teal-50 text-teal-600 text-[7px] font-black px-1.5 py-0.5 rounded border border-teal-100 uppercase">{id}</span>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="px-5 py-3 border-b border-slate-50 flex justify-between items-center bg-slate-50">
              <h2 className="text-xs font-black uppercase tracking-widest text-slate-900">Patient Registration</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400"><X size={16} /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-5 space-y-3">
              <div className="grid grid-cols-1 gap-3">
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID *</label>
                  <input required value={newPatient.uhid} onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} type="text" className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg outline-none focus:border-teal-500 transition-all text-xs font-bold" placeholder="HOSP-XXXXX" />
                </div>
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Full Name *</label>
                  <input required value={newPatient.name} onChange={e => setNewPatient({...newPatient, name: e.target.value})} type="text" className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg outline-none focus:border-teal-500 text-xs font-bold" placeholder="e.g. John Doe" />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Age (Years)</label>
                    <input type="number" value={newPatient.ageYears} onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold" />
                  </div>
                  {/* Conditional Age in Months logic */}
                  {newPatient.ageYears !== undefined && newPatient.ageYears <= 2 && (
                    <div className="animate-in slide-in-from-left-2 duration-300">
                      <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Age (Months)</label>
                      <input type="number" max="24" value={newPatient.ageMonths} onChange={e => setNewPatient({...newPatient, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-3 py-2 bg-teal-50 border border-teal-100 rounded-lg text-xs font-bold" />
                    </div>
                  )}
                </div>
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Date of Surgery (Optional)</label>
                  <input type="date" value={newPatient.dateOfSurgery} onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold" />
                </div>
                <div>
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Assign Study Cluster</label>
                  <select 
                    value={newPatient.studyGroupIds?.[0] || ''} 
                    onChange={e => setNewPatient({...newPatient, studyGroupIds: e.target.value ? [e.target.value] : []})}
                    className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg text-xs font-bold"
                  >
                    <option value="">No specific group</option>
                    {studyGroups.map(g => <option key={g.id} value={g.id}>{g.name}</option>)}
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Clinical Diagnosis</label>
                <textarea required value={newPatient.diagnosis} onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 outline-none focus:border-teal-500 text-xs font-bold resize-none" />
              </div>

              <button type="submit" className="w-full bg-teal-600 text-white font-black py-3 rounded-xl hover:bg-teal-700 transition-all shadow-md text-[11px] uppercase tracking-[0.2em]">
                Commit to Vault
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { ArrowLeft, Plus, Download, X, Edit, Columns, CloudUpload, HardDrive, CheckCircle2, Camera, FileText, PlayCircle, PauseCircle, Maximize2 } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, MediaEntry, SurgeryEvent, MediaType } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient }) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showEditModal, setShowEditModal] = useState(false);
  const [isCompareMode, setIsCompareMode] = useState(false);
  const [editPatient, setEditPatient] = useState<Patient>({ ...patient });
  const [syncingIds, setSyncingIds] = useState<Set<string>>(new Set());
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);

  const patientMedia = [...MOCK_MEDIA]
    .filter(m => m.uhid === patient.uhid)
    .sort((a, b) => new Date(b.uploadedAt).getTime() - new Date(a.uploadedAt).getTime());

  const filteredMedia = patientMedia.filter(m => m.surgeryId === activeSurgeryId && m.stage === activeStage);
  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);

  const handleDownload = async (media: MediaEntry) => {
    try {
      const response = await fetch(media.url);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `OPUS_${patient.uhid}_${media.stage}_${media.id}.${media.type === MediaType.VIDEO ? 'mp4' : 'jpg'}`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (e) {
      alert("High-quality master download failed. Retrying...");
    }
  };

  const handleSyncToDrive = (mediaId: string) => {
    setSyncingIds(prev => new Set(prev).add(mediaId));
    setTimeout(() => {
      setSyncingIds(prev => { const next = new Set(prev); next.delete(mediaId); return next; });
    }, 1200);
  };

  const toggleVideoPlayback = (mediaId: string) => {
    if (playingVideoId === mediaId) {
      setPlayingVideoId(null);
    } else {
      setPlayingVideoId(mediaId);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="flex items-center gap-2 text-slate-400 hover:text-slate-900 transition-colors font-bold text-[9px] uppercase tracking-widest group">
          <ArrowLeft size={12} className="group-hover:-translate-x-1 transition-transform" /> Dashboard
        </button>
        <div className="flex gap-2">
          <button 
            onClick={() => setIsCompareMode(!isCompareMode)}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest transition-all ${isCompareMode ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-600 border border-slate-200'}`}
          >
            <Columns size={14} /> Compare Phases
          </button>
          <button onClick={onAddMedia} className="flex items-center gap-1.5 bg-teal-600 text-white px-3 py-1.5 rounded-lg font-black text-[9px] uppercase tracking-widest shadow-md">
            <Plus size={14} /> Capture Media
          </button>
        </div>
      </div>

      {/* Header Info */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-col lg:flex-row justify-between items-center gap-4">
        <div className="flex gap-4 items-center w-full lg:w-auto">
          <div className="w-12 h-12 bg-teal-600 text-white rounded-xl flex items-center justify-center text-lg font-black">
            {patient.name.charAt(0)}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-base font-black text-slate-900 tracking-tight">{patient.name}</h1>
              <span className="bg-slate-50 px-2 py-0.5 rounded-md font-mono font-bold text-[8px] text-slate-400 border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest mt-0.5">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} • {patient.surgeries.length} Historical Procedures
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 w-full lg:w-auto">
           <div className="flex-1 bg-slate-50 border border-slate-100 px-3 py-2 rounded-xl flex items-center gap-2 min-w-[200px]">
              <HardDrive size={14} className="text-teal-600" />
              <p className="text-[10px] font-bold text-slate-600 italic truncate line-clamp-1">{patient.diagnosis}</p>
           </div>
           <button onClick={() => setShowEditModal(true)} className="text-slate-300 hover:text-slate-600 p-1 transition-colors">
              <Edit size={14} />
           </button>
        </div>
      </div>

      {/* Surgery Selection Timeline */}
      <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} 
            onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-4 py-2 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
          >
            <div className="flex flex-col items-start">
               <span className="opacity-60 text-[7px] mb-0.5">{s.date}</span>
               {s.title}
            </div>
          </button>
        ))}
      </div>

      {/* Media View */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col">
        <div className="flex bg-slate-50/50 p-1 gap-1">
          {Object.values(SurgicalStage).map(stage => (
            <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-2.5 text-[9px] font-black tracking-widest uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}>
              {stage}
            </button>
          ))}
        </div>
        <div className="p-4">
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 gap-3">
            {filteredMedia.map(m => (
              <div key={m.id} className="group relative bg-slate-100 rounded-xl overflow-hidden aspect-square border border-slate-100">
                {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                  <div className="w-full h-full bg-black relative">
                    <video 
                      src={m.url} 
                      className="w-full h-full object-contain" 
                      autoPlay 
                      controls 
                      onEnded={() => setPlayingVideoId(null)}
                    />
                    <button 
                      onClick={() => setPlayingVideoId(null)}
                      className="absolute top-2 right-2 p-1.5 bg-black/60 text-white rounded-full hover:bg-black/80 transition-colors z-20"
                    >
                      <X size={12} />
                    </button>
                  </div>
                ) : (
                  <>
                    <img 
                      src={m.thumbnailUrl || m.url} 
                      className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-110" 
                      alt="" 
                    />

                    {/* Video Indicator */}
                    {m.type === MediaType.VIDEO && (
                      <div 
                        onClick={() => toggleVideoPlayback(m.id)}
                        className="absolute inset-0 flex items-center justify-center cursor-pointer z-10"
                      >
                        <div className="bg-black/40 backdrop-blur-sm p-3 rounded-full text-white transform transition-transform group-hover:scale-110">
                          <PlayCircle size={32} />
                        </div>
                      </div>
                    )}

                    <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-all p-3 flex flex-col justify-between z-20">
                      <div className="flex justify-between items-start">
                         <div className={`p-1 rounded-md backdrop-blur-md text-white border border-white/20 ${syncingIds.has(m.id) ? 'bg-teal-500 animate-pulse' : 'bg-black/20'}`}>
                            {m.storageLocation === StorageLocation.GOOGLE_DRIVE ? <CheckCircle2 size={10} /> : <button onClick={(e) => { e.stopPropagation(); handleSyncToDrive(m.id); }}><CloudUpload size={10} /></button>}
                         </div>
                         <div className="flex gap-1">
                           {m.type === MediaType.VIDEO && (
                             <button 
                               onClick={(e) => { e.stopPropagation(); toggleVideoPlayback(m.id); }}
                               className="p-1 bg-white/20 backdrop-blur-md rounded-md text-white hover:bg-white/40 transition-colors"
                               title="Preview Video"
                             >
                               <PlayCircle size={10} />
                             </button>
                           )}
                           <button onClick={(e) => { e.stopPropagation(); handleDownload(m); }} className="p-1 bg-white/20 backdrop-blur-md rounded-md text-white hover:bg-white/40 transition-colors">
                              <Download size={10} />
                           </button>
                         </div>
                      </div>
                      <div className="space-y-1">
                         {m.notes && <p className="text-[7px] text-white font-bold truncate"><FileText size={8} className="inline mr-0.5" /> {m.notes}</p>}
                         <div className="flex justify-between items-center">
                            <p className="text-[7px] text-teal-400 uppercase font-black tracking-widest">{new Date(m.uploadedAt).toLocaleDateString()}</p>
                            {m.type === MediaType.VIDEO && <span className="text-[6px] bg-teal-600 text-white px-1 rounded font-black uppercase tracking-tighter">Video</span>}
                         </div>
                      </div>
                    </div>
                  </>
                )}
              </div>
            ))}
            {filteredMedia.length === 0 && (
              <div className="col-span-full py-16 text-center text-slate-200 font-black italic text-[10px] uppercase tracking-[0.2em] border border-dashed border-slate-100 rounded-2xl">
                 No documentation for this phase
              </div>
            )}
          </div>
        </div>
      </div>

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest"><h2>Edit Clinical Core</h2><button onClick={() => setShowEditModal(false)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID</label><input value={editPatient.uhid} readOnly className="w-full px-3 py-1.5 bg-slate-100 rounded-lg border border-slate-100 font-bold text-[11px] outline-none" /></div>
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Full Name</label>
                <input value={editPatient.name} onChange={e => setEditPatient({...editPatient, name: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">Save Patient Data</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut, Fingerprint, FileText,
  Download, UserPlus, Trash2, Edit
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showEnrollModal, setShowEnrollModal] = useState(false);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);
  const [isExporting, setIsExporting] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const handleGoogleAuth = () => {
    setIsLinked(true);
    // Auto-login after linking for smoother flow
    setTimeout(() => setIsLoggedIn(true), 800);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient); // Auto-navigate to the new patient's dashboard
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
    if (patientToEdit?.uhid === updated.uhid) {
      setPatientToEdit(null);
    }
  };

  const handleEnrollPatient = (patientUhid: string) => {
    if (!selectedStudyGroup) return;
    setPatients(prev => prev.map(p => {
      if (p.uhid === patientUhid && !p.studyGroupIds.includes(selectedStudyGroup.id)) {
        return { ...p, studyGroupIds: [...p.studyGroupIds, selectedStudyGroup.id] };
      }
      return p;
    }));
  };

  const handleUnenrollPatient = (patientUhid: string, studyGroupId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === patientUhid) {
        return { ...p, studyGroupIds: p.studyGroupIds.filter(id => id !== studyGroupId) };
      }
      return p;
    }));
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleExportAction = () => {
    if (exportSelection.length === 0) {
      alert("Please select at least one study group to export.");
      return;
    }
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      setShowExportModal(false);
      setExportSelection([]);
      alert(`Export Successful: Clinical Data compiled for ${exportSelection.length} groups. Downloaded as PDF and Excel (.xlsx) to your research drive.`);
    }, 2000);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = patients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      const unenrolledPatients = patients.filter(p => !p.studyGroupIds.includes(selectedStudyGroup.id));

      return (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-[11px] font-bold uppercase tracking-wider">
              <X size={14} /> Close Study View
            </button>
            <div className="flex gap-2">
              <button onClick={() => setShowEnrollModal(true)} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all hover:bg-teal-700 flex items-center gap-1.5 shadow-sm">
                <UserPlus size={12} /> Enroll Patient
              </button>
              <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-transform hover:scale-105">
                <Edit3 size={12} className="inline mr-1" /> Edit Meta
              </button>
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-xs font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 flex items-center gap-2">
              <HardDrive className="text-slate-400" size={14} />
              <p className="font-mono text-[9px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>

          <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">
            <FileText size={12} /> Enrolled Candidates ({enrolledPatients.length})
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {enrolledPatients.map(p => (
              <div key={p.uhid} className="bg-white p-3 rounded-xl border border-slate-100 hover:border-teal-500 transition-all flex flex-col gap-3 group relative overflow-hidden">
                <div className="flex items-center gap-3 cursor-pointer" onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }}>
                  <div className="w-10 h-10 bg-teal-600 text-white rounded-lg flex items-center justify-center text-xs font-black shrink-0">{p.name.charAt(0)}</div>
                  <div className="overflow-hidden">
                    <h4 className="font-bold text-slate-900 text-xs truncate">{p.name}</h4>
                    <p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p>
                  </div>
                </div>

                <div className="flex border-t border-slate-50 pt-2 gap-1.5">
                   <button 
                    onClick={() => setPatientToEdit(p)}
                    className="flex-1 py-1.5 rounded-md bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-900 transition-all flex items-center justify-center gap-1 text-[8px] font-black uppercase"
                   >
                     <Edit size={10} /> Edit
                   </button>
                   <button 
                    onClick={() => handleUnenrollPatient(p.uhid, selectedStudyGroup.id)}
                    className="p-1.5 rounded-md bg-red-50 text-red-400 hover:bg-red-500 hover:text-white transition-all"
                    title="Remove from Study"
                   >
                     <Trash2 size={10} />
                   </button>
                </div>
              </div>
            ))}
            {enrolledPatients.length === 0 && (
              <div className="col-span-full py-12 text-center bg-slate-50/50 border border-dashed border-slate-200 rounded-2xl">
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">No candidates enrolled in this cluster</p>
              </div>
            )}
          </div>

          {showEnrollModal && (
            <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl animate-in zoom-in-95 flex flex-col max-h-[80vh]">
                <div className="p-4 border-b border-slate-50 flex justify-between items-center">
                  <h2 className="text-xs font-black uppercase tracking-widest">Enroll Patient to {selectedStudyGroup.name}</h2>
                  <button onClick={() => setShowEnrollModal(false)}><X size={16} /></button>
                </div>
                <div className="p-4 overflow-y-auto space-y-2">
                  {unenrolledPatients.length > 0 ? unenrolledPatients.map(p => (
                    <div key={p.uhid} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-slate-100 transition-all">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-slate-200 text-slate-500 rounded-lg flex items-center justify-center text-[10px] font-black">{p.name.charAt(0)}</div>
                        <div>
                          <p className="text-[11px] font-bold text-slate-900">{p.name}</p>
                          <p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p>
                        </div>
                      </div>
                      <button 
                        onClick={() => { handleEnrollPatient(p.uhid); setShowEnrollModal(false); }}
                        className="bg-teal-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-teal-700"
                      >
                        Enroll
                      </button>
                    </div>
                  )) : (
                    <p className="text-center text-[10px] font-bold text-slate-400 py-8 uppercase tracking-widest italic">All patients are currently enrolled</p>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={patients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={patients} studyGroups={studyGroups} onUpload={d => { 
          // Update patient surgery date if provided during upload
          if (d.surgeryDate) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid ? { ...p, dateOfSurgery: d.surgeryDate } : p));
          }
          // Add to study group if assigned
          if (d.studyGroup) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup) ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] } : p));
          }
        }} />;
      case 'research': return (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div><h2 className="text-xl font-black text-slate-900 tracking-tight">Research Clusters</h2></div>
            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 border border-slate-200 bg-white px-3 py-1.5 rounded-lg text-[10px] font-black text-slate-700 uppercase tracking-widest hover:bg-slate-50 transition-all"><FileSpreadsheet size={14} /> Export Sheet</button>
              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-teal-700 transition-all"><Plus size={14} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-8 h-8 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-3 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={16} /></div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{group.name}</h3>
                <p className="text-slate-400 text-[11px] font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-3 border-t border-slate-50 mt-3">
                  <span className="text-teal-700 font-bold text-[9px] uppercase tracking-tighter">{patients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <Edit3 size={12} className="text-slate-300 group-hover:text-teal-600" />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-xs w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-6">
            <OpusLogo size="md" className="mx-auto mb-3 shadow-lg rounded-xl" />
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[8px]">Operative Photo Unite and Store</p>
          </div>

          <div className="bg-white rounded-[2rem] p-8 border border-slate-100 shadow-xl">
            {!isLinked ? (
              <div className="space-y-4">
                <button 
                  onClick={handleGoogleAuth} 
                  className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Sign in with Google
                </button>
                <div className="flex items-center justify-center gap-2 text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2">
                  <Fingerprint size={14} /> Biometric Ready
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 bg-teal-50 p-3 rounded-xl border border-teal-100">
                  <img src="https://ui-avatars.com/api/?name=Dr+Smith&background=0d9488&color=fff" className="w-10 h-10 rounded-lg" alt="Profile" />
                  <div className="text-left">
                    <p className="font-bold text-slate-900 text-sm">Dr. Alexander Smith</p>
                    <p className="text-[9px] text-teal-600 font-black uppercase tracking-widest">Authenticated</p>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 text-slate-400">
                   <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-teal-500 animate-pulse">
                      <Fingerprint size={24} />
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.2em]">Touch to Unlock</p>
                </div>
              </div>
            )}
          </div>

          <p className="mt-6 text-[8px] text-slate-300 font-bold uppercase tracking-[0.4em]">
            Hand & Microvascular Surgery Core
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar activeView={activeView} setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} isOpen={isSidebarOpen} setIsOpen={setIsSidebarOpen} />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md">
          <div className="flex items-center gap-2">
            <div className="lg:hidden"><OpusLogo size="sm" className="rounded-lg shadow-sm" /></div>
            <div className="hidden lg:block font-bold text-slate-300 text-[9px] uppercase tracking-[0.3em]">Dr. Smith • Microvascular Terminal</div>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5 bg-teal-50 px-2 py-1 rounded-lg border border-teal-100">
              <div className="w-1 h-1 rounded-full bg-teal-500 animate-pulse"></div>
              <span className="text-[8px] font-black text-teal-700 uppercase">Drive Secure</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-600"><Menu size={18} /></button>
          </div>
        </div>

        <div className="px-6 py-4 max-w-[1200px] mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Initialize Study Modal */}
      {showAddStudyModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-sm uppercase tracking-widest"><h2>Initialize Study</h2><button onClick={() => setShowAddStudyModal(false)}><X size={16} /></button></div>
            <form onSubmit={handleCreateStudy} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Study Name</label><input required value={newStudy.name} onChange={e => setNewStudy({...newStudy, name: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs outline-none focus:border-teal-500" placeholder="e.g. Nerve Repair 2024" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={newStudy.description} onChange={e => setNewStudy({...newStudy, description: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs outline-none focus:border-teal-500 resize-none" /></div>
              <button type="submit" className="w-full bg-teal-600 text-white font-black py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest">Create Research Unit</button>
            </form>
          </div>
        </div>
      )}

      {/* Export Selection Modal */}
      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest">
              <h2>Select Groups to Export</h2>
              <button onClick={() => setShowExportModal(false)} className="text-slate-400 hover:text-slate-600"><X size={16} /></button>
            </div>
            <div className="space-y-2 mb-6 max-h-60 overflow-y-auto pr-1">
              {studyGroups.map(group => (
                <button 
                  key={group.id} 
                  onClick={() => setExportSelection(prev => prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id])} 
                  className={`w-full text-left p-3 rounded-xl border transition-all flex items-center justify-between text-[11px] ${exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 hover:border-slate-200'}`}
                >
                  <span>{group.name}</span>
                  {exportSelection.includes(group.id) ? <CheckCircle2 size={14} /> : <div className="w-3.5 h-3.5 rounded-full border border-slate-200" />}
                </button>
              ))}
            </div>
            <button 
              onClick={handleExportAction} 
              disabled={isExporting}
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest hover:bg-teal-700 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isExporting ? <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Download size={16} />}
              Generate Clinical Report (.pdf / .xlsx)
            </button>
          </div>
        </div>
      )}

      {editingStudyGroup && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4"><h2 className="text-sm font-bold">Edit Study</h2><button onClick={() => setEditingStudyGroup(null)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); setEditingStudyGroup(null); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Name</label><input required value={editingStudyGroup.name} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={editingStudyGroup.description} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs" /></div>
              <button type="submit" className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest"><Save size={14} className="inline mr-1" /> Update Metadata</button>
            </form>
          </div>
        </div>
      )}

      {/* Direct Patient Edit Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-[10px] font-black uppercase tracking-widest">Edit Patient Clinical Data</h2>
              <button onClick={() => setPatientToEdit(null)}><X size={16} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-4">
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID (Read Only)</label>
                <input value={patientToEdit.uhid} readOnly className="w-full px-3 py-1.5 bg-slate-100 rounded-lg border border-slate-100 font-bold text-[11px] outline-none" />
              </div>
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Full Name</label>
                <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
              </div>
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px] h-16 resize-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">Update Core Registry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
