import React from 'react';
import { Trash2, RotateCcw, AlertCircle, Clock, ShieldCheck } from 'lucide-react';
import { Patient } from '../types';

interface RecycleBinProps {
  deletedPatients: Patient[];
  onRestore: (patient: Patient) => void;
  onPermanentDelete: (patient: Patient) => void;
}

const RecycleBin: React.FC<RecycleBinProps> = ({ deletedPatients, onRestore, onPermanentDelete }) => {
  const getDaysRemaining = (deletedAt: string) => {
    const deletedDate = new Date(deletedAt);
    const purgeDate = new Date(deletedDate.getTime() + (30 * 24 * 60 * 60 * 1000));
    const today = new Date();
    const diffTime = purgeDate.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays > 0 ? diffDays : 0;
  };

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-xl font-black text-slate-900 tracking-tight">Recycle Bin</h1>
          <p className="text-slate-400 text-[9px] font-bold uppercase tracking-[0.2em]">Data retention vault (30-day purge cycle)</p>
        </div>
        <div className="flex items-center gap-2 bg-amber-50 border border-amber-100 px-3 py-1.5 rounded-lg">
          <AlertCircle size={14} className="text-amber-500" />
          <span className="text-[10px] font-bold text-amber-700 uppercase tracking-wider">Entries older than 30 days are automatically scrubbed</span>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full border-collapse">
          <thead>
            <tr className="bg-slate-50 border-b border-slate-100">
              <th className="px-6 py-3 text-left text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Patient Identity</th>
              <th className="px-6 py-3 text-left text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Deleted On</th>
              <th className="px-6 py-3 text-left text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Purge In</th>
              <th className="px-6 py-3 text-right text-[9px] font-black text-slate-400 uppercase tracking-[0.2em]">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {deletedPatients.length > 0 ? (
              deletedPatients.map(p => {
                const daysLeft = getDaysRemaining(p.deletedAt!);
                return (
                  <tr key={p.uhid} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-slate-100 rounded-lg flex items-center justify-center text-slate-400 font-black text-[10px]">
                          {p.name.charAt(0)}
                        </div>
                        <div>
                          <p className="text-xs font-bold text-slate-900">{p.name}</p>
                          <p className="text-[10px] font-mono text-slate-400">{p.uhid}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <p className="text-[10px] font-bold text-slate-500">
                        {new Date(p.deletedAt!).toLocaleDateString()}
                      </p>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-1.5">
                        <Clock size={12} className={daysLeft <= 5 ? 'text-red-500' : 'text-slate-300'} />
                        <span className={`text-[10px] font-black uppercase tracking-tighter ${daysLeft <= 5 ? 'text-red-500' : 'text-slate-600'}`}>
                          {daysLeft} Days
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-right space-x-2">
                      <button 
                        onClick={() => onRestore(p)}
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 text-teal-600 hover:bg-teal-50 rounded-lg transition-all text-[9px] font-black uppercase tracking-widest"
                      >
                        <RotateCcw size={14} /> Restore
                      </button>
                      <button 
                        onClick={() => onPermanentDelete(p)}
                        className="inline-flex items-center gap-1.5 px-3 py-1.5 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-all text-[9px] font-black uppercase tracking-widest"
                      >
                        <Trash2 size={14} /> Scrub
                      </button>
                    </td>
                  </tr>
                );
              })
            ) : (
              <tr>
                <td colSpan={4} className="py-20 text-center">
                  <div className="flex flex-col items-center gap-2 opacity-20">
                    <Trash2 size={48} className="text-slate-400" />
                    <p className="text-xs font-black uppercase tracking-[0.3em]">Vault Empty</p>
                  </div>
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="flex items-center gap-3 bg-slate-900 text-slate-400 p-4 rounded-2xl shadow-lg border border-slate-800">
        <ShieldCheck size={20} className="text-teal-500" />
        <div>
          <p className="text-[10px] font-black text-white uppercase tracking-widest">Master Vault Security</p>
          <p className="text-[9px] font-medium opacity-60">All deletions undergo high-entropy verification before purging from the hospital's central Drive cluster.</p>
        </div>
      </div>
    </div>
  );
};

