import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import RecycleBin from './views/RecycleBin';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, ChevronRight, Edit3, Save, LogOut, Fingerprint, FileText,
  Download, UserPlus, Trash2, Edit, ShieldAlert, KeyRound
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  // Modals
  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showEnrollModal, setShowEnrollModal] = useState(false);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  // Security Verification
  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const [isExporting, setIsExporting] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const handleGoogleAuth = () => {
    setIsLinked(true);
    setTimeout(() => setIsLoggedIn(true), 800);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) {
      setSelectedPatient(updated);
    }
    if (patientToEdit?.uhid === updated.uhid) {
      setPatientToEdit(null);
    }
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);

    // Simulate biometric/password latency
    setTimeout(() => {
      const { type, patient } = securityContext;

      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => 
          p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p
        ));
        setSelectedPatient(null);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => 
          p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p
        ));
      }

      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 1200);
  };

  const handleEnrollPatient = (patientUhid: string) => {
    if (!selectedStudyGroup) return;
    setPatients(prev => prev.map(p => {
      if (p.uhid === patientUhid && !p.studyGroupIds.includes(selectedStudyGroup.id)) {
        return { ...p, studyGroupIds: [...p.studyGroupIds, selectedStudyGroup.id] };
      }
      return p;
    }));
  };

  const handleUnenrollPatient = (patientUhid: string, studyGroupId: string) => {
    setPatients(prev => prev.map(p => {
      if (p.uhid === patientUhid) {
        return { ...p, studyGroupIds: p.studyGroupIds.filter(id => id !== studyGroupId) };
      }
      return p;
    }));
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description || 'Clinical study group.',
        patientCount: 0,
        driveFolderId: `drive_${Math.random().toString(36).substr(2, 9)}`,
        lastSync: new Date().toISOString()
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const handleExportAction = () => {
    if (exportSelection.length === 0) {
      alert("Please select at least one study group to export.");
      return;
    }
    setIsExporting(true);
    setTimeout(() => {
      setIsExporting(false);
      setShowExportModal(false);
      setExportSelection([]);
      alert(`Export Successful: Clinical Data compiled for ${exportSelection.length} groups.`);
    }, 2000);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolledPatients = activePatients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      const unenrolledPatients = activePatients.filter(p => !p.studyGroupIds.includes(selectedStudyGroup.id));

      return (
        <div className="space-y-4 animate-in fade-in slide-in-from-bottom-2 duration-300">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="flex items-center gap-2 text-slate-500 hover:text-slate-800 text-[11px] font-bold uppercase tracking-wider">
              <X size={14} /> Close Study View
            </button>
            <div className="flex gap-2">
              <button onClick={() => setShowEnrollModal(true)} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-all hover:bg-teal-700 flex items-center gap-1.5 shadow-sm">
                <UserPlus size={12} /> Enroll Patient
              </button>
              <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest transition-transform hover:scale-105">
                <Edit3 size={12} className="inline mr-1" /> Edit Meta
              </button>
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
            <div className="max-w-xl">
              <h2 className="text-xl font-black text-slate-900 tracking-tight">{selectedStudyGroup.name}</h2>
              <p className="text-slate-500 text-xs font-medium">{selectedStudyGroup.description}</p>
            </div>
            <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100 flex items-center gap-2">
              <HardDrive className="text-slate-400" size={14} />
              <p className="font-mono text-[9px] text-slate-500 font-bold">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>

          <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">
            <FileText size={12} /> Enrolled Candidates ({enrolledPatients.length})
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {enrolledPatients.map(p => (
              <div key={p.uhid} className="bg-white p-3 rounded-xl border border-slate-100 hover:border-teal-500 transition-all flex flex-col gap-3 group relative overflow-hidden">
                <div className="flex items-center gap-3 cursor-pointer" onClick={() => { setSelectedPatient(p); setSelectedStudyGroup(null); }}>
                  <div className="w-10 h-10 bg-teal-600 text-white rounded-lg flex items-center justify-center text-xs font-black shrink-0">{p.name.charAt(0)}</div>
                  <div className="overflow-hidden">
                    <h4 className="font-bold text-slate-900 text-xs truncate">{p.name}</h4>
                    <p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p>
                  </div>
                </div>

                <div className="flex border-t border-slate-50 pt-2 gap-1.5">
                   <button 
                    onClick={() => setPatientToEdit(p)}
                    className="flex-1 py-1.5 rounded-md bg-slate-50 text-slate-400 hover:bg-slate-100 hover:text-slate-900 transition-all flex items-center justify-center gap-1 text-[8px] font-black uppercase"
                   >
                     <Edit size={10} /> Edit
                   </button>
                   <button 
                    onClick={() => handleUnenrollPatient(p.uhid, selectedStudyGroup.id)}
                    className="p-1.5 rounded-md bg-red-50 text-red-400 hover:bg-red-500 hover:text-white transition-all"
                    title="Remove from Study"
                   >
                     <Trash2 size={10} />
                   </button>
                </div>
              </div>
            ))}
            {enrolledPatients.length === 0 && (
              <div className="col-span-full py-12 text-center bg-slate-50/50 border border-dashed border-slate-200 rounded-2xl">
                <p className="text-[10px] font-black text-slate-300 uppercase tracking-widest italic">No candidates enrolled in this cluster</p>
              </div>
            )}
          </div>

          {showEnrollModal && (
            <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[250] flex items-center justify-center p-4">
              <div className="bg-white w-full max-w-md rounded-2xl shadow-2xl animate-in zoom-in-95 flex flex-col max-h-[80vh]">
                <div className="p-4 border-b border-slate-50 flex justify-between items-center">
                  <h2 className="text-xs font-black uppercase tracking-widest">Enroll Patient to {selectedStudyGroup.name}</h2>
                  <button onClick={() => setShowEnrollModal(false)}><X size={16} /></button>
                </div>
                <div className="p-4 overflow-y-auto space-y-2">
                  {unenrolledPatients.length > 0 ? unenrolledPatients.map(p => (
                    <div key={p.uhid} className="flex items-center justify-between p-3 bg-slate-50 rounded-xl hover:bg-slate-100 transition-all">
                      <div className="flex items-center gap-3">
                        <div className="w-8 h-8 bg-slate-200 text-slate-500 rounded-lg flex items-center justify-center text-[10px] font-black">{p.name.charAt(0)}</div>
                        <div>
                          <p className="text-[11px] font-bold text-slate-900">{p.name}</p>
                          <p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p>
                        </div>
                      </div>
                      <button 
                        onClick={() => { handleEnrollPatient(p.uhid); setShowEnrollModal(false); }}
                        className="bg-teal-600 text-white px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest hover:bg-teal-700"
                      >
                        Enroll
                      </button>
                    </div>
                  )) : (
                    <p className="text-center text-[10px] font-bold text-slate-400 py-8 uppercase tracking-widest italic">All patients are currently enrolled</p>
                  )}
                </div>
              </div>
            </div>
          )}
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={activePatients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={activePatients} studyGroups={studyGroups} onUpload={d => { 
          if (d.surgeryDate) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid ? { ...p, dateOfSurgery: d.surgeryDate } : p));
          }
          if (d.studyGroup) {
            setPatients(prev => prev.map(p => p.uhid === d.uhid && !p.studyGroupIds.includes(d.studyGroup) ? { ...p, studyGroupIds: [...p.studyGroupIds, d.studyGroup] } : p));
          }
        }} />;
      case 'research': return (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <div><h2 className="text-xl font-black text-slate-900 tracking-tight">Research Clusters</h2></div>
            <div className="flex gap-2">
              <button onClick={() => setShowExportModal(true)} className="flex items-center gap-2 border border-slate-200 bg-white px-3 py-1.5 rounded-lg text-[10px] font-black text-slate-700 uppercase tracking-widest hover:bg-slate-50 transition-all"><FileSpreadsheet size={14} /> Export Sheet</button>
              <button onClick={() => setShowAddStudyModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-widest hover:bg-teal-700 transition-all"><Plus size={14} /> New Study</button>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-md transition-all group cursor-pointer flex flex-col">
                <div className="w-8 h-8 bg-teal-50 text-teal-600 rounded-lg flex items-center justify-center mb-3 transition-all group-hover:bg-teal-600 group-hover:text-white"><Library size={16} /></div>
                <h3 className="font-bold text-slate-900 text-sm mb-1">{group.name}</h3>
                <p className="text-slate-400 text-[11px] font-medium line-clamp-2 h-8">{group.description}</p>
                <div className="flex justify-between items-center pt-3 border-t border-slate-50 mt-3">
                  <span className="text-teal-700 font-bold text-[9px] uppercase tracking-tighter">{activePatients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  <Edit3 size={12} className="text-slate-300 group-hover:text-teal-600" />
                </div>
              </div>
            ))}
          </div>
        </div>
      );
      case 'recycle': return (
        <RecycleBin 
          deletedPatients={deletedPatients} 
          onRestore={(p) => setSecurityContext({ type: 'restore', patient: p })}
          onPermanentDelete={(p) => setSecurityContext({ type: 'hard-delete', patient: p })}
        />
      );
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 relative overflow-hidden">
        <div className="max-w-xs w-full text-center animate-in fade-in zoom-in-95 duration-500">
          <div className="mb-6">
            <OpusLogo size="md" className="mx-auto mb-3 shadow-lg rounded-xl" />
            <h1 className="text-2xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.2em] text-[8px]">Operative Photo Unite and Store</p>
          </div>
          <div className="bg-white rounded-[2rem] p-8 border border-slate-100 shadow-xl">
            {!isLinked ? (
              <div className="space-y-4">
                <button 
                  onClick={handleGoogleAuth} 
                  className="w-full flex items-center justify-center gap-2 bg-slate-900 text-white py-3 rounded-xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98]"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Sign in with Google
                </button>
                <div className="flex items-center justify-center gap-2 text-[10px] font-bold text-slate-300 uppercase tracking-widest pt-2">
                  <Fingerprint size={14} /> Biometric Ready
                </div>
              </div>
            ) : (
              <div className="space-y-4 animate-in slide-in-from-bottom-2">
                <div className="flex items-center gap-3 bg-teal-50 p-3 rounded-xl border border-teal-100">
                  <img src="https://ui-avatars.com/api/?name=Dr+Smith&background=0d9488&color=fff" className="w-10 h-10 rounded-lg" alt="Profile" />
                  <div className="text-left">
                    <p className="font-bold text-slate-900 text-sm">Dr. Alexander Smith</p>
                    <p className="text-[9px] text-teal-600 font-black uppercase tracking-widest">Authenticated</p>
                  </div>
                </div>
                <div className="flex flex-col items-center gap-2 text-slate-400">
                   <div className="w-12 h-12 rounded-full bg-slate-50 flex items-center justify-center text-teal-500 animate-pulse">
                      <Fingerprint size={24} />
                   </div>
                   <p className="text-[10px] font-bold uppercase tracking-[0.2em]">Touch to Unlock</p>
                </div>
              </div>
            )}
          </div>
          <p className="mt-6 text-[8px] text-slate-300 font-bold uppercase tracking-[0.4em]">Hand & Microvascular Surgery Core</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen}
        deletedCount={deletedPatients.length}
      />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <div className="flex items-center justify-between px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md">
          <div className="flex items-center gap-2">
            <div className="lg:hidden"><OpusLogo size="sm" className="rounded-lg shadow-sm" /></div>
            <div className="hidden lg:block font-bold text-slate-300 text-[9px] uppercase tracking-[0.3em]">Dr. Smith • Microvascular Terminal</div>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-1.5 bg-teal-50 px-2 py-1 rounded-lg border border-teal-100">
              <div className="w-1 h-1 rounded-full bg-teal-500 animate-pulse"></div>
              <span className="text-[8px] font-black text-teal-700 uppercase">Drive Secure</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-600"><Menu size={18} /></button>
          </div>
        </div>

        <div className="px-6 py-4 max-w-[1200px] mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-md z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-8 animate-in zoom-in-95 text-center space-y-6">
            <div className="mx-auto w-20 h-20 bg-slate-50 border border-slate-100 rounded-2xl flex items-center justify-center text-slate-900">
              {isVerifying ? (
                <div className="w-10 h-10 border-4 border-teal-600/30 border-t-teal-600 rounded-full animate-spin" />
              ) : (
                <Fingerprint size={40} className="text-teal-600 animate-pulse" />
              )}
            </div>

            <div className="space-y-2">
              <h2 className="text-lg font-black text-slate-900 tracking-tight uppercase">Security Check Required</h2>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
                Verification for: <span className="text-slate-900">{securityContext.type === 'soft-delete' ? 'Archiving' : securityContext.type === 'hard-delete' ? 'Purging' : 'Restoring'}</span>
              </p>
              <div className="bg-slate-50 p-3 rounded-xl border border-slate-100">
                 <p className="text-xs font-bold text-slate-600">{securityContext.patient.name}</p>
                 <p className="text-[9px] font-mono text-slate-400">{securityContext.patient.uhid}</p>
              </div>
            </div>

            <div className="space-y-3">
              <div className="relative">
                <KeyRound className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input 
                  type="password" 
                  placeholder="Enter Vault Key or use TouchID"
                  className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-teal-500/20"
                  value={verificationInput}
                  onChange={(e) => setVerificationInput(e.target.value)}
                  autoFocus
                />
              </div>

              <div className="flex gap-3">
                <button 
                  onClick={() => { setSecurityContext(null); setVerificationInput(''); }}
                  className="flex-1 py-3 text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-600 transition-colors"
                >
                  Cancel
                </button>
                <button 
                  disabled={isVerifying || (!verificationInput && !isLinked)}
                  onClick={processSecurityAction}
                  className="flex-1 bg-slate-900 text-white py-3 rounded-xl text-[10px] font-black uppercase tracking-widest shadow-lg active:scale-[0.98] disabled:opacity-50 transition-all"
                >
                  Verify Access
                </button>
              </div>
            </div>

            <div className="flex items-center justify-center gap-1.5 pt-2">
               <div className="w-1 h-1 rounded-full bg-teal-500"></div>
               <span className="text-[8px] font-black text-teal-600 uppercase tracking-[0.2em]">End-to-End Encrypted Verification</span>
            </div>
          </div>
        </div>
      )}

      {/* App Modals (Study, Export, Edit) */}
      {showAddStudyModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-sm uppercase tracking-widest"><h2>Initialize Study</h2><button onClick={() => setShowAddStudyModal(false)}><X size={16} /></button></div>
            <form onSubmit={handleCreateStudy} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Study Name</label><input required value={newStudy.name} onChange={e => setNewStudy({...newStudy, name: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs outline-none focus:border-teal-500" placeholder="e.g. Nerve Repair 2024" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={newStudy.description} onChange={e => setNewStudy({...newStudy, description: e.target.value})} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs outline-none focus:border-teal-500 resize-none" /></div>
              <button type="submit" className="w-full bg-teal-600 text-white font-black py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest">Create Research Unit</button>
            </form>
          </div>
        </div>
      )}

      {showExportModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4 font-black text-[10px] uppercase tracking-widest">
              <h2>Select Groups to Export</h2>
              <button onClick={() => setShowExportModal(false)} className="text-slate-400 hover:text-slate-600"><X size={16} /></button>
            </div>
            <div className="space-y-2 mb-6 max-h-60 overflow-y-auto pr-1">
              {studyGroups.map(group => (
                <button 
                  key={group.id} 
                  onClick={() => setExportSelection(prev => prev.includes(group.id) ? prev.filter(id => id !== group.id) : [...prev, group.id])} 
                  className={`w-full text-left p-3 rounded-xl border transition-all flex items-center justify-between text-[11px] ${exportSelection.includes(group.id) ? 'border-teal-500 bg-teal-50 text-teal-700 font-bold' : 'border-slate-50 hover:border-slate-200'}`}
                >
                  <span>{group.name}</span>
                  {exportSelection.includes(group.id) ? <CheckCircle2 size={14} /> : <div className="w-3.5 h-3.5 rounded-full border border-slate-200" />}
                </button>
              ))}
            </div>
            <button 
              onClick={handleExportAction} 
              disabled={isExporting}
              className="w-full bg-teal-600 text-white font-black py-3.5 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest hover:bg-teal-700 transition-all active:scale-[0.98] disabled:opacity-50"
            >
              {isExporting ? <div className="w-3.5 h-3.5 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <Download size={16} />}
              Generate Clinical Report
            </button>
          </div>
        </div>
      )}

      {editingStudyGroup && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4"><h2 className="text-sm font-bold">Edit Study</h2><button onClick={() => setEditingStudyGroup(null)}><X size={16} /></button></div>
            <form onSubmit={(e) => { e.preventDefault(); setEditingStudyGroup(null); }} className="space-y-4">
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Name</label><input required value={editingStudyGroup.name} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg font-bold text-xs" /></div>
              <div><label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Description</label><textarea value={editingStudyGroup.description} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-16 font-bold text-xs" /></div>
              <button type="submit" className="w-full bg-slate-900 text-white font-bold py-3 rounded-xl shadow-lg text-xs uppercase tracking-widest"><Save size={14} className="inline mr-1" /> Update Metadata</button>
            </form>
          </div>
        </div>
      )}

      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-[10px] font-black uppercase tracking-widest">Edit Patient Clinical Data</h2>
              <button onClick={() => setPatientToEdit(null)}><X size={16} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-4">
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">UHID (Read Only)</label>
                <input value={patientToEdit.uhid} readOnly className="w-full px-3 py-1.5 bg-slate-100 rounded-lg border border-slate-100 font-bold text-[11px] outline-none" />
              </div>
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Full Name</label>
                <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
              </div>
              <div>
                <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest mb-1">Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px] h-16 resize-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl font-black text-[10px] uppercase tracking-[0.2em]">Update Core Registry</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import RecycleBin from './views/RecycleBin';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, Edit3, Save, LogOut, Fingerprint, FileText,
  Download, UserPlus, Trash2, Edit, KeyRound
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [user, setUser] = useState<{name: string, email: string, avatar: string} | null>(null);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showEnrollModal, setShowEnrollModal] = useState(false);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const [isExporting, setIsExporting] = useState(false);
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);
  const [exportSelection, setExportSelection] = useState<string[]>([]);
  const [newStudy, setNewStudy] = useState({ name: '', description: '' });

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const handleGoogleAuth = () => {
    // Simulate fetching Google account details
    setUser({
      name: 'Dr. Alexander Smith',
      email: 'a.smith@surgical.org',
      avatar: 'https://ui-avatars.com/api/?name=Alexander+Smith&background=0d9488&color=fff'
    });
    setIsLinked(true);
  };

  const handleFinalLogin = () => {
    setIsLoggedIn(true);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) setSelectedPatient(updated);
    if (patientToEdit?.uhid === updated.uhid) setPatientToEdit(null);
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);
    setTimeout(() => {
      const { type, patient } = securityContext;
      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p));
        setSelectedPatient(null);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p));
      }
      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 800);
  };

  const handleCreateStudy = (e: React.FormEvent) => {
    e.preventDefault();
    if (newStudy.name) {
      const group: StudyGroup = {
        id: `sg${Date.now()}`,
        name: newStudy.name,
        description: newStudy.description,
        patientCount: 0,
        driveFolderId: `DRV_${Math.random().toString(36).substr(2, 6).toUpperCase()}`
      };
      setStudyGroups(prev => [...prev, group]);
      setNewStudy({ name: '', description: '' });
      setShowAddStudyModal(false);
    }
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => setActiveView('upload')}
          onUpdatePatient={handleUpdatePatient}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolled = activePatients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-4 max-w-5xl mx-auto">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors">
              &larr; Back to Groups
            </button>
            <div className="flex gap-2">
              <button onClick={() => setShowEnrollModal(true)} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 shadow-sm">
                <UserPlus size={14} /> Enroll
              </button>
              <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest">
                <Edit3 size={14} />
              </button>
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex justify-between items-center">
            <div>
              <h2 className="text-lg font-bold text-slate-900">{selectedStudyGroup.name}</h2>
              <p className="text-slate-400 text-xs mt-0.5">{selectedStudyGroup.description}</p>
            </div>
            <div className="text-right">
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Repository</p>
              <p className="text-xs font-mono font-bold text-teal-600">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {enrolled.map(p => (
              <div key={p.uhid} className="bg-white p-3 rounded-xl border border-slate-100 flex items-center gap-3 cursor-pointer hover:border-teal-500 transition-all" onClick={() => setSelectedPatient(p)}>
