          <div className="bg-white/80 backdrop-blur-xl border border-white rounded-[2.5rem] p-8 shadow-2xl space-y-6">
            {!isLinked ? (
              <div className="space-y-4">
                <p className="text-center text-xs font-medium text-slate-500 mb-6 px-4">Link your institutional Google ID to access the clinical database.</p>
                <button 
                  onClick={handleGoogleAuth}
                  className="w-full flex items-center justify-center gap-3 bg-slate-900 text-white py-3.5 rounded-2xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98] shadow-lg"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Continue with Google
                </button>
              </div>
            ) : (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                <div className="text-center">
                  <div className="relative inline-block">
                    <img src={user?.avatar} className="w-20 h-20 rounded-3xl shadow-md border-2 border-white mx-auto mb-3" alt="User" />
                    <div className="absolute -bottom-1 -right-1 bg-teal-500 text-white p-1 rounded-full border-2 border-white">
                      <CheckCircle2 size={14} />
                    </div>
                  </div>
                  <h2 className="text-lg font-bold text-slate-900">{user?.name}</h2>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{user?.email}</p>
                </div>

                <button 
                  onClick={handleFinalLogin}
                  className="w-full bg-teal-600 text-white py-3.5 rounded-2xl font-bold text-sm shadow-xl hover:bg-teal-700 transition-all flex items-center justify-center gap-2 group"
                >
                  <Fingerprint size={18} className="group-hover:scale-110 transition-transform" />
                  Unlock Terminal
                </button>
              </div>
            )}
          </div>

          <p className="text-center mt-12 text-[7px] text-slate-300 font-black uppercase tracking-[0.5em]">HIPAA Compliant • End-to-End Encrypted</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false); setUser(null);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen}
        deletedCount={deletedPatients.length}
      />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <header className="px-6 py-3 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="lg:hidden"><OpusLogo size="sm" /></div>
             <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{activeView}</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2 bg-slate-50 px-3 py-1.5 rounded-full border border-slate-100">
               <img src={user?.avatar} className="w-5 h-5 rounded-full" alt="" />
               <span className="text-[10px] font-bold text-slate-700">{user?.name.split(' ').pop()}</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-400"><Menu size={18} /></button>
          </div>
        </header>

        <div className="px-6 py-6 max-w-6xl mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xs rounded-3xl shadow-2xl p-6 animate-in zoom-in-95 text-center space-y-4">
            <div className="mx-auto w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-teal-600">
              {isVerifying ? <div className="w-6 h-6 border-2 border-teal-600/30 border-t-teal-600 rounded-full animate-spin" /> : <KeyRound size={24} />}
            </div>
            <div className="space-y-1">
              <h2 className="text-sm font-bold text-slate-900 uppercase tracking-tight">Access Required</h2>
              <p className="text-[10px] text-slate-400 uppercase font-bold tracking-widest">{securityContext.type}</p>
            </div>
            <input 
              type="password" 
              placeholder="Vault Key"
              className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold outline-none text-center"
