import React, { useState } from 'react';
import { ArrowLeft, Plus, Download, X, Edit, Columns, CloudUpload, HardDrive, CheckCircle2, PlayCircle, Trash2 } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, MediaEntry, MediaType } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient, onDeletePatient }) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showEditModal, setShowEditModal] = useState(false);
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);

  // Added missing state for editing patient details
  const [editPatient, setEditPatient] = useState<Patient>(patient);

  const filteredMedia = [...MOCK_MEDIA].filter(m => m.uhid === patient.uhid && m.surgeryId === activeSurgeryId && m.stage === activeStage);

  // Synchronize editPatient state when the modal opens to ensure it has the latest patient data
  const handleOpenEditModal = () => {
    setEditPatient({ ...patient });
    setShowEditModal(true);
  };

  return (
    <div className="space-y-4">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-slate-900">&larr; Dashboard</button>
        <button onClick={onAddMedia} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest shadow-sm">Capture Media</button>
      </div>

      <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="flex gap-4 items-center">
          <div className="w-10 h-10 bg-teal-600 text-white rounded-xl flex items-center justify-center font-bold">{patient.name.charAt(0)}</div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-base font-bold text-slate-900">{patient.name}</h1>
              <span className="text-[9px] font-mono font-bold text-slate-300">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">{patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} &bull; {patient.surgeries.length} History</p>
          </div>
        </div>
        <div className="flex-1 max-w-md bg-slate-50 px-3 py-2 rounded-xl border border-slate-100 flex items-center gap-3">
          <HardDrive size={14} className="text-teal-600" />
          <p className="text-[11px] text-slate-600 italic line-clamp-1">{patient.diagnosis}</p>
        </div>
        <div className="flex gap-1">
          {/* Updated to use handleOpenEditModal to initialize edit state correctly */}
          <button onClick={handleOpenEditModal} className="p-2 bg-slate-50 text-slate-400 rounded-lg border border-slate-100"><Edit size={14} /></button>
          <button onClick={() => onDeletePatient(patient)} className="p-2 bg-slate-50 text-slate-400 hover:text-red-500 rounded-lg border border-slate-100"><Trash2 size={14} /></button>
        </div>
      </div>

      <div className="flex gap-1 overflow-x-auto pb-1 no-scrollbar">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-4 py-2 rounded-xl border text-[10px] font-bold uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-md' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-200'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden flex flex-col">
        <div className="flex bg-slate-50 p-1 gap-1">
          {Object.values(SurgicalStage).map(stage => (
            <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-2 text-[9px] font-bold uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400'}`}>
              {stage}
            </button>
          ))}
        </div>
        <div className="p-4">
          <div className="grid grid-cols-2 sm:grid-cols-4 lg:grid-cols-5 gap-3">
            {filteredMedia.map(m => (
              <div key={m.id} className="group relative aspect-square rounded-xl overflow-hidden border border-slate-50 bg-slate-100">
                {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                  <video src={m.url} autoPlay controls className="w-full h-full object-cover" />
                ) : (
                  <>
                    <img src={m.thumbnailUrl || m.url} className="w-full h-full object-cover group-hover:scale-105 transition-transform" />
                    {m.type === MediaType.VIDEO && (
                      <div className="absolute inset-0 flex items-center justify-center cursor-pointer" onClick={() => setPlayingVideoId(m.id)}>
                        <div className="bg-black/20 backdrop-blur-sm p-3 rounded-full text-white"><PlayCircle size={24} /></div>
                      </div>
                    )}
                    <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                       <button className="p-1.5 bg-white/20 backdrop-blur-md rounded-lg text-white"><Download size={10} /></button>
                    </div>
                  </>
                )}
              </div>
            ))}
            {filteredMedia.length === 0 && <div className="col-span-full py-12 text-center text-slate-200 font-bold uppercase tracking-widest text-[10px]">Empty Section</div>}
          </div>
        </div>
      </div>

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xs rounded-2xl p-6 shadow-2xl animate-in zoom-in-95">
            <h2 className="text-[10px] font-bold uppercase tracking-widest mb-4">Edit Clinical Data</h2>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-3">
              <input value={editPatient.name} onChange={e => setEditPatient({...editPatient, name: e.target.value})} className="w-full px-3 py-2 bg-slate-50 rounded-lg text-xs font-bold" placeholder="Patient Name" />
              <textarea value={editPatient.diagnosis} onChange={e => setEditPatient({...editPatient, diagnosis: e.target.value})} className="w-full px-3 py-2 bg-slate-50 rounded-lg text-xs font-bold h-20 resize-none" placeholder="Diagnosis" />
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl text-[10px] font-bold uppercase tracking-widest">Update Vault</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

