import React, { useState } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, CloudUpload, FileText, Plus } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video';
  thumbnailUrl?: string;
  base64?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [notes, setNotes] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = patients.find(p => p.uhid === selectedPatientId);

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = () => resolve(reader.result?.toString().split(',')[1] || '');
      reader.onerror = error => reject(error);
    });
  };

  const generateVideoThumbnail = (file: File): Promise<string> => {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      const videoUrl = URL.createObjectURL(file);
      video.src = videoUrl;
      video.preload = 'metadata';
      video.muted = true;
      video.playsInline = true;

      video.onloadedmetadata = () => {
        video.currentTime = Math.min(0.5, video.duration / 2);
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          const dataUrl = canvas.toDataURL('image/jpeg');
          URL.revokeObjectURL(videoUrl);
          resolve(dataUrl);
        } else {
          URL.revokeObjectURL(videoUrl);
          resolve('');
        }
      };

      video.onerror = () => {
        URL.revokeObjectURL(videoUrl);
        resolve('');
      };
    });
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processPromises = files.map(async (file): Promise<PreviewFile> => {
        const type: 'image' | 'video' = file.type.startsWith('video/') ? 'video' : 'image';
        const url = URL.createObjectURL(file);
        let thumbnailUrl: string | undefined;
        let base64: string | undefined;
        if (type === 'video') {
          thumbnailUrl = await generateVideoThumbnail(file);
        } else {
          base64 = await fileToBase64(file);
        }
        return { url, file, type, thumbnailUrl, base64 };
      });
      const processedFiles = await Promise.all(processPromises);
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;

    if (!surgeryId && !showNewSurgeryForm) {
      alert("Please select or register a surgery event.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        surgeryId: showNewSurgeryForm ? `surg_${Date.now()}` : surgeryId,
        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate, otNotes: otNotes } : null,
        otNotes: otNotes,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        tags: customTags.split(',').filter(t => t.trim()),
        notes,
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length
      });
      setIsUploading(false);
      setShowSuccess(true);
      previewFiles.forEach(f => URL.revokeObjectURL(f.url));
      setPreviewFiles([]);
      setCustomTags('');
      setNotes('');
      setOtNotes('');
      setSelectedPatientId('');
      setSurgeryId('');
      setShowNewSurgeryForm(false);
    }, 1200);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xs mx-auto py-12 text-center space-y-6 animate-in zoom-in-95">
        <div className="w-14 h-14 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center mx-auto shadow-sm border border-teal-100">
          <CheckCircle2 size={28} />
        </div>
        <div className="space-y-1">
          <h2 className="text-lg font-bold text-slate-900 tracking-tight italic">Assest Committed</h2>
          <p className="text-slate-400 font-bold text-[9px] uppercase tracking-widest">Entry Locked in Repository</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg text-[10px] uppercase tracking-widest transition-transform active:scale-95">
          New Intake Session
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4 max-w-4xl mx-auto">
      <div>
        <h1 className="text-lg font-bold text-slate-900">Intake Portal</h1>
        <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest">Clinical Data Synchronizer</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-5">
        <div className="lg:col-span-5 space-y-3">
          <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm space-y-4">
            <h2 className="text-[9px] font-bold uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2">
              <Database size={12} /> Target Metadata
            </h2>
            <div>
              <label className="block text-[8px] font-bold text-slate-400 uppercase mb-1">Select Patient *</label>
              <select className="w-full px-3 py-2 bg-slate-50 border border-slate-50 rounded-lg font-bold text-slate-900 text-xs" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Patient lookup...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-3 animate-in fade-in duration-300">
                <div className="flex justify-between items-center">
                  <label className="block text-[8px] font-bold text-slate-400 uppercase">Procedure Event</label>
                  <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-bold text-teal-600 uppercase">
                    {showNewSurgeryForm ? 'Existing' : 'Register New'}
                  </button>
                </div>

                {!showNewSurgeryForm ? (
                  <select className="w-full px-3 py-2 bg-slate-50 border border-slate-50 rounded-lg font-bold text-slate-900 text-xs" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                    <option value="">Select event...</option>
                    {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                  </select>
                ) : (
                  <div className="space-y-2 p-3 bg-slate-50 rounded-xl border border-slate-100">
                     <input required placeholder="Procedure Title" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-slate-200" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                     <input required type="date" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-slate-200" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                  </div>
                )}

                <div>
                  <label className="block text-[8px] font-bold text-slate-400 uppercase mb-1">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-1">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-3 py-1.5 rounded-lg border text-[10px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                        {s}{stage === s && <CheckCircle2 size={10} />}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-1">
                  <label className="block text-[8px] font-bold text-slate-400 uppercase">Operative (OT) Notes</label>
                  <textarea value={otNotes} onChange={e => setOtNotes(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-50 rounded-lg h-16 text-xs font-bold resize-none" placeholder="Procedure details..." />
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-7 space-y-3">
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm space-y-4">
            <div className="group relative p-6 border-2 border-dashed border-slate-100 rounded-xl bg-slate-50/50 hover:bg-white hover:border-teal-200 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[140px]">
              <input type="file" multiple accept="image/*,video/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-2 bg-white rounded-lg shadow-sm text-slate-300 mb-2 group-hover:text-teal-500 transition-colors"><Camera size={20} /></div>
              <p className="text-xs font-bold text-slate-900">Upload Media</p>
              <p className="text-slate-400 text-[8px] font-bold uppercase tracking-widest mt-0.5">JPG / PNG / MP4 Master Quality</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-5 sm:grid-cols-6 gap-2">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-lg overflow-hidden border border-slate-100 bg-slate-50">
                    <img src={fileData.thumbnailUrl || fileData.url} className="w-full h-full object-cover" />
                    <button type="button" onClick={() => removeFile(i)} className="absolute top-1 right-1 p-1 bg-black/50 text-white rounded-md opacity-0 group-hover:opacity-100 transition-opacity">
                      <Trash2 size={8} />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className="space-y-1">
              <label className="block text-[8px] font-bold text-slate-400 uppercase flex items-center gap-1"><FileText size={10} /> Media Caption</label>
              <textarea value={notes} onChange={e => setNotes(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-50 rounded-lg h-16 font-bold text-xs outline-none focus:border-teal-500 resize-none" placeholder="Specific notes for this media set..." />
            </div>

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest mt-2 active:scale-95 transition-all disabled:opacity-50"
            >
              {isUploading ? <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={14} />}
              Commit Assets
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

import React, { useState } from 'react';
import { ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, FileText, CheckCircle2 } from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ patient, onBack, onAddMedia, onUpdatePatient, onDeletePatient }) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [showEditModal, setShowEditModal] = useState(false);
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);
  const [editPatient, setEditPatient] = useState<Patient>(patient);

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = [...MOCK_MEDIA].filter(m => m.uhid === patient.uhid && m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const handleOpenEditModal = () => {
    setEditPatient({ ...patient });
    setShowEditModal(true);
  };

  const handleDownload = async (media: MediaEntry) => {
    try {
      const response = await fetch(media.url);
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `HQ_${patient.uhid}_${media.stage}_${Date.now()}.${media.type === MediaType.VIDEO ? 'mp4' : 'jpg'}`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
    } catch (e) {
      alert("HQ Download failed. Check network permissions.");
    }
  };

  return (
    <div className="space-y-4 max-w-5xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="text-[9px] font-bold text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors flex items-center gap-1">
          <ArrowLeft size={10} /> Registry Dashboard
        </button>
        <button onClick={onAddMedia} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[9px] font-bold uppercase tracking-widest shadow-sm hover:bg-teal-700 transition-all active:scale-95 flex items-center gap-1.5">
          <Plus size={12} /> Intake Session
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="flex gap-4 items-center">
          <div className="w-10 h-10 bg-teal-600 text-white rounded-xl flex items-center justify-center font-bold text-sm shadow-md">{patient.name.charAt(0)}</div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-sm font-bold text-slate-900">{patient.name}</h1>
              <span className="text-[8px] font-mono font-bold text-slate-300 bg-slate-50 px-1 rounded border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest leading-none mt-1">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} &bull; {patient.primarySurgeon}
            </p>
          </div>
        </div>
        <div className="flex-1 max-w-md bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100 flex items-center gap-3">
          <HardDrive size={12} className="text-teal-600 shrink-0" />
          <p className="text-[10px] text-slate-600 italic line-clamp-1">{patient.diagnosis}</p>
        </div>
        <div className="flex gap-1">
          <button onClick={handleOpenEditModal} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg border border-slate-100 hover:text-teal-600 hover:bg-white transition-all shadow-sm"><Edit size={12} /></button>
          <button onClick={() => onDeletePatient(patient)} className="p-1.5 bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg border border-slate-100 transition-all shadow-sm"><Trash2 size={12} /></button>
        </div>
      </div>

      <div className="flex gap-1 overflow-x-auto pb-1 no-scrollbar scroll-smooth">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-3 py-1.5 rounded-xl border text-[9px] font-bold uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-md scale-105 z-10' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-200'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
        {/* Left Column: Media */}
        <div className="lg:col-span-8 bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden flex flex-col h-fit">
          <div className="flex bg-slate-50 p-1 gap-1">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-1.5 text-[8px] font-bold uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-3">
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative aspect-square rounded-xl overflow-hidden border border-slate-50 bg-slate-100 shadow-sm">
                  {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                    <video src={m.url} autoPlay controls className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <img src={m.thumbnailUrl || m.url} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                      {m.type === MediaType.VIDEO && (
                        <div className="absolute inset-0 flex items-center justify-center cursor-pointer" onClick={() => setPlayingVideoId(m.id)}>
                          <div className="bg-black/20 backdrop-blur-sm p-2.5 rounded-full text-white"><PlayCircle size={20} /></div>
                        </div>
                      )}
                      <div className="absolute top-1.5 right-1.5 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                         <button onClick={() => handleDownload(m)} className="p-1 bg-white/40 backdrop-blur-md rounded-lg text-white hover:bg-teal-600 transition-colors" title="HQ Download"><Download size={10} /></button>
                      </div>
                    </>
                  )}
                </div>
              ))}
              {filteredMedia.length === 0 && <div className="col-span-full py-10 text-center text-slate-200 font-bold uppercase tracking-widest text-[9px] italic">Registry segment empty</div>}
            </div>
          </div>
        </div>

        {/* Right Column: OT Notes */}
        <div className="lg:col-span-4 space-y-3">
          <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm h-full">
            <h3 className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-3 flex items-center gap-1.5">
              <FileText size={12} className="text-teal-600" /> Operative (OT) Notes
            </h3>
            <div className="bg-slate-50 p-3 rounded-xl border border-slate-100 min-h-[120px]">
               {currentSurgery?.otNotes ? (
                 <p className="text-xs text-slate-600 leading-relaxed font-medium whitespace-pre-wrap">{currentSurgery.otNotes}</p>
               ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-300 py-6">
                    <p className="text-[8px] font-bold uppercase">No OT notes uploaded</p>
                 </div>
               )}
            </div>
            {currentSurgery && (
              <p className="text-[7px] font-bold text-slate-300 uppercase mt-2 text-right tracking-tighter">Verified Procedure Date: {currentSurgery.date}</p>
            )}
          </div>
        </div>
      </div>

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95 my-auto">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-[10px] font-bold uppercase tracking-widest text-slate-900">Update Clinical Entry</h2>
              <button onClick={() => setShowEditModal(false)}><X size={16} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-3">
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Registry UHID</label>
                <input value={editPatient.uhid} onChange={e => setEditPatient({...editPatient, uhid: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
              </div>
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Patient Name</label>
                <input value={editPatient.name} onChange={e => setEditPatient({...editPatient, name: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
              </div>
              <div className="grid grid-cols-2 gap-2">
                <div className="space-y-0.5">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">Age (Y)</label>
                  <input type="number" value={editPatient.ageYears} onChange={e => setEditPatient({...editPatient, ageYears: parseInt(e.target.value) || 0})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
                </div>
                <div className="space-y-0.5">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">Age (M)</label>
                  <input type="number" value={editPatient.ageMonths || 0} onChange={e => setEditPatient({...editPatient, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
                </div>
              </div>
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Lead Surgeon</label>
                <input value={editPatient.primarySurgeon} onChange={e => setEditPatient({...editPatient, primarySurgeon: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
              </div>
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Final Diagnosis</label>
                <textarea value={editPatient.diagnosis} onChange={e => setEditPatient({...editPatient, diagnosis: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold h-16 border border-slate-100 resize-none" />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-lg active:scale-95 transition-all">Save Synchronized Changes</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React, { useState } from 'react';
import { Search, Plus, User, X, Calendar } from 'lucide-react';
import { Patient, SurgeryEvent } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, studyGroups, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Primary Admission', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="space-y-5 animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <h1 className="text-lg font-bold text-slate-900 tracking-tight">Clinical Registry</h1>
        <button onClick={() => setShowModal(true)} className="flex items-center gap-2 bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[9px] font-bold uppercase tracking-widest shadow-sm hover:bg-teal-700 transition-all active:scale-95">
          <Plus size={14} /> New Record
        </button>
      </div>

      <div className="relative max-w-lg mx-auto">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
        <input 
          type="text" placeholder="Search entries by ID or name..."
          className="w-full pl-9 pr-4 py-2 bg-white border border-slate-100 rounded-xl outline-none focus:ring-1 focus:ring-teal-500/20 transition-all text-xs font-medium shadow-sm"
          value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3.5">
        {filtered.map(p => (
          <div key={p.uhid} onClick={() => onSelectPatient(p)} className="bg-white p-4 rounded-2xl border border-slate-100 hover:border-teal-400 transition-all cursor-pointer shadow-sm group">
            <div className="flex justify-between items-center mb-3">
              <div className="w-8 h-8 bg-slate-50 rounded-lg flex items-center justify-center text-slate-300 group-hover:text-teal-600 group-hover:bg-teal-50 transition-colors shadow-sm"><User size={14} /></div>
              <span className="font-mono text-[8px] font-bold text-slate-300 bg-slate-50 px-1 rounded">{p.uhid}</span>
            </div>
            <h3 className="font-bold text-slate-900 text-xs truncate group-hover:text-teal-700 transition-colors">{p.name}</h3>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-tight mb-2">{p.ageYears}y {p.ageYears <= 2 ? `${p.ageMonths || 0}m` : ''} &bull; {p.primarySurgeon}</p>
            <div className="bg-slate-50/50 p-2 rounded-lg mb-3">
              <p className="text-slate-500 text-[10px] italic leading-tight line-clamp-2 h-7">"{p.diagnosis}"</p>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-[8px] font-bold text-slate-300 uppercase tracking-widest flex items-center gap-1">
                <Calendar size={10} /> {p.dateOfSurgery || 'Pending'}
              </span>
              <span className="text-[7px] font-bold text-teal-600 uppercase bg-teal-50 px-1.5 py-0.5 rounded border border-teal-100">{p.studyGroupIds[0] || 'Unassigned'}</span>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xs rounded-2xl shadow-2xl animate-in zoom-in-95 overflow-hidden">
            <div className="p-4 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
              <h2 className="text-[10px] font-bold uppercase tracking-widest text-slate-900">Patient Registration</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-900"><X size={16} /></button>
            </div>
            <form onSubmit={handleSubmit} className="p-4 space-y-3">
              <input required placeholder="Registry UHID" className="w-full px-3 py-2 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
              <input required placeholder="Patient Full Name" className="w-full px-3 py-2 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-2">
                <input type="number" placeholder="Age (Y)" className="w-full px-3 py-2 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
                <input type="date" className="w-full px-3 py-2 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} />
              </div>
              <textarea required placeholder="Clinical Diagnosis" className="w-full px-3 py-2 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100 h-20 resize-none" onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              <button type="submit" className="w-full bg-teal-600 text-white font-bold py-2.5 rounded-xl text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 transition-all">Commit to Repository</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { LayoutDashboard, Upload, Library, LogOut, X, Trash2 } from 'lucide-react';

interface SidebarProps {
  activeView: string;
  setActiveView: (view: string) => void;
  onLogout: () => void;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  deletedCount: number;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, setActiveView, onLogout, isOpen, setIsOpen, deletedCount }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'upload', label: 'Intake Portal', icon: Upload },
    { id: 'research', label: 'Study Groups', icon: Library },
    { id: 'recycle', label: 'Archive Bin', icon: Trash2, count: deletedCount },
  ];

  return (
    <>
      {isOpen && <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsOpen(false)} />}
      <div className={`fixed left-0 top-0 h-screen w-64 bg-white border-r border-slate-100 flex flex-col z-50 transition-transform duration-300 ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 border-b border-slate-50 flex items-center justify-between">
          <span className="font-black text-xl tracking-tighter italic text-slate-900">OPUS</span>
          <button className="lg:hidden text-slate-400" onClick={() => setIsOpen(false)}><X size={18} /></button>
        </div>
        <nav className="flex-1 mt-6 px-6 space-y-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => { setActiveView(item.id); setIsOpen(false); }}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-2xl transition-all text-xs font-bold ${activeView === item.id ? 'bg-teal-600 text-white shadow-lg shadow-teal-600/10' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
            >
              <div className="flex items-center gap-3"><item.icon size={16} /><span>{item.label}</span></div>
              {item.count !== undefined && item.count > 0 && <span className={`text-[9px] px-1.5 py-0.5 rounded-full ${activeView === item.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'}`}>{item.count}</span>}
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-50">
          <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-2.5 text-slate-400 hover:text-red-500 transition-colors text-[10px] font-bold uppercase tracking-widest">
            <LogOut size={14} /><span>Logout Terminal</span>
          </button>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

