              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} &bull; {patient.primarySurgeon}
            </p>
          </div>
        </div>
        <div className="flex-1 max-w-md bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100 flex items-center gap-3">
          <HardDrive size={12} className="text-teal-600 shrink-0" />
          <p className="text-[10px] text-slate-600 italic line-clamp-1">{patient.diagnosis}</p>
        </div>
        <div className="flex gap-1">
          <button onClick={handleOpenEditModal} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg border border-slate-100 hover:text-teal-600 hover:bg-white transition-all shadow-sm"><Edit size={12} /></button>
          <button onClick={() => onDeletePatient(patient)} className="p-1.5 bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg border border-slate-100 transition-all shadow-sm"><Trash2 size={12} /></button>
        </div>
      </div>

      <div className="flex gap-1 overflow-x-auto pb-1 no-scrollbar scroll-smooth">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-3 py-1.5 rounded-xl border text-[9px] font-bold uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-md scale-105 z-10' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-200'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
        {/* Left Column: Media */}
        <div className="lg:col-span-8 bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden flex flex-col h-fit">
          <div className="flex bg-slate-50 p-1 gap-1">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-1.5 text-[8px] font-bold uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-3">
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative aspect-square rounded-xl overflow-hidden border border-slate-50 bg-slate-100 shadow-sm">
                  {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                    <video src={m.url} autoPlay controls className="w-full h-full object-cover" />
                  ) : (
                    <>
                      <img src={m.thumbnailUrl || m.url} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                      {m.type === MediaType.VIDEO && (
                        <div className="absolute inset-0 flex items-center justify-center cursor-pointer" onClick={() => setPlayingVideoId(m.id)}>
                          <div className="bg-black/20 backdrop-blur-sm p-2.5 rounded-full text-white"><PlayCircle size={20} /></div>
                        </div>
                      )}
                      <div className="absolute top-1.5 right-1.5 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                         <button onClick={() => handleDownload(m)} className="p-1 bg-white/40 backdrop-blur-md rounded-lg text-white hover:bg-teal-600 transition-colors" title="HQ Download"><Download size={10} /></button>
                      </div>
                    </>
                  )}
                </div>
              ))}
              {filteredMedia.length === 0 && <div className="col-span-full py-10 text-center text-slate-200 font-bold uppercase tracking-widest text-[9px] italic">Registry segment empty</div>}
            </div>
          </div>
        </div>

        {/* Right Column: OT Notes */}
        <div className="lg:col-span-4 space-y-3">
          <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm h-full">
            <h3 className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-3 flex items-center gap-1.5">
              <FileText size={12} className="text-teal-600" /> Operative (OT) Notes
            </h3>
            <div className="bg-slate-50 p-3 rounded-xl border border-slate-100 min-h-[120px]">
               {currentSurgery?.otNotes ? (
                 <p className="text-xs text-slate-600 leading-relaxed font-medium whitespace-pre-wrap">{currentSurgery.otNotes}</p>
               ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-300 py-6">
                    <p className="text-[8px] font-bold uppercase">No OT notes uploaded</p>
                 </div>
               )}
            </div>
            {currentSurgery && (
              <p className="text-[7px] font-bold text-slate-300 uppercase mt-2 text-right tracking-tighter">Verified Procedure Date: {currentSurgery.date}</p>
            )}
          </div>
        </div>
      </div>

      {showEditModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[150] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white w-full max-w-sm rounded-2xl p-6 shadow-2xl animate-in zoom-in-95 my-auto">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-[10px] font-bold uppercase tracking-widest text-slate-900">Update Clinical Entry</h2>
              <button onClick={() => setShowEditModal(false)}><X size={16} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); onUpdatePatient(editPatient); setShowEditModal(false); }} className="space-y-3">
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Registry UHID</label>
                <input value={editPatient.uhid} onChange={e => setEditPatient({...editPatient, uhid: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
              </div>
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Patient Name</label>
                <input value={editPatient.name} onChange={e => setEditPatient({...editPatient, name: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
              </div>
              <div className="grid grid-cols-2 gap-2">
                <div className="space-y-0.5">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">Age (Y)</label>
                  <input type="number" value={editPatient.ageYears} onChange={e => setEditPatient({...editPatient, ageYears: parseInt(e.target.value) || 0})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
                </div>
                <div className="space-y-0.5">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">Age (M)</label>
                  <input type="number" value={editPatient.ageMonths || 0} onChange={e => setEditPatient({...editPatient, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
                </div>
              </div>
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Lead Surgeon</label>
                <input value={editPatient.primarySurgeon} onChange={e => setEditPatient({...editPatient, primarySurgeon: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold border border-slate-100" />
              </div>
              <div className="space-y-0.5">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Final Diagnosis</label>
                <textarea value={editPatient.diagnosis} onChange={e => setEditPatient({...editPatient, diagnosis: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg text-xs font-bold h-16 border border-slate-100 resize-none" />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-2.5 rounded-xl text-[10px] font-bold uppercase tracking-widest shadow-lg active:scale-95 transition-all">Save Synchronized Changes</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import RecycleBin from './views/RecycleBin';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup, SurgeryEvent } from './types';
import { 
  Menu, Library, Plus, FileSpreadsheet, 
  X, HardDrive, CheckCircle2, Edit3, Save, LogOut, Fingerprint, FileText,
  Download, UserPlus, Trash2, Edit, KeyRound, ShieldCheck
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [user, setUser] = useState<{name: string, email: string, avatar: string} | null>(null);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups, setStudyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [selectedStudyGroup, setSelectedStudyGroup] = useState<StudyGroup | null>(null);
  // Added editingStudyGroup state to fix the error where setEditingStudyGroup was not found.
  const [editingStudyGroup, setEditingStudyGroup] = useState<StudyGroup | null>(null);

  const [showAddStudyModal, setShowAddStudyModal] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [showEnrollModal, setShowEnrollModal] = useState(false);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const handleGoogleAuth = () => {
    // Simulating Google account linkage
    setUser({
      name: 'Dr. Alexander Smith',
      email: 'a.smith@surgical.org',
      avatar: 'https://ui-avatars.com/api/?name=Alexander+Smith&background=0d9488&color=fff'
    });
    setIsLinked(true);
  };

  const handleFinalLogin = () => {
    setIsLoggedIn(true);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) setSelectedPatient(updated);
    if (patientToEdit?.uhid === updated.uhid) setPatientToEdit(null);
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);
    setTimeout(() => {
      const { type, patient } = securityContext;
      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p));
        setSelectedPatient(null);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p));
      }
      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 800);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    if (selectedStudyGroup) {
      const enrolled = activePatients.filter(p => p.studyGroupIds.includes(selectedStudyGroup.id));
      const unenrolled = activePatients.filter(p => !p.studyGroupIds.includes(selectedStudyGroup.id));
      return (
        <div className="space-y-4 max-w-5xl mx-auto">
          <div className="flex justify-between items-center">
            <button onClick={() => setSelectedStudyGroup(null)} className="text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors">
              &larr; Back to Groups
            </button>
            <div className="flex gap-2">
              <button onClick={() => setShowEnrollModal(true)} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest flex items-center gap-2 shadow-sm">
                <UserPlus size={14} /> Enroll
              </button>
              <button onClick={() => setEditingStudyGroup(selectedStudyGroup)} className="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest">
                <Edit3 size={14} />
              </button>
            </div>
          </div>
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm flex justify-between items-center">
            <div>
              <h2 className="text-lg font-bold text-slate-900">{selectedStudyGroup.name}</h2>
              <p className="text-slate-400 text-xs mt-0.5">{selectedStudyGroup.description}</p>
            </div>
            <div className="text-right">
              <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Repository</p>
              <p className="text-xs font-mono font-bold text-teal-600">{selectedStudyGroup.driveFolderId}</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-4 gap-3">
            {enrolled.map(p => (
              <div key={p.uhid} className="bg-white p-3 rounded-xl border border-slate-100 flex items-center gap-3 cursor-pointer hover:border-teal-500 transition-all" onClick={() => setSelectedPatient(p)}>
                <div className="w-8 h-8 bg-slate-50 text-slate-400 rounded-lg flex items-center justify-center font-bold text-xs">{p.name.charAt(0)}</div>
                <div className="overflow-hidden">
                  <p className="text-xs font-bold text-slate-900 truncate">{p.name}</p>
                  <p className="text-[9px] text-slate-400 font-mono">{p.uhid}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      );
    }

    switch (activeView) {
      case 'dashboard': return <Dashboard patients={activePatients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': return <UploadMedia patients={activePatients} studyGroups={studyGroups} onUpload={d => { 
          setPatients(prev => prev.map(p => {
            if (p.uhid === d.uhid) {
              const updatedSurgeries = [...p.surgeries];
              let newDateOfSurgery = p.dateOfSurgery;

              if (d.newSurgery) {
                const newSurg = {
                  id: d.surgeryId,
                  title: d.newSurgery.title,
                  date: d.newSurgery.date,
                  otNotes: d.newSurgery.otNotes // OT Notes saving fix
                };
                updatedSurgeries.push(newSurg);
                newDateOfSurgery = d.newSurgery.date;
              } else if (d.surgeryId) {
                const existingIndex = updatedSurgeries.findIndex(s => s.id === d.surgeryId);
                if (existingIndex > -1) {
                  // Update existing surgery with potential new OT notes
                  updatedSurgeries[existingIndex] = {
                    ...updatedSurgeries[existingIndex],
                    otNotes: d.otNotes || updatedSurgeries[existingIndex].otNotes
                  };
                  newDateOfSurgery = updatedSurgeries[existingIndex].date;
                }
              }

              return { 
                ...p, 
                dateOfSurgery: newDateOfSurgery,
                surgeries: updatedSurgeries,
                studyGroupIds: d.studyGroup && !p.studyGroupIds.includes(d.studyGroup) 
                  ? [...p.studyGroupIds, d.studyGroup] 
                  : p.studyGroupIds
              };
            }
            return p;
          }));
          setActiveView('dashboard');
        }} />;
      case 'research': return (
        <div className="space-y-4 max-w-5xl mx-auto">
          <div className="flex justify-between items-center">
            <h2 className="text-lg font-bold text-slate-900">Study Groups</h2>
            <button onClick={() => setShowAddStudyModal(true)} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[10px] font-bold uppercase tracking-widest flex items-center gap-2">
              <Plus size={14} /> Create New
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            {studyGroups.map(group => (
              <div key={group.id} onClick={() => setSelectedStudyGroup(group)} className="bg-white p-4 rounded-xl border border-slate-100 hover:border-teal-500 transition-all cursor-pointer group shadow-sm">
                <div className="flex justify-between items-start mb-2">
                  <div className="p-2 bg-slate-50 text-slate-400 rounded-lg group-hover:text-teal-600 transition-colors"><Library size={16} /></div>
                  <span className="text-[10px] font-bold text-teal-600 bg-teal-50 px-2 py-0.5 rounded-md">
                    {activePatients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled
                  </span>
                </div>
                <h3 className="font-bold text-slate-900 text-sm">{group.name}</h3>
                <p className="text-slate-400 text-[10px] mt-1 line-clamp-2">{group.description}</p>
              </div>
            ))}
          </div>
        </div>
      );
      case 'recycle': return <RecycleBin deletedPatients={deletedPatients} onRestore={(p) => setSecurityContext({ type: 'restore', patient: p })} onPermanentDelete={(p) => setSecurityContext({ type: 'hard-delete', patient: p })} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-teal-50 via-slate-50 to-slate-100">
        <div className="w-full max-w-sm animate-in fade-in zoom-in-95 duration-700">
          <div className="text-center mb-10">
            <div className="bg-white p-4 rounded-3xl shadow-xl inline-block mb-4 border border-slate-100">
               <OpusLogo size="md" />
            </div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.3em] text-[8px] mt-1">Surgical Asset Repository</p>
          </div>

          <div className="bg-white/80 backdrop-blur-xl border border-white rounded-[2.5rem] p-8 shadow-2xl space-y-6">
            {!isLinked ? (
              <div className="space-y-4">
                <p className="text-center text-xs font-medium text-slate-500 mb-6 px-4 leading-relaxed">Securely link your institutional ID to synchronize clinical data.</p>
                <button 
                  onClick={handleGoogleAuth}
                  className="w-full flex items-center justify-center gap-3 bg-slate-900 text-white py-3.5 rounded-2xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98] shadow-lg"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Continue with Google
                </button>
              </div>
            ) : (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 text-center">
                <div className="relative inline-block mb-2">
                  <img src={user?.avatar} className="w-20 h-20 rounded-3xl shadow-lg border-4 border-white mx-auto" alt="User" />
                  <div className="absolute -bottom-1 -right-1 bg-teal-500 text-white p-1 rounded-full border-2 border-white shadow-sm">
                    <CheckCircle2 size={14} />
                  </div>
                </div>
                <div className="space-y-1">
                  <h2 className="text-lg font-bold text-slate-900">{user?.name}</h2>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{user?.email}</p>
                </div>

                <button 
                  onClick={handleFinalLogin}
                  className="w-full bg-teal-600 text-white py-3.5 rounded-2xl font-bold text-sm shadow-xl hover:bg-teal-700 transition-all flex items-center justify-center gap-2 group"
                >
                  <Fingerprint size={20} className="group-hover:scale-110 transition-transform" />
                  Biometric Access
                </button>
              </div>
            )}
          </div>

          <p className="text-center mt-12 text-[7px] text-slate-300 font-black uppercase tracking-[0.5em]">HIPAA Compliant • Protected Access</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { setActiveView(v); setSelectedPatient(null); setSelectedStudyGroup(null); }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false); setUser(null);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen}
        deletedCount={deletedPatients.length}
      />

      <main className="flex-1 lg:ml-64 min-h-screen">
        <header className="px-6 py-2.5 bg-white border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="lg:hidden"><OpusLogo size="sm" /></div>
             <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{activeView}</span>
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2 bg-slate-50 px-2.5 py-1 rounded-full border border-slate-100">
               <img src={user?.avatar} className="w-5 h-5 rounded-full" alt="" />
               <span className="text-[10px] font-bold text-slate-600">{user?.name.split(' ').pop()}</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-400"><Menu size={18} /></button>
          </div>
        </header>

        <div className="px-6 py-6 max-w-6xl mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xs rounded-3xl shadow-2xl p-6 animate-in zoom-in-95 text-center space-y-4">
            <div className="mx-auto w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-teal-600">
              {isVerifying ? <div className="w-5 h-5 border-2 border-teal-600/30 border-t-teal-600 rounded-full animate-spin" /> : <Fingerprint size={24} className="animate-pulse" />}
            </div>
            <div className="space-y-1">
              <h2 className="text-xs font-bold text-slate-900 uppercase tracking-tight">Security Verification</h2>
              <p className="text-[9px] text-slate-400 uppercase font-bold tracking-widest">Confirm {securityContext.type}</p>
            </div>
            <input 
              type="password" 
              placeholder="System Passcode"
              className="w-full px-4 py-2 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold outline-none text-center"
              value={verificationInput}
              onChange={(e) => setVerificationInput(e.target.value)}
              autoFocus
            />
            <div className="flex gap-2">
              <button onClick={() => setSecurityContext(null)} className="flex-1 text-[9px] font-bold uppercase text-slate-400 py-2">Cancel</button>
              <button onClick={processSecurityAction} className="flex-1 bg-slate-900 text-white py-2 rounded-xl text-[9px] font-bold uppercase tracking-widest shadow-md">Confirm</button>
            </div>
          </div>
        </div>
      )}

      {/* Fully Editable Patient Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-[300] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 animate-in zoom-in-95 my-auto">
            <div className="flex justify-between items-center mb-4">
