                  <label className="text-[8px] font-bold text-slate-400 uppercase">Age (Months)</label>
                  <input type="number" value={patientToEdit.ageMonths || 0} onChange={e => setPatientToEdit({...patientToEdit, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Lead Surgeon</label>
                <input value={patientToEdit.primarySurgeon} onChange={e => setPatientToEdit({...patientToEdit, primarySurgeon: e.target.value})} className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px]" />
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Clinical Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 font-bold text-[11px] h-16 resize-none"
