import React from 'react';
import { LayoutDashboard, Upload, Library, LogOut, X, Trash2 } from 'lucide-react';

interface SidebarProps {
  activeView: string;
  setActiveView: (view: string) => void;
  onLogout: () => void;
  isOpen: boolean;
  setIsOpen: (open: boolean) => void;
  deletedCount: number;
}

const Sidebar: React.FC<SidebarProps> = ({ activeView, setActiveView, onLogout, isOpen, setIsOpen, deletedCount }) => {
  const navItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'upload', label: 'Intake Portal', icon: Upload },
    { id: 'research', label: 'Study Groups', icon: Library },
    { id: 'recycle', label: 'Archive Bin', icon: Trash2, count: deletedCount },
  ];

  return (
    <>
      {isOpen && <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-40 lg:hidden" onClick={() => setIsOpen(false)} />}
      <div className={`fixed left-0 top-0 h-screen w-64 bg-white border-r border-slate-100 flex flex-col z-50 transition-transform duration-300 ${isOpen ? 'translate-x-0' : '-translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 border-b border-slate-50 flex items-center justify-between">
          <span className="font-black text-xl tracking-tighter italic text-slate-900">OPUS</span>
          <button className="lg:hidden text-slate-400" onClick={() => setIsOpen(false)}><X size={18} /></button>
        </div>
        <nav className="flex-1 mt-6 px-6 space-y-2">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => { setActiveView(item.id); setIsOpen(false); }}
              className={`w-full flex items-center justify-between px-4 py-3 rounded-2xl transition-all text-xs font-bold ${activeView === item.id ? 'bg-teal-600 text-white shadow-lg shadow-teal-600/10' : 'text-slate-500 hover:bg-slate-50 hover:text-slate-900'}`}
            >
              <div className="flex items-center gap-3"><item.icon size={16} /><span>{item.label}</span></div>
              {item.count !== undefined && item.count > 0 && <span className={`text-[9px] px-1.5 py-0.5 rounded-full ${activeView === item.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'}`}>{item.count}</span>}
            </button>
          ))}
        </nav>
        <div className="p-6 border-t border-slate-50">
          <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-2.5 text-slate-400 hover:text-red-500 transition-colors text-[10px] font-bold uppercase tracking-widest">
            <LogOut size={14} /><span>Logout Terminal</span>
          </button>
        </div>
      </div>
    </>
  );
};

export default Sidebar;

export enum SurgicalStage {
  PRE_OP = 'Pre-operative',
  INTRA_OP = 'Intra-operative',
  POST_OP = 'Post-operative'
}

export enum MediaType {
  IMAGE = 'image',
  VIDEO = 'video',
  AUDIO = 'audio'
}

export enum StorageLocation {
  GOOGLE_DRIVE = 'Google Drive',
  LOCAL = 'Local Storage'
}

export interface StudyGroup {
  id: string;
  name: string;
  description: string;
  patientCount: number;
  driveFolderId?: string;
  lastSync?: string;
}

export interface SurgeryEvent {
  id: string;
  title: string;
  date: string;
  notes?: string;
  otNotes?: string; // New field for operative notes
}

export interface MediaEntry {
  id: string;
  uhid: string;
  surgeryId: string; // Links to a specific surgery event
  stage: SurgicalStage;
  type: MediaType;
  url: string;
  thumbnailUrl?: string;
  uploadedAt: string;
  notes?: string;
  tags: string[];
  storageLocation: StorageLocation;
}

export interface Patient {
  uhid: string;
  name: string;
  ageYears: number;
  ageMonths?: number;
  diagnosis: string;
  primarySurgeon: string;
  studyGroupIds: string[];
  createdAt: string;
  surgeries: SurgeryEvent[]; // Historical list of surgeries
  dateOfSurgery?: string; // Most recent surgery date
  deletedAt?: string; // For Recycle Bin (30-day retention)
}

export interface AuthUser {
  id: string;
  name: string;
  role: 'Surgeon' | 'Fellow' | 'Researcher';
  email: string;
}

import React, { useState } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, CloudUpload, FileText, Plus, Mic, Music } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio';
  thumbnailUrl?: string;
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState('');
  const [customTags, setCustomTags] = useState('');
  const [notes, setNotes] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const selectedPatient = patients.find(p => p.uhid === selectedPatientId);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' = 'image';
        if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';

        const url = URL.createObjectURL(file);
        return { url, file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;

    if (!surgeryId && !showNewSurgeryForm) {
      alert("Please select or register a surgery event.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        surgeryId: showNewSurgeryForm ? `surg_${Date.now()}` : surgeryId,
        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate, otNotes: otNotes } : null,
        otNotes: otNotes,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        tags: customTags.split(',').filter(t => t.trim()),
        notes,
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
    }, 1200);
  };

  if (showSuccess) {
    return (
      <div className="max-w-xs mx-auto py-12 text-center space-y-6 animate-in zoom-in-95">
        <div className="w-14 h-14 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center mx-auto shadow-sm border border-teal-100">
          <CheckCircle2 size={28} />
        </div>
        <div className="space-y-1">
          <h2 className="text-lg font-bold text-slate-900 tracking-tight italic">Assets Committed</h2>
          <p className="text-slate-400 font-bold text-[9px] uppercase tracking-widest">Entry Locked in Repository</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg text-[10px] uppercase tracking-widest transition-transform active:scale-95">
          New Intake Session
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-4 max-w-4xl mx-auto">
      <div>
        <h1 className="text-lg font-bold text-slate-900">Intake Portal</h1>
        <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest">Clinical Data Synchronizer</p>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-5">
        <div className="lg:col-span-5 space-y-3">
          <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm space-y-4">
            <h2 className="text-[9px] font-bold uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2">
              <Database size={12} /> Target Metadata
            </h2>
            <div>
              <label className="block text-[8px] font-bold text-slate-400 uppercase mb-1">Select Patient *</label>
              <select className="w-full px-3 py-2 bg-slate-50 border border-slate-50 rounded-lg font-bold text-slate-900 text-xs outline-none focus:border-teal-500" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Patient lookup...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-3 animate-in fade-in duration-300">
                <div className="flex justify-between items-center">
                  <label className="block text-[8px] font-bold text-slate-400 uppercase tracking-widest">Surgery Event</label>
                  <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[8px] font-bold text-teal-600 uppercase flex items-center gap-1">
                    {showNewSurgeryForm ? 'Existing' : <><Plus size={10} /> Register New</>}
                  </button>
                </div>

                {!showNewSurgeryForm ? (
                  <select className="w-full px-3 py-2 bg-slate-50 border border-slate-50 rounded-lg font-bold text-slate-900 text-xs outline-none focus:border-teal-500" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                    <option value="">Select Procedure...</option>
                    {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                  </select>
                ) : (
                  <div className="space-y-2 p-3 bg-teal-50/30 rounded-xl border border-teal-100">
                     <input required placeholder="Procedure Title" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100 outline-none" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                     <input required type="date" className="w-full px-2 py-1.5 text-xs font-bold rounded border border-teal-100" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                  </div>
                )}

                <div>
                  <label className="block text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-1">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-1">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-3 py-1.5 rounded-lg border text-[10px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700' : 'border-slate-50 text-slate-400 bg-slate-50'}`}>
                        {s}{stage === s && <CheckCircle2 size={10} />}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-[8px] font-bold text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1"><FileText size={10} /> Operative (OT) Notes</label>
                  <textarea value={otNotes} onChange={e => setOtNotes(e.target.value)} className="w-full px-3 py-2 bg-slate-50 border border-slate-100 rounded-lg h-20 font-bold text-xs outline-none focus:border-teal-500 resize-none" placeholder="Enter findings or steps..." />
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-7 space-y-3">
          <div className="bg-white p-5 rounded-2xl border border-slate-100 shadow-sm space-y-4">
            <div className="group relative p-6 border-2 border-dashed border-slate-100 rounded-xl bg-slate-50/50 hover:bg-white hover:border-teal-200 transition-all flex flex-col items-center justify-center text-center cursor-pointer min-h-[140px]">
              <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-2 bg-white rounded-lg shadow-sm text-slate-300 mb-2 group-hover:text-teal-500 transition-colors flex gap-2">
                <Camera size={20} />
                <Music size={20} />
              </div>
              <p className="text-xs font-bold text-slate-900">Upload Media</p>
              <p className="text-slate-400 text-[8px] font-bold uppercase tracking-widest mt-0.5">JPG / PNG / MP4 / MP3 Master Quality</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-5 sm:grid-cols-6 gap-2">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-lg overflow-hidden border border-slate-100 bg-slate-50 flex items-center justify-center">
                    {fileData.type === 'image' && <img src={fileData.url} className="w-full h-full object-cover" />}
                    {fileData.type === 'video' && <div className="text-slate-400"><PlayCircle size={24} /></div>}
                    {fileData.type === 'audio' && <div className="text-slate-400"><Music size={24} /></div>}
                    <button type="button" onClick={() => removeFile(i)} className="absolute top-1 right-1 p-1 bg-black/50 text-white rounded-md opacity-0 group-hover:opacity-100 transition-opacity">
                      <Trash2 size={8} />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-teal-600 text-white font-bold py-3 rounded-xl shadow-lg flex items-center justify-center gap-2 text-[10px] uppercase tracking-widest mt-2 active:scale-95 transition-all disabled:opacity-50"
            >
              {isUploading ? <div className="w-3 h-3 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={14} />}
              Commit Assets
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

import React, { useState } from 'react';
import { ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, FileText, CheckCircle2, Plus, Music, Volume2 } from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onEditPatient: (patient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, onBack, onAddMedia, onUpdatePatient, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('');

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = [...MOCK_MEDIA].filter(m => m.uhid === patient.uhid && m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const handleDownloadInit = (media: MediaEntry) => {
    setDownloadModalMedia(media);
    if (media.type === MediaType.VIDEO) setDownloadFormat('MP4');
    else if (media.type === MediaType.AUDIO) setDownloadFormat('MP3');
    else setDownloadFormat('JPG');
  };

  const handleFinalDownload = () => {
    if (!downloadModalMedia) return;
    const a = document.createElement('a');
    a.href = downloadModalMedia.url;
    a.download = `HQ_${patient.uhid}_${downloadModalMedia.stage}_${Date.now()}.${downloadFormat.toLowerCase()}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setDownloadModalMedia(null);
  };

  return (
    <div className="space-y-4 max-w-5xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="text-[9px] font-bold text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors flex items-center gap-1">
          <ArrowLeft size={10} /> Registry Dashboard
        </button>
        <button onClick={onAddMedia} className="bg-teal-600 text-white px-3 py-1.5 rounded-lg text-[9px] font-bold uppercase tracking-widest shadow-sm hover:bg-teal-700 transition-all active:scale-95 flex items-center gap-1.5">
          <Plus size={12} /> Intake Session
        </button>
      </div>

      <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div className="flex gap-4 items-center">
          <div className="w-10 h-10 bg-teal-600 text-white rounded-xl flex items-center justify-center font-bold text-sm shadow-md">{patient.name.charAt(0)}</div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-sm font-bold text-slate-900">{patient.name}</h1>
              <span className="text-[8px] font-mono font-bold text-slate-300 bg-slate-50 px-1 rounded border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[9px] font-bold uppercase tracking-widest leading-none mt-1">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} &bull; {patient.primarySurgeon}
            </p>
          </div>
        </div>
        <div className="flex-1 max-w-md bg-slate-50 px-3 py-1.5 rounded-xl border border-slate-100 flex items-center gap-3">
          <HardDrive size={12} className="text-teal-600 shrink-0" />
          <p className="text-[10px] text-slate-600 italic line-clamp-1">{patient.diagnosis}</p>
        </div>
        <div className="flex gap-1">
          <button onClick={() => onEditPatient(patient)} className="p-1.5 bg-slate-50 text-slate-400 rounded-lg border border-slate-100 hover:text-teal-600 hover:bg-white transition-all shadow-sm"><Edit size={12} /></button>
          <button onClick={() => onDeletePatient(patient)} className="p-1.5 bg-slate-50 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg border border-slate-100 transition-all shadow-sm"><Trash2 size={12} /></button>
        </div>
      </div>

      <div className="flex gap-1 overflow-x-auto pb-1 no-scrollbar scroll-smooth">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-3 py-1.5 rounded-xl border text-[9px] font-bold uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-md scale-105 z-10' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-200'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
        {/* Left Column: Media */}
        <div className="lg:col-span-8 bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden flex flex-col h-fit">
          <div className="flex bg-slate-50 p-1 gap-1">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-1.5 text-[8px] font-bold uppercase transition-all rounded-lg ${activeStage === stage ? 'text-teal-600 bg-white shadow-sm' : 'text-slate-400'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-3">
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative aspect-square rounded-xl overflow-hidden border border-slate-50 bg-slate-100 shadow-sm flex items-center justify-center">
                  {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                    <video src={m.url} autoPlay controls className="w-full h-full object-cover" />
                  ) : m.type === MediaType.AUDIO ? (
                    <div className="flex flex-col items-center gap-2 p-4 w-full">
                       <div className="p-3 bg-teal-50 text-teal-600 rounded-full shadow-inner"><Volume2 size={24} /></div>
                       {playingAudioId === m.id && <audio src={m.url} autoPlay controls className="w-full h-8 mt-2" />}
                       <button onClick={() => setPlayingAudioId(m.id === playingAudioId ? null : m.id)} className="text-[8px] font-bold uppercase tracking-widest text-slate-400 mt-1">
                          {playingAudioId === m.id ? 'Stop' : 'Play Audio'}
                       </button>
                    </div>
                  ) : (
                    <>
                      <img src={m.thumbnailUrl || m.url} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                      {m.type === MediaType.VIDEO && (
                        <div className="absolute inset-0 flex items-center justify-center cursor-pointer" onClick={() => setPlayingVideoId(m.id)}>
                          <div className="bg-black/20 backdrop-blur-sm p-2.5 rounded-full text-white"><PlayCircle size={20} /></div>
                        </div>
                      )}
                    </>
                  )}
                  {/* Common Overlay for Download */}
                  <div className="absolute top-1.5 right-1.5 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                     <button onClick={() => handleDownloadInit(m)} className="p-1 bg-white/40 backdrop-blur-md rounded-lg text-white hover:bg-teal-600 transition-colors" title="HQ Download"><Download size={10} /></button>
                  </div>
                </div>
              ))}
              {filteredMedia.length === 0 && <div className="col-span-full py-10 text-center text-slate-200 font-bold uppercase tracking-widest text-[9px] italic">Registry segment empty</div>}
            </div>
          </div>
        </div>

        {/* Right Column: OT Notes */}
        <div className="lg:col-span-4 space-y-3">
          <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm h-full">
            <h3 className="text-[9px] font-bold uppercase tracking-widest text-slate-400 mb-3 flex items-center gap-1.5">
              <FileText size={12} className="text-teal-600" /> Operative (OT) Notes
            </h3>
            <div className="bg-slate-50 p-3 rounded-xl border border-slate-100 min-h-[120px]">
               {currentSurgery?.otNotes ? (
                 <p className="text-xs text-slate-600 leading-relaxed font-medium whitespace-pre-wrap">{currentSurgery.otNotes}</p>
               ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-300 py-6">
                    <p className="text-[8px] font-bold uppercase">No OT notes uploaded</p>
                 </div>
               )}
            </div>
            {currentSurgery && (
              <p className="text-[7px] font-bold text-slate-300 uppercase mt-2 text-right tracking-tighter">Verified Procedure Date: {currentSurgery.date}</p>
            )}
          </div>
        </div>
      </div>

      {/* HQ Download Format Selection Modal */}
      {downloadModalMedia && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[400] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xs rounded-3xl shadow-2xl p-6 animate-in zoom-in-95 text-center space-y-5">
            <div className="mx-auto w-12 h-12 bg-teal-50 text-teal-600 rounded-2xl flex items-center justify-center">
              <Download size={24} />
            </div>
            <div className="space-y-1">
              <h2 className="text-xs font-bold text-slate-900 uppercase tracking-widest">HQ Asset Export</h2>
              <p className="text-[9px] text-slate-400 font-bold uppercase">Select preferred master format</p>
            </div>
            <div className="grid grid-cols-2 gap-2">
              {downloadModalMedia.type === MediaType.IMAGE ? (
                ['JPG', 'PNG', 'WEBP'].map(f => (
                  <button key={f} onClick={() => setDownloadFormat(f)} className={`py-2 rounded-xl text-[10px] font-bold transition-all ${downloadFormat === f ? 'bg-teal-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                ))
              ) : downloadModalMedia.type === MediaType.VIDEO ? (
                ['MP4', 'MOV', 'AVI'].map(f => (
                  <button key={f} onClick={() => setDownloadFormat(f)} className={`py-2 rounded-xl text-[10px] font-bold transition-all ${downloadFormat === f ? 'bg-teal-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                ))
              ) : (
                ['MP3', 'WAV', 'AAC', 'M4A'].map(f => (
                  <button key={f} onClick={() => setDownloadFormat(f)} className={`py-2 rounded-xl text-[10px] font-bold transition-all ${downloadFormat === f ? 'bg-teal-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                ))
              )}
            </div>
            <div className="flex gap-2 pt-2 border-t border-slate-50">
              <button onClick={() => setDownloadModalMedia(null)} className="flex-1 py-2 text-[9px] font-bold uppercase text-slate-400">Cancel</button>
              <button onClick={handleFinalDownload} className="flex-1 bg-slate-900 text-white py-2 rounded-xl text-[9px] font-bold uppercase tracking-widest shadow-md">Export</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PatientDetails;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import RecycleBin from './views/RecycleBin';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup, SurgeryEvent } from './types';
import { 
  Menu, CheckCircle2, Fingerprint, X, KeyRound
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [user, setUser] = useState<{name: string, email: string, avatar: string} | null>(null);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const handleGoogleAuth = () => {
    setUser({
      name: 'Dr. Alexander Smith',
      email: 'a.smith@surgical.org',
      avatar: 'https://ui-avatars.com/api/?name=Alexander+Smith&background=0d9488&color=fff'
    });
    setIsLinked(true);
  };

  const handleBiometricLogin = () => {
    // In a real mobile environment, this would call window.PublicKeyCredential or similar
    setIsLoggedIn(true);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) setSelectedPatient(updated);
    setPatientToEdit(null);
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);
    setTimeout(() => {
      const { type, patient } = securityContext;
      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p));
        setSelectedPatient(null);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p));
      }
      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 800);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          onEditPatient={setPatientToEdit}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    switch (activeView) {
      case 'dashboard': 
        return <Dashboard patients={activePatients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': 
        return <UploadMedia patients={activePatients} studyGroups={studyGroups} onUpload={d => { 
          setPatients(prev => prev.map(p => {
            if (p.uhid === d.uhid) {
              const updatedSurgeries = [...p.surgeries];
              let newDateOfSurgery = p.dateOfSurgery;

              if (d.newSurgery) {
                updatedSurgeries.push({
                  id: d.surgeryId,
                  title: d.newSurgery.title,
                  date: d.newSurgery.date,
                  otNotes: d.newSurgery.otNotes
                });
                newDateOfSurgery = d.newSurgery.date;
              } else if (d.surgeryId) {
                const existingIndex = updatedSurgeries.findIndex(s => s.id === d.surgeryId);
                if (existingIndex > -1) {
                  updatedSurgeries[existingIndex] = {
                    ...updatedSurgeries[existingIndex],
                    otNotes: d.otNotes || updatedSurgeries[existingIndex].otNotes
                  };
                  newDateOfSurgery = updatedSurgeries[existingIndex].date;
                }
              }

              return { 
                ...p, 
                dateOfSurgery: newDateOfSurgery,
                surgeries: updatedSurgeries,
                studyGroupIds: d.studyGroup && !p.studyGroupIds.includes(d.studyGroup) 
                  ? [...p.studyGroupIds, d.studyGroup] 
                  : p.studyGroupIds
              };
            }
            return p;
          }));
          setActiveView('dashboard');
        }} />;
      case 'research': 
        return (
          <div className="space-y-6 max-w-7xl mx-auto">
            <h2 className="text-2xl font-bold text-slate-900">Study Units</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {studyGroups.map(group => (
                <div key={group.id} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-lg transition-all cursor-pointer">
                  <h3 className="font-bold text-slate-900 text-lg mb-2">{group.name}</h3>
                  <p className="text-slate-400 text-xs mb-4">{group.description}</p>
                  <div className="flex justify-between items-center text-[10px] font-bold text-teal-600 bg-teal-50 px-3 py-1 rounded-full">
                    <span>{activePatients.filter(p => p.studyGroupIds.includes(group.id)).length} Enrolled</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'recycle': 
        return <RecycleBin deletedPatients={deletedPatients} onRestore={(p) => setSecurityContext({ type: 'restore', patient: p })} onPermanentDelete={(p) => setSecurityContext({ type: 'hard-delete', patient: p })} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-teal-50 via-slate-50 to-slate-100">
        <div className="w-full max-w-sm">
          <div className="text-center mb-10">
            <div className="bg-white p-4 rounded-3xl shadow-xl inline-block mb-4 border border-slate-100">
               <OpusLogo size="md" />
            </div>
            <h1 className="text-3xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.3em] text-[8px] mt-1">Surgical Asset Repository</p>
          </div>

          <div className="bg-white/80 backdrop-blur-xl border border-white rounded-[2.5rem] p-8 shadow-2xl space-y-6">
            {!isLinked ? (
              <div className="space-y-4">
                <p className="text-center text-xs font-medium text-slate-500 mb-6 px-4">Link your clinical credentials to begin.</p>
                <button 
                  onClick={handleGoogleAuth}
                  className="w-full flex items-center justify-center gap-3 bg-slate-900 text-white py-4 rounded-2xl font-bold text-sm hover:bg-slate-800 transition-all active:scale-[0.98] shadow-lg"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-4 h-4" alt="" />
                  Continue with Google
                </button>
              </div>
            ) : (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 text-center">
                <div className="relative inline-block">
                  <img src={user?.avatar} className="w-20 h-20 rounded-3xl shadow-md border-4 border-white mx-auto mb-3" alt="User" />
                  <div className="absolute -bottom-1 -right-1 bg-teal-500 text-white p-1 rounded-full border-2 border-white">
                    <CheckCircle2 size={14} />
                  </div>
                </div>
                <h2 className="text-lg font-bold text-slate-900 leading-none">{user?.name}</h2>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{user?.email}</p>

                <button 
                  onClick={handleBiometricLogin}
                  className="w-full bg-teal-600 text-white py-4 rounded-2xl font-bold text-sm shadow-xl hover:bg-teal-700 transition-all flex items-center justify-center gap-2 group"
                >
                  <Fingerprint size={22} className="group-hover:scale-110 transition-transform" />
                  Unlock with Biometrics
                </button>
              </div>
            )}
          </div>
          <p className="text-center mt-12 text-[7px] text-slate-300 font-black uppercase tracking-[0.5em]">HIPAA COMPLIANT • END-TO-END ENCRYPTED</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { setActiveView(v); setSelectedPatient(null); }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false); setUser(null);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen}
        deletedCount={deletedPatients.length}
      />

      <main className="flex-1 lg:ml-64 min-h-screen transition-all">
        <header className="px-8 py-3 bg-white/80 border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md flex items-center justify-between">
          <div className="flex items-center gap-3">
             <div className="lg:hidden"><OpusLogo size="sm" /></div>
             <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">{activeView}</span>
          </div>
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 bg-slate-100/50 px-3 py-1.5 rounded-full border border-slate-100">
               <img src={user?.avatar} className="w-5 h-5 rounded-full" alt="" />
               <span className="text-[10px] font-bold text-slate-700">{user?.name.split(' ').pop()}</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-1.5 text-slate-400"><Menu size={18} /></button>
          </div>
        </header>

        <div className="px-8 py-8 max-w-7xl mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Expanded Clinical Data Edit Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[2rem] shadow-2xl p-8 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xs font-bold uppercase tracking-[0.2em] text-slate-900">Clinical Record Edit</h2>
              <button onClick={() => setPatientToEdit(null)} className="text-slate-400 hover:text-slate-900 transition-colors"><X size={20} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">UHID</label>
                  <input value={patientToEdit.uhid} onChange={e => setPatientToEdit({...patientToEdit, uhid: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs focus:ring-2 focus:ring-teal-500/20 transition-all outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">Lead Surgeon</label>
                  <input value={patientToEdit.primarySurgeon} onChange={e => setPatientToEdit({...patientToEdit, primarySurgeon: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs focus:ring-2 focus:ring-teal-500/20 transition-all outline-none" />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Patient Name</label>
                <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs focus:ring-2 focus:ring-teal-500/20 transition-all outline-none" />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">Age (Y)</label>
                  <input type="number" value={patientToEdit.ageYears} onChange={e => setPatientToEdit({...patientToEdit, ageYears: parseInt(e.target.value) || 0})} className="w-full px-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs focus:ring-2 focus:ring-teal-500/20 transition-all outline-none" />
                </div>
                <div className="space-y-1">
                  <label className="text-[8px] font-bold text-slate-400 uppercase">Age (M)</label>
                  <input type="number" value={patientToEdit.ageMonths || 0} onChange={e => setPatientToEdit({...patientToEdit, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs focus:ring-2 focus:ring-teal-500/20 transition-all outline-none" />
                </div>
              </div>
              <div className="space-y-1">
                <label className="text-[8px] font-bold text-slate-400 uppercase">Clinical Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-4 py-2.5 bg-slate-50 rounded-xl border border-slate-100 font-bold text-xs h-24 resize-none focus:ring-2 focus:ring-teal-500/20 transition-all outline-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-4 rounded-2xl font-bold text-[10px] uppercase tracking-[0.2em] shadow-lg active:scale-95 transition-all">Commit Changes to Vault</button>
            </form>
          </div>
        </div>
      )}

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-xs rounded-3xl shadow-2xl p-6 animate-in zoom-in-95 text-center space-y-4">
            <div className="mx-auto w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-teal-600">
              {isVerifying ? <div className="w-5 h-5 border-2 border-teal-600/30 border-t-teal-600 rounded-full animate-spin" /> : <KeyRound size={24} className="animate-pulse" />}
            </div>
            <div className="space-y-1">
              <h2 className="text-xs font-bold text-slate-900 uppercase tracking-tight">Access Required</h2>
              <p className="text-[9px] text-slate-400 uppercase font-bold tracking-widest">Verify identity for {securityContext.type}</p>
            </div>
            <input 
              type="password" 
              placeholder="Vault Key"
              className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold outline-none text-center"
              value={verificationInput}
              onChange={(e) => setVerificationInput(e.target.value)}
              autoFocus
            />
            <div className="flex gap-2">
              <button onClick={() => setSecurityContext(null)} className="flex-1 text-[9px] font-bold uppercase text-slate-400 py-2">Cancel</button>
              <button onClick={processSecurityAction} className="flex-1 bg-slate-900 text-white py-2.5 rounded-xl text-[9px] font-bold uppercase tracking-widest shadow-md">Confirm</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, FileText, Plus, Music, Volume2 } from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onEditPatient: (patient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, onBack, onAddMedia, onUpdatePatient, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('');

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = [...MOCK_MEDIA].filter(m => m.uhid === patient.uhid && m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const handleDownloadInit = (media: MediaEntry) => {
    setDownloadModalMedia(media);
    if (media.type === MediaType.VIDEO) setDownloadFormat('MP4');
    else if (media.type === MediaType.AUDIO) setDownloadFormat('MP3');
    else setDownloadFormat('JPG');
  };

  const handleFinalDownload = () => {
    if (!downloadModalMedia) return;
    const a = document.createElement('a');
    a.href = downloadModalMedia.url;
    a.download = `HQ_${patient.uhid}_${downloadModalMedia.stage}_${Date.now()}.${downloadFormat.toLowerCase()}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setDownloadModalMedia(null);
  };

  return (
    <div className="space-y-6 max-w-7xl mx-auto animate-in fade-in duration-500">
      <div className="flex justify-between items-center">
        <button onClick={onBack} className="text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-slate-900 transition-colors flex items-center gap-2">
          <ArrowLeft size={14} /> Back to Registry
        </button>
        <button onClick={onAddMedia} className="bg-teal-600 text-white px-5 py-2 rounded-2xl text-[10px] font-bold uppercase tracking-widest shadow-xl hover:bg-teal-700 transition-all active:scale-95 flex items-center gap-2">
          <Plus size={16} /> New Intake Session
        </button>
      </div>

      <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
        <div className="flex gap-5 items-center">
          <div className="w-14 h-14 bg-teal-600 text-white rounded-[1.5rem] flex items-center justify-center font-bold text-xl shadow-lg">{patient.name.charAt(0)}</div>
          <div>
            <div className="flex items-center gap-3">
              <h1 className="text-xl font-bold text-slate-900 tracking-tight">{patient.name}</h1>
              <span className="text-[10px] font-mono font-bold text-slate-400 bg-slate-100 px-2 py-0.5 rounded-lg border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.2em] mt-1.5">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} • {patient.primarySurgeon}
            </p>
          </div>
        </div>
        <div className="flex-1 max-w-xl bg-slate-50/50 px-5 py-3 rounded-2xl border border-slate-100 flex items-center gap-4">
          <HardDrive size={18} className="text-teal-600 shrink-0" />
          <p className="text-xs text-slate-600 italic leading-relaxed">{patient.diagnosis}</p>
        </div>
        <div className="flex gap-2">
          <button onClick={() => onEditPatient(patient)} className="p-3 bg-white text-slate-400 rounded-2xl border border-slate-100 hover:text-teal-600 hover:border-teal-100 transition-all shadow-sm"><Edit size={18} /></button>
          <button onClick={() => onDeletePatient(patient)} className="p-3 bg-white text-slate-400 hover:text-red-500 hover:border-red-100 rounded-2xl border border-slate-100 transition-all shadow-sm"><Trash2 size={18} /></button>
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar scroll-smooth">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-6 py-3 rounded-2xl border text-[10px] font-bold uppercase tracking-widest transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-xl scale-105 z-10' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* Left Column: Larger Media Grid */}
        <div className="lg:col-span-8 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden flex flex-col h-fit">
          <div className="flex bg-slate-50 p-2 gap-2">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-3 text-[10px] font-bold uppercase transition-all rounded-xl ${activeStage === stage ? 'text-teal-600 bg-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-6">
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-5">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative aspect-video sm:aspect-square rounded-3xl overflow-hidden border border-slate-100 bg-slate-100 shadow-sm flex items-center justify-center">
                  {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                    <video src={m.url} autoPlay controls className="w-full h-full object-cover" />
                  ) : m.type === MediaType.AUDIO ? (
                    <div className="flex flex-col items-center gap-3 p-6 w-full text-center">
                       <div className="p-4 bg-teal-50 text-teal-600 rounded-full shadow-inner"><Volume2 size={32} /></div>
                       <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{m.notes || 'Audio Clip'}</p>
                       {playingAudioId === m.id && <audio src={m.url} autoPlay controls className="w-full h-8 mt-2" />}
