              <h3 className="text-xs font-bold uppercase tracking-[0.2em] text-slate-900">Operative (OT) Notes</h3>
            </div>

            <div className="bg-slate-50/80 p-6 rounded-3xl border border-slate-100 flex-1 min-h-[250px] relative overflow-hidden group">
               <div className="absolute top-0 right-0 p-4 opacity-10 group-hover:opacity-30 transition-opacity"><FileText size={80} /></div>
               {currentSurgery?.otNotes ? (
                 <p className="text-sm text-slate-600 leading-relaxed font-medium whitespace-pre-wrap relative z-10">{currentSurgery.otNotes}</p>
               ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-300 py-10">
