import React, { useState } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, CloudUpload, FileText, Plus, Music } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState('');
  const [notes, setNotes] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' = 'image';
        if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;

    if (!surgeryId && !showNewSurgeryForm) {
      alert("Registration requires a specific procedure event.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        surgeryId: showNewSurgeryForm ? `surg_${Date.now()}` : surgeryId,
        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate, otNotes: otNotes } : null,
        otNotes: otNotes,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        notes,
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-md mx-auto py-20 text-center space-y-8 animate-in zoom-in-95">
        <div className="w-20 h-20 bg-teal-50 text-teal-600 rounded-[2rem] flex items-center justify-center mx-auto shadow-xl border border-teal-100">
          <CheckCircle2 size={40} />
        </div>
        <div className="space-y-2">
          <h2 className="text-2xl font-black text-slate-900 tracking-tight italic">Assest Committed</h2>
          <p className="text-slate-400 font-bold text-[10px] uppercase tracking-[0.3em]">Entry Secured in Longitudinal Repository</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-bold py-4 rounded-2xl shadow-xl text-xs uppercase tracking-[0.2em] transition-transform active:scale-95 hover:bg-teal-700">
          Initialize New Session
        </button>
      </div>
    );
  }

  const selectedPatient = patients.find(p => p.uhid === selectedPatientId);

  return (
    <div className="space-y-8 max-w-6xl mx-auto">
      <div className="flex justify-between items-end">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight">Intake Portal</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em]">High-Fidelity Clinical Data Synchronization</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-5 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
            <h2 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-300 flex items-center gap-2">
              <Database size={14} /> Clinical Metadata
            </h2>

            <div className="space-y-1.5">
              <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest">Select Patient *</label>
              <select className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 text-xs focus:ring-2 focus:ring-teal-500/20 outline-none transition-all" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Search patient database...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-6 animate-in fade-in duration-500">
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest">Procedure Event</label>
                    <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[9px] font-bold text-teal-600 uppercase flex items-center gap-1.5 hover:underline">
                      {showNewSurgeryForm ? 'Use Existing' : <><Plus size={12} /> New Registry</>}
                    </button>
                  </div>
                  {!showNewSurgeryForm ? (
                    <select className="w-full px-4 py-3 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-slate-900 text-xs outline-none focus:ring-2 focus:ring-teal-500/20" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                      <option value="">Select Procedure...</option>
                      {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                    </select>
                  ) : (
                    <div className="space-y-3 p-5 bg-teal-50/30 rounded-3xl border border-teal-100/50">
                       <input required placeholder="Procedure Title (e.g. Nerve Graft)" className="w-full px-4 py-2.5 text-xs font-bold rounded-xl border border-teal-100 outline-none focus:bg-white" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                       <input required type="date" className="w-full px-4 py-2.5 text-xs font-bold rounded-xl border border-teal-100 outline-none focus:bg-white" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                    </div>
                  )}
                </div>

                <div className="space-y-2">
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-2">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-4 py-3 rounded-2xl border text-[10px] font-bold text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700 shadow-sm' : 'border-slate-100 text-slate-400 bg-slate-50/50 hover:bg-slate-100'}`}>
                        {s}{stage === s && <CheckCircle2 size={14} />}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-2">
                  <label className="block text-[9px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5"><FileText size={12} className="text-teal-600" /> Operative (OT) Notes</label>
                  <textarea value={otNotes} onChange={e => setOtNotes(e.target.value)} className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-3xl h-32 font-bold text-xs outline-none focus:ring-2 focus:ring-teal-500/20 resize-none transition-all" placeholder="Enter surgical findings, anatomical landmarks, or technique details..." />
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-7 space-y-6">
          <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6 h-full flex flex-col">
            <h2 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-300">HQ Asset Capture</h2>

            <div className="group relative p-10 border-2 border-dashed border-slate-200 rounded-[2rem] bg-slate-50/50 hover:bg-white hover:border-teal-400 transition-all flex flex-col items-center justify-center text-center cursor-pointer flex-1 min-h-[300px]">
              <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-5 bg-white rounded-3xl shadow-xl text-slate-300 mb-4 group-hover:text-teal-600 group-hover:scale-110 transition-all flex gap-3">
                <Camera size={32} />
                <Music size={32} />
              </div>
              <p className="text-lg font-bold text-slate-900">Drag & Drop Clinical Assets</p>
              <p className="text-slate-400 text-[10px] font-bold uppercase tracking-[0.3em] mt-2">All Video / Audio / Image Formats Accepted (Master Quality)</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-4 sm:grid-cols-6 gap-3">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-2xl overflow-hidden border border-slate-100 bg-slate-50 flex items-center justify-center shadow-sm">
                    {fileData.type === 'image' && <img src={fileData.url} className="w-full h-full object-cover" />}
                    {fileData.type === 'video' && <div className="text-slate-400 flex flex-col items-center gap-1"><PlayCircle size={24} /><span className="text-[7px] font-bold uppercase tracking-tighter">Video</span></div>}
                    {fileData.type === 'audio' && <div className="text-slate-400 flex flex-col items-center gap-1"><Music size={24} /><span className="text-[7px] font-bold uppercase tracking-tighter">Audio</span></div>}
                    <button type="button" onClick={() => removeFile(i)} className="absolute top-1.5 right-1.5 p-1.5 bg-black/60 text-white rounded-lg opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500">
                      <Trash2 size={12} />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-slate-900 text-white font-bold py-5 rounded-3xl shadow-2xl flex items-center justify-center gap-3 text-[11px] uppercase tracking-[0.3em] mt-auto active:scale-95 transition-all disabled:opacity-30 disabled:cursor-not-allowed group"
            >
              {isUploading ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" /> : <CloudUpload size={20} className="group-hover:translate-y-[-2px] transition-transform" />}
              Commit Master Assets
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

