              </span>
              <div className="flex gap-1">
                 {p.studyGroupIds.map(id => (
                   <span key={id} className="text-[8px] font-black text-teal-600 uppercase bg-teal-50 px-2 py-0.5 rounded-lg border border-teal-100">{id}</span>
