              </div>
              <input required placeholder="Full Patient Name" className="w-full px-4 py-3 bg-slate-50 rounded-2xl text-xs font-bold border border-slate-100 outline-none focus:ring-2 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              <div className="grid grid-cols-2 gap-3">
                <input type="number" placeholder="Age (Years)" className="w-full px-4 py-3 bg-slate-50 rounded-2xl text-xs font-bold border border-slate-100 outline-none focus:ring-2 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
                <input type="date" className="w-full px-4 py-3 bg-slate-50 rounded-2xl text-xs font-bold border border-slate-100 outline-none focus:ring-2 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} />
              </div>
              <textarea required placeholder="Preliminary Diagnosis" className="w-full px-4 py-3 bg-slate-50 rounded-2xl text-xs font-bold border border-slate-100 h-24 resize-none outline-none focus:ring-2 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-4 rounded-3xl text-[10px] uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Register with Vault</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './views/Dashboard';
import PatientDetails from './views/PatientDetails';
import UploadMedia from './views/UploadMedia';
import RecycleBin from './views/RecycleBin';
import { OpusLogo } from './components/Logo';
import { Patient, StudyGroup, SurgeryEvent } from './types';
import { 
  Menu, CheckCircle2, Fingerprint, X, KeyRound
} from 'lucide-react';
import { MOCK_PATIENTS, MOCK_MEDIA, MOCK_STUDY_GROUPS } from './constants';

const App: React.FC = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isLinked, setIsLinked] = useState(false);
  const [user, setUser] = useState<{name: string, email: string, avatar: string} | null>(null);
  const [activeView, setActiveView] = useState('dashboard');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [patients, setPatients] = useState<Patient[]>(MOCK_PATIENTS);
  const [studyGroups] = useState<StudyGroup[]>(MOCK_STUDY_GROUPS);
  const [selectedPatient, setSelectedPatient] = useState<Patient | null>(null);
  const [patientToEdit, setPatientToEdit] = useState<Patient | null>(null);

  const [securityContext, setSecurityContext] = useState<{ type: 'soft-delete' | 'hard-delete' | 'restore', patient: Patient } | null>(null);
  const [verificationInput, setVerificationInput] = useState('');
  const [isVerifying, setIsVerifying] = useState(false);

  const activePatients = patients.filter(p => !p.deletedAt);
  const deletedPatients = patients.filter(p => !!p.deletedAt);

  const handleGoogleAuth = () => {
    setUser({
      name: 'Dr. Alexander Smith',
      email: 'a.smith@surgical.org',
      avatar: 'https://ui-avatars.com/api/?name=Alexander+Smith&background=0d9488&color=fff'
    });
    setIsLinked(true);
  };

  const handleBiometricLogin = () => {
    setIsLoggedIn(true);
  };

  const handleAddPatient = (newPatient: Patient) => {
    setPatients(prev => [newPatient, ...prev]);
    setSelectedPatient(newPatient);
  };

  const handleUpdatePatient = (updated: Patient) => {
    setPatients(prev => prev.map(p => p.uhid === updated.uhid ? updated : p));
    if (selectedPatient?.uhid === updated.uhid) setSelectedPatient(updated);
    setPatientToEdit(null);
  };

  const processSecurityAction = () => {
    if (!securityContext) return;
    setIsVerifying(true);
    setTimeout(() => {
      const { type, patient } = securityContext;
      if (type === 'soft-delete') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: new Date().toISOString() } : p));
        setSelectedPatient(null);
      } else if (type === 'hard-delete') {
        setPatients(prev => prev.filter(p => p.uhid !== patient.uhid));
      } else if (type === 'restore') {
        setPatients(prev => prev.map(p => p.uhid === patient.uhid ? { ...p, deletedAt: undefined } : p));
      }
      setIsVerifying(false);
      setSecurityContext(null);
      setVerificationInput('');
    }, 800);
  };

  const renderView = () => {
    if (selectedPatient) {
      return (
        <PatientDetails 
          patient={selectedPatient} 
          onBack={() => setSelectedPatient(null)} 
          onAddMedia={() => { setActiveView('upload'); setSelectedPatient(null); }}
          onUpdatePatient={handleUpdatePatient}
          onEditPatient={setPatientToEdit}
          onDeletePatient={(p) => setSecurityContext({ type: 'soft-delete', patient: p })}
          studyGroups={studyGroups}
        />
      );
    }

    switch (activeView) {
      case 'dashboard': 
        return <Dashboard patients={activePatients} studyGroups={studyGroups} onAddPatient={handleAddPatient} onSelectPatient={setSelectedPatient} />;
      case 'upload': 
        return <UploadMedia patients={activePatients} studyGroups={studyGroups} onUpload={d => { 
          setPatients(prev => prev.map(p => {
            if (p.uhid === d.uhid) {
              const updatedSurgeries = [...p.surgeries];
              let newDateOfSurgery = p.dateOfSurgery;

              if (d.newSurgery) {
                updatedSurgeries.push({
                  id: d.surgeryId,
                  title: d.newSurgery.title,
                  date: d.newSurgery.date,
                  otNotes: d.newSurgery.otNotes
                });
                newDateOfSurgery = d.newSurgery.date;
              } else if (d.surgeryId) {
                const existingIndex = updatedSurgeries.findIndex(s => s.id === d.surgeryId);
                if (existingIndex > -1) {
                  updatedSurgeries[existingIndex] = {
                    ...updatedSurgeries[existingIndex],
                    otNotes: d.otNotes || updatedSurgeries[existingIndex].otNotes
                  };
                  newDateOfSurgery = updatedSurgeries[existingIndex].date;
                }
              }

              return { 
                ...p, 
                dateOfSurgery: newDateOfSurgery,
                surgeries: updatedSurgeries,
                studyGroupIds: d.studyGroup && !p.studyGroupIds.includes(d.studyGroup) 
                  ? [...p.studyGroupIds, d.studyGroup] 
                  : p.studyGroupIds
              };
            }
            return p;
          }));
          setActiveView('dashboard');
        }} />;
      case 'research': 
        return (
          <div className="space-y-8 max-w-7xl mx-auto">
            <h2 className="text-3xl font-black text-slate-900 tracking-tight">Study Units</h2>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
              {studyGroups.map(group => (
                <div key={group.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:-translate-y-1 transition-all cursor-pointer">
                  <h3 className="font-bold text-slate-900 text-xl mb-3">{group.name}</h3>
                  <p className="text-slate-500 text-sm mb-6 leading-relaxed">{group.description}</p>
                  <div className="inline-flex items-center text-[11px] font-black uppercase tracking-widest text-teal-600 bg-teal-50 px-4 py-1.5 rounded-full border border-teal-100">
                    <span>{activePatients.filter(p => p.studyGroupIds.includes(group.id)).length} Patients Enrolled</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        );
      case 'recycle': 
        return <RecycleBin deletedPatients={deletedPatients} onRestore={(p) => setSecurityContext({ type: 'restore', patient: p })} onPermanentDelete={(p) => setSecurityContext({ type: 'hard-delete', patient: p })} />;
      default: return null;
    }
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 bg-[radial-gradient(circle_at_top_right,_var(--tw-gradient-stops))] from-teal-50 via-slate-50 to-slate-100">
        <div className="w-full max-w-md">
          <div className="text-center mb-12">
            <div className="bg-white p-6 rounded-[2.5rem] shadow-2xl inline-block mb-6 border border-slate-100">
               <OpusLogo size="md" />
            </div>
            <h1 className="text-4xl font-black text-slate-900 tracking-tighter italic">OPUS</h1>
            <p className="text-slate-400 font-bold uppercase tracking-[0.4em] text-[10px] mt-2">Surgical Asset Repository</p>
          </div>

          <div className="bg-white/90 backdrop-blur-xl border border-white rounded-[3rem] p-10 shadow-2xl space-y-8">
            {!isLinked ? (
              <div className="space-y-6">
                <p className="text-center text-sm font-medium text-slate-500 mb-8 px-4 leading-relaxed">Securely link your clinical credentials to initialize the Longitudinal Repository.</p>
                <button 
                  onClick={handleGoogleAuth}
                  className="w-full flex items-center justify-center gap-4 bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-base hover:bg-slate-800 transition-all active:scale-[0.98] shadow-2xl"
                >
                  <img src="https://www.google.com/favicon.ico" className="w-5 h-5" alt="" />
                  Continue with Institutional ID
                </button>
              </div>
            ) : (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-6 duration-700 text-center">
                <div className="relative inline-block">
                  <img src={user?.avatar} className="w-24 h-24 rounded-[2rem] shadow-xl border-4 border-white mx-auto mb-4" alt="User" />
                  <div className="absolute -bottom-1 -right-1 bg-teal-500 text-white p-1.5 rounded-full border-4 border-white">
                    <CheckCircle2 size={16} />
                  </div>
                </div>
                <div className="space-y-1">
                  <h2 className="text-2xl font-black text-slate-900 tracking-tight">{user?.name}</h2>
                  <p className="text-[11px] font-bold text-slate-400 uppercase tracking-[0.2em]">{user?.email}</p>
                </div>

                <button 
                  onClick={handleBiometricLogin}
                  className="w-full bg-teal-600 text-white py-5 rounded-[1.5rem] font-bold text-base shadow-2xl hover:bg-teal-700 transition-all flex items-center justify-center gap-3 group"
                >
                  <Fingerprint size={28} className="group-hover:scale-110 transition-transform" />
                  Biometric Unlock
                </button>
              </div>
            )}
          </div>
          <p className="text-center mt-12 text-[9px] text-slate-300 font-black uppercase tracking-[0.6em]">HIPAA COMPLIANT • MASTER REPOSITORY</p>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 selection:bg-teal-100">
      <Sidebar 
        activeView={activeView} 
        setActiveView={v => { setActiveView(v); setSelectedPatient(null); }} 
        onLogout={() => {setIsLoggedIn(false); setIsLinked(false); setUser(null);}} 
        isOpen={isSidebarOpen} 
        setIsOpen={setIsSidebarOpen}
        deletedCount={deletedPatients.length}
      />

      <main className="flex-1 lg:ml-64 min-h-screen transition-all">
        <header className="px-10 py-4 bg-white/80 border-b border-slate-100 sticky top-0 z-[100] backdrop-blur-md flex items-center justify-between">
          <div className="flex items-center gap-4">
             <div className="lg:hidden"><OpusLogo size="sm" /></div>
             <span className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em]">{activeView}</span>
          </div>
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3 bg-slate-100/50 px-4 py-2 rounded-2xl border border-slate-100">
               <img src={user?.avatar} className="w-6 h-6 rounded-full" alt="" />
               <span className="text-[12px] font-black text-slate-700">{user?.name.split(' ').pop()}</span>
            </div>
            <button onClick={() => setIsSidebarOpen(true)} className="lg:hidden p-2 text-slate-400"><Menu size={22} /></button>
          </div>
        </header>

        <div className="px-10 py-10 max-w-7xl mx-auto w-full">
          {renderView()}
        </div>
      </main>

      {/* Expanded Clinical Data Edit Modal */}
      {patientToEdit && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[300] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-lg rounded-[2.5rem] shadow-2xl p-10 animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-900 italic">Clinical Record Correction</h2>
              <button onClick={() => setPatientToEdit(null)} className="text-slate-400 hover:text-slate-900 transition-colors p-2"><X size={24} /></button>
            </div>
            <form onSubmit={(e) => { e.preventDefault(); if (patientToEdit) handleUpdatePatient(patientToEdit); }} className="space-y-6">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">UHID</label>
                  <input value={patientToEdit.uhid} onChange={e => setPatientToEdit({...patientToEdit, uhid: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Lead Surgeon</label>
                  <input value={patientToEdit.primarySurgeon} onChange={e => setPatientToEdit({...patientToEdit, primarySurgeon: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Patient Identity</label>
                <input value={patientToEdit.name} onChange={e => setPatientToEdit({...patientToEdit, name: e.target.value})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Age (Years)</label>
                  <input type="number" value={patientToEdit.ageYears} onChange={e => setPatientToEdit({...patientToEdit, ageYears: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Age (Months)</label>
                  <input type="number" value={patientToEdit.ageMonths || 0} onChange={e => setPatientToEdit({...patientToEdit, ageMonths: parseInt(e.target.value) || 0})} className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm focus:ring-4 focus:ring-teal-500/10 transition-all outline-none" />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Primary Diagnosis</label>
                <textarea 
                  value={patientToEdit.diagnosis} 
                  onChange={e => setPatientToEdit({...patientToEdit, diagnosis: e.target.value})} 
                  className="w-full px-5 py-4 bg-slate-50 rounded-2xl border border-slate-100 font-bold text-sm h-32 resize-none focus:ring-4 focus:ring-teal-500/10 transition-all outline-none"
                />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-[1.5rem] font-bold text-xs uppercase tracking-[0.3em] shadow-2xl active:scale-95 transition-all">Synchronize Vault Changes</button>
            </form>
          </div>
        </div>
      )}

      {/* Security Verification Modal */}
      {securityContext && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[500] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-[2.5rem] shadow-2xl p-8 animate-in zoom-in-95 text-center space-y-6">
            <div className="mx-auto w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center text-teal-600 shadow-inner">
              {isVerifying ? <div className="w-6 h-6 border-4 border-teal-600/20 border-t-teal-600 rounded-full animate-spin" /> : <KeyRound size={32} className="animate-pulse" />}
            </div>
            <div className="space-y-2">
              <h2 className="text-sm font-black text-slate-900 uppercase tracking-[0.2em]">Security Checkpoint</h2>
              <p className="text-[11px] text-slate-400 uppercase font-bold tracking-widest">Confirm identity for clinical {securityContext.type}</p>
            </div>
            <input 
              type="password" 
              placeholder="System Vault Key"
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl text-base font-bold outline-none text-center focus:ring-4 focus:ring-teal-500/10 transition-all"
              value={verificationInput}
              onChange={(e) => setVerificationInput(e.target.value)}
              autoFocus
            />
            <div className="flex gap-4">
              <button onClick={() => setSecurityContext(null)} className="flex-1 text-[11px] font-black uppercase tracking-widest text-slate-400 py-3">Abort</button>
              <button onClick={processSecurityAction} className="flex-1 bg-slate-900 text-white py-3 rounded-2xl text-[11px] font-black uppercase tracking-widest shadow-xl">Authorize</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, Plus, User, Calendar, X } from 'lucide-react';
import { Patient, SurgeryEvent } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Initial Consultation', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700 max-w-7xl mx-auto">
      <div className="flex justify-between items-end px-2">
        <div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight italic">Clinical Registry</h1>
          <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.4em] mt-2">Precision Longitudinal Asset Management</p>
        </div>
        <button onClick={() => setShowModal(true)} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl hover:bg-slate-800 transition-all active:scale-95">
          <Plus size={20} /> Register New Patient
        </button>
      </div>

      <div className="relative max-w-3xl mx-auto">
        <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300">
           <Search size={24} />
        </div>
        <input 
          type="text" placeholder="Filter patient records by Identity, UHID, or Clinical Diagnosis..."
          className="w-full pl-16 pr-8 py-5 bg-white border border-slate-100 rounded-[2.5rem] outline-none focus:ring-8 focus:ring-teal-500/5 transition-all text-base font-medium shadow-xl placeholder:text-slate-300"
          value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
        {filtered.map(p => (
          <div key={p.uhid} onClick={() => onSelectPatient(p)} className="bg-white p-8 rounded-[3rem] border border-slate-100 hover:border-teal-500 hover:shadow-[0_20px_50px_rgba(13,148,136,0.1)] hover:-translate-y-2 transition-all cursor-pointer shadow-sm group">
            <div className="flex justify-between items-start mb-6">
              <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center text-slate-300 group-hover:text-teal-600 group-hover:bg-teal-50 transition-all shadow-inner">
                <User size={28} />
              </div>
              <span className="font-mono text-[11px] font-black text-slate-400 bg-slate-100 px-3 py-1.5 rounded-xl border border-slate-100">{p.uhid}</span>
            </div>
            <h3 className="font-black text-slate-900 text-xl truncate group-hover:text-teal-700 transition-colors mb-1.5">{p.name}</h3>
            <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.2em] mb-5">
               {p.ageYears}y {p.ageYears <= 2 ? `${p.ageMonths || 0}m` : ''} • {p.primarySurgeon}
            </p>
            <div className="bg-slate-50/80 p-5 rounded-2xl mb-6 min-h-[70px] flex items-center border border-slate-100">
              <p className="text-slate-600 text-[12px] font-medium leading-relaxed italic line-clamp-2">"{p.diagnosis}"</p>
            </div>
            <div className="flex justify-between items-center border-t border-slate-50 pt-5">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                <Calendar size={16} className="text-teal-600" /> {p.dateOfSurgery || 'Initial Registry'}
              </span>
              <div className="flex gap-2">
                 {p.studyGroupIds.map(id => (
                   <span key={id} className="text-[9px] font-black text-teal-600 uppercase bg-teal-50 px-3 py-1 rounded-xl border border-teal-100">{id}</span>
                 ))}
              </div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[3rem] shadow-2xl animate-in zoom-in-95 overflow-hidden p-10 space-y-8">
            <div className="flex justify-between items-center">
              <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic">Registry Initialization</h2>
              <button onClick={() => setShowModal(false)} className="text-slate-300 hover:text-slate-900 transition-colors p-2"><X size={28} /></button>
            </div>
            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">UHID</label>
                  <input required placeholder="HOSP-XXXX" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Lead Surgeon</label>
                  <input required placeholder="Lead Surgeon" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/10" value={newPatient.primarySurgeon} onChange={e => setNewPatient({...newPatient, primarySurgeon: e.target.value})} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Patient Full Name</label>
                <input required placeholder="Patient Identity" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Age (Y)</label>
                  <input type="number" placeholder="Years" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
                </div>
                <div className="space-y-1.5">
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Registry Date</label>
                  <input type="date" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none focus:ring-4 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, dateOfSurgery: e.target.value})} />
                </div>
              </div>
              <div className="space-y-1.5">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-1">Initial Diagnosis</label>
                <textarea required placeholder="Brief clinical findings..." className="w-full px-5 py-4 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 h-28 resize-none outline-none focus:ring-4 focus:ring-teal-500/10" onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              </div>
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-[1.5rem] text-xs uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all mt-4">Commit to Longitudinal Vault</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { ArrowLeft, Download, X, Edit, HardDrive, PlayCircle, Trash2, FileText, Plus, Music, Volume2 } from 'lucide-react';
import { Patient, SurgicalStage, MediaType, MediaEntry } from '../types';
import { MOCK_MEDIA } from '../constants';

interface PatientDetailsProps {
  patient: Patient;
  onBack: () => void;
  onAddMedia: () => void;
  onUpdatePatient: (updatedPatient: Patient) => void;
  onEditPatient: (patient: Patient) => void;
  onDeletePatient: (patient: Patient) => void;
  studyGroups: any[];
}

const PatientDetails: React.FC<PatientDetailsProps> = ({ 
  patient, onBack, onAddMedia, onUpdatePatient, onEditPatient, onDeletePatient 
}) => {
  const [activeSurgeryId, setActiveSurgeryId] = useState<string>(patient.surgeries[0]?.id || '');
  const [activeStage, setActiveStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [playingVideoId, setPlayingVideoId] = useState<string | null>(null);
  const [playingAudioId, setPlayingAudioId] = useState<string | null>(null);
  const [downloadModalMedia, setDownloadModalMedia] = useState<MediaEntry | null>(null);
  const [downloadFormat, setDownloadFormat] = useState<string>('');

  const currentSurgery = patient.surgeries.find(s => s.id === activeSurgeryId);
  const filteredMedia = [...MOCK_MEDIA].filter(m => m.uhid === patient.uhid && m.surgeryId === activeSurgeryId && m.stage === activeStage);

  const handleDownloadInit = (media: MediaEntry) => {
    setDownloadModalMedia(media);
    if (media.type === MediaType.VIDEO) setDownloadFormat('MP4');
    else if (media.type === MediaType.AUDIO) setDownloadFormat('MP3');
    else setDownloadFormat('JPG');
  };

  const handleFinalDownload = () => {
    if (!downloadModalMedia) return;
    const a = document.createElement('a');
    a.href = downloadModalMedia.url;
    a.download = `HQ_${patient.uhid}_${downloadModalMedia.stage}_${Date.now()}.${downloadFormat.toLowerCase()}`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setDownloadModalMedia(null);
  };

  return (
    <div className="space-y-8 max-w-7xl mx-auto animate-in fade-in duration-700">
      <div className="flex justify-between items-center px-2">
        <button onClick={onBack} className="text-[11px] font-black text-slate-400 uppercase tracking-[0.3em] hover:text-slate-900 transition-colors flex items-center gap-2 group">
          <ArrowLeft size={18} className="group-hover:-translate-x-1 transition-transform" /> Registry Dashboard
        </button>
        <button onClick={onAddMedia} className="bg-teal-600 text-white px-8 py-3 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl hover:bg-teal-700 transition-all active:scale-95 flex items-center gap-3">
          <Plus size={20} /> New Intake Session
        </button>
      </div>

      <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-start md:items-center gap-8">
        <div className="flex gap-6 items-center">
          <div className="w-20 h-20 bg-teal-600 text-white rounded-[2rem] flex items-center justify-center font-black text-2xl shadow-xl">{patient.name.charAt(0)}</div>
          <div>
            <div className="flex items-center gap-4">
              <h1 className="text-3xl font-black text-slate-900 tracking-tight italic">{patient.name}</h1>
              <span className="text-[11px] font-mono font-black text-slate-400 bg-slate-100 px-3 py-1 rounded-xl border border-slate-100">{patient.uhid}</span>
            </div>
            <p className="text-slate-400 text-[12px] font-bold uppercase tracking-[0.3em] mt-2">
              {patient.ageYears}y {patient.ageYears <= 2 ? `${patient.ageMonths}m` : ''} • {patient.primarySurgeon}
            </p>
          </div>
        </div>
        <div className="flex-1 max-w-2xl bg-slate-50/50 px-8 py-4 rounded-[1.5rem] border border-slate-100 flex items-center gap-5 shadow-inner">
          <HardDrive size={24} className="text-teal-600 shrink-0" />
          <p className="text-sm text-slate-600 italic leading-relaxed font-medium">{patient.diagnosis}</p>
        </div>
        <div className="flex gap-3">
          <button onClick={() => onEditPatient(patient)} className="p-4 bg-white text-slate-400 rounded-2xl border border-slate-100 hover:text-teal-600 hover:border-teal-100 transition-all shadow-sm"><Edit size={24} /></button>
          <button onClick={() => onDeletePatient(patient)} className="p-4 bg-white text-slate-400 hover:text-red-500 hover:border-red-100 rounded-2xl border border-slate-100 transition-all shadow-sm"><Trash2 size={24} /></button>
        </div>
      </div>

      <div className="flex gap-3 overflow-x-auto pb-4 no-scrollbar scroll-smooth px-1">
        {patient.surgeries.map(s => (
          <button 
            key={s.id} onClick={() => setActiveSurgeryId(s.id)}
            className={`flex-shrink-0 px-8 py-4 rounded-3xl border text-[11px] font-black uppercase tracking-[0.2em] transition-all ${activeSurgeryId === s.id ? 'bg-slate-900 text-white border-slate-900 shadow-2xl scale-105 z-10' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
          >
            {s.title}
          </button>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        {/* Left Column: Larger Media Grid */}
        <div className="lg:col-span-8 bg-white rounded-[3rem] border border-slate-100 shadow-sm overflow-hidden flex flex-col h-fit">
          <div className="flex bg-slate-50 p-2.5 gap-2.5">
            {Object.values(SurgicalStage).map(stage => (
              <button key={stage} onClick={() => setActiveStage(stage)} className={`flex-1 py-4 text-[11px] font-black uppercase tracking-widest transition-all rounded-2xl ${activeStage === stage ? 'text-teal-600 bg-white shadow-xl' : 'text-slate-400 hover:text-slate-600'}`}>
                {stage}
              </button>
            ))}
          </div>
          <div className="p-8">
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-6">
              {filteredMedia.map(m => (
                <div key={m.id} className="group relative aspect-video sm:aspect-square rounded-[2rem] overflow-hidden border border-slate-100 bg-slate-100 shadow-md flex items-center justify-center">
                  {m.type === MediaType.VIDEO && playingVideoId === m.id ? (
                    <video src={m.url} autoPlay controls className="w-full h-full object-cover" />
                  ) : m.type === MediaType.AUDIO ? (
                    <div className="flex flex-col items-center gap-4 p-8 w-full text-center">
                       <div className="p-5 bg-teal-50 text-teal-600 rounded-[1.5rem] shadow-inner"><Volume2 size={40} /></div>
                       <p className="text-[11px] font-black text-slate-400 uppercase tracking-widest leading-relaxed line-clamp-2">{m.notes || 'Audio Record'}</p>
                       {playingAudioId === m.id && <audio src={m.url} autoPlay controls className="w-full h-10 mt-3" />}
                       <button onClick={() => setPlayingAudioId(m.id === playingAudioId ? null : m.id)} className="px-6 py-2 bg-slate-100 text-[10px] font-black uppercase tracking-[0.3em] text-slate-600 rounded-full hover:bg-slate-200 transition-all shadow-sm">
                          {playingAudioId === m.id ? 'Stop Stream' : 'Play Asset'}
                       </button>
                    </div>
                  ) : (
                    <>
                      <img src={m.thumbnailUrl || m.url} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000" />
                      {m.type === MediaType.VIDEO && (
                        <div className="absolute inset-0 flex items-center justify-center cursor-pointer" onClick={() => setPlayingVideoId(m.id)}>
                          <div className="bg-black/20 backdrop-blur-md p-5 rounded-full text-white shadow-2xl scale-100 group-hover:scale-110 transition-transform"><PlayCircle size={36} /></div>
                        </div>
                      )}
                    </>
                  )}
                  {/* Download Overlay */}
                  <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-all translate-y-2 group-hover:translate-y-0">
                     <button onClick={() => handleDownloadInit(m)} className="p-3 bg-white/70 backdrop-blur-2xl rounded-2xl text-slate-900 hover:bg-teal-600 hover:text-white transition-all shadow-2xl" title="High Fidelity Download"><Download size={20} /></button>
                  </div>
                </div>
              ))}
              {filteredMedia.length === 0 && (
                <div className="col-span-full py-24 text-center space-y-4">
                  <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto text-slate-200 shadow-inner"><FileText size={48} /></div>
                  <p className="text-slate-300 font-black uppercase tracking-[0.4em] text-[11px] italic">No longitudinal assets in this segment</p>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Right Column: Operative Notes */}
        <div className="lg:col-span-4 space-y-8">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm h-full flex flex-col">
            <div className="flex items-center gap-4 mb-8">
              <div className="p-3 bg-teal-50 text-teal-600 rounded-2xl shadow-sm border border-teal-100"><FileText size={24} /></div>
              <h3 className="text-[12px] font-black uppercase tracking-[0.4em] text-slate-900 italic">Operative (OT) Findings</h3>
            </div>

            <div className="bg-slate-50/80 p-8 rounded-[2rem] border border-slate-100 flex-1 min-h-[300px] relative overflow-hidden group">
               <div className="absolute -top-10 -right-10 p-4 opacity-5 group-hover:opacity-10 transition-opacity"><FileText size={160} /></div>
               {currentSurgery?.otNotes ? (
                 <p className="text-base text-slate-600 leading-relaxed font-medium whitespace-pre-wrap relative z-10">{currentSurgery.otNotes}</p>
               ) : (
                 <div className="flex flex-col items-center justify-center h-full text-slate-300 py-12 relative z-10">
                    <p className="text-[11px] font-black uppercase tracking-[0.3em]">No operative data recorded</p>
                    <button className="mt-6 text-[10px] font-black text-teal-600 underline uppercase tracking-widest hover:text-teal-800">Initialize Post-Op Report</button>
                 </div>
               )}
            </div>
            {currentSurgery && (
              <div className="mt-8 pt-8 border-t border-slate-100 flex justify-between items-center text-[11px] font-black uppercase tracking-[0.3em]">
                <span className="text-slate-400">Vault Timestamp</span>
                <span className="text-teal-600">{currentSurgery.date}</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* HQ Format Selection Modal */}
      {downloadModalMedia && (
        <div className="fixed inset-0 bg-slate-900/70 backdrop-blur-xl z-[400] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-md rounded-[3rem] shadow-2xl p-12 animate-in zoom-in-95 text-center space-y-10">
            <div className="mx-auto w-20 h-20 bg-teal-50 text-teal-600 rounded-[2rem] flex items-center justify-center shadow-xl">
              <Download size={40} />
            </div>
            <div className="space-y-3">
              <h2 className="text-2xl font-black text-slate-900 tracking-tight italic">HQ Asset Export</h2>
              <p className="text-sm text-slate-500 font-medium leading-relaxed px-8">Select the master clinical format for high-fidelity offline archival.</p>
            </div>

            <div className="space-y-6">
              <p className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-300">Format Matrix</p>
              <div className="grid grid-cols-2 gap-4">
                {downloadModalMedia.type === MediaType.IMAGE ? (
                  ['JPG', 'PNG', 'WEBP', 'TIFF'].map(f => (
                    <button key={f} onClick={() => setDownloadFormat(f)} className={`py-4 rounded-[1.2rem] text-sm font-black transition-all ${downloadFormat === f ? 'bg-slate-900 text-white shadow-2xl scale-110' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                  ))
                ) : downloadModalMedia.type === MediaType.VIDEO ? (
                  ['MP4', 'MOV', 'AVI', 'MKV'].map(f => (
                    <button key={f} onClick={() => setDownloadFormat(f)} className={`py-4 rounded-[1.2rem] text-sm font-black transition-all ${downloadFormat === f ? 'bg-slate-900 text-white shadow-2xl scale-110' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                  ))
                ) : (
                  ['MP3', 'WAV', 'AAC', 'FLAC'].map(f => (
                    <button key={f} onClick={() => setDownloadFormat(f)} className={`py-4 rounded-[1.2rem] text-sm font-black transition-all ${downloadFormat === f ? 'bg-slate-900 text-white shadow-2xl scale-110' : 'bg-slate-50 text-slate-400 hover:bg-slate-100'}`}>{f}</button>
                  ))
                )}
              </div>
            </div>

            <div className="flex gap-6 pt-6 border-t border-slate-100">
              <button onClick={() => setDownloadModalMedia(null)} className="flex-1 py-4 text-[11px] font-black uppercase tracking-[0.3em] text-slate-400 hover:text-slate-900 transition-colors">Cancel</button>
              <button onClick={handleFinalDownload} className="flex-1 bg-teal-600 text-white py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-[0.3em] shadow-2xl hover:bg-teal-700 transition-all active:scale-95">Download Master</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

