import React, { useState } from 'react';
import { Camera, Database, CheckCircle2, Trash2, PlayCircle, CloudUpload, FileText, Plus, Music } from 'lucide-react';
import { Patient, SurgicalStage, StorageLocation, StudyGroup } from '../types';

interface UploadMediaProps {
  patients: Patient[];
  onUpload: (media: any) => void;
  studyGroups: StudyGroup[];
}

interface PreviewFile {
  url: string;
  file: File;
  type: 'image' | 'video' | 'audio';
}

const UploadMedia: React.FC<UploadMediaProps> = ({ patients, onUpload, studyGroups }) => {
  const [selectedPatientId, setSelectedPatientId] = useState('');
  const [stage, setStage] = useState<SurgicalStage>(SurgicalStage.PRE_OP);
  const [surgeryId, setSurgeryId] = useState('');
  const [newSurgeryTitle, setNewSurgeryTitle] = useState('');
  const [newSurgeryDate, setNewSurgeryDate] = useState('');
  const [otNotes, setOtNotes] = useState('');
  const [showNewSurgeryForm, setShowNewSurgeryForm] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState('');
  const [notes, setNotes] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [previewFiles, setPreviewFiles] = useState<PreviewFile[]>([]);
  const [showSuccess, setShowSuccess] = useState(false);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files: File[] = Array.from(e.target.files);
      const processedFiles = files.map((file): PreviewFile => {
        let type: 'image' | 'video' | 'audio' = 'image';
        if (file.type.startsWith('video/')) type = 'video';
        else if (file.type.startsWith('audio/')) type = 'audio';
        return { url: URL.createObjectURL(file), file, type };
      });
      setPreviewFiles(prev => [...prev, ...processedFiles]);
    }
  };

  const removeFile = (index: number) => {
    setPreviewFiles(prev => {
      const fileToRemove = prev[index];
      if (fileToRemove.url) URL.revokeObjectURL(fileToRemove.url);
      return prev.filter((_, i) => i !== index);
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedPatientId || previewFiles.length === 0) return;

    if (!surgeryId && !showNewSurgeryForm) {
      alert("Registration requires a specific procedure event link.");
      return;
    }

    setIsUploading(true);
    setTimeout(() => {
      onUpload({
        uhid: selectedPatientId, 
        stage, 
        surgeryId: showNewSurgeryForm ? `surg_${Date.now()}` : surgeryId,
        newSurgery: showNewSurgeryForm ? { title: newSurgeryTitle, date: newSurgeryDate, otNotes: otNotes } : null,
        otNotes: otNotes,
        storage: StorageLocation.GOOGLE_DRIVE,
        studyGroup: selectedGroup, 
        notes,
        timestamp: new Date().toISOString(),
        mediaCount: previewFiles.length
      });
      setIsUploading(false);
      setShowSuccess(true);
      setPreviewFiles([]);
    }, 1500);
  };

  if (showSuccess) {
    return (
      <div className="max-w-lg mx-auto py-24 text-center space-y-10 animate-in zoom-in-95">
        <div className="w-24 h-24 bg-teal-50 text-teal-600 rounded-[2.5rem] flex items-center justify-center mx-auto shadow-2xl border border-teal-100">
          <CheckCircle2 size={48} />
        </div>
        <div className="space-y-3">
          <h2 className="text-3xl font-black text-slate-900 tracking-tight italic">Assets Committed</h2>
          <p className="text-slate-400 font-bold text-[12px] uppercase tracking-[0.4em]">Securely Synchronized to Longitudinal Vault</p>
        </div>
        <button onClick={() => setShowSuccess(false)} className="w-full bg-teal-600 text-white font-black py-5 rounded-[1.5rem] shadow-2xl text-sm uppercase tracking-[0.3em] transition-transform active:scale-95 hover:bg-teal-700">
          Initialize New Intake Session
        </button>
      </div>
    );
  }

  const selectedPatient = patients.find(p => p.uhid === selectedPatientId);

  return (
    <div className="space-y-10 max-w-7xl mx-auto">
      <div className="flex justify-between items-end px-2">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight italic">Intake Portal</h1>
          <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.4em] mt-2">High-Entropy Clinical Data Synchronization</p>
        </div>
      </div>

      <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-10">
        <div className="lg:col-span-5 space-y-8">
          <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm space-y-8">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-300 flex items-center gap-3 italic">
              <Database size={18} /> Master Metadata
            </h2>

            <div className="space-y-2.5">
              <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">Select Patient *</label>
              <select className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-[1.5rem] font-bold text-slate-900 text-sm focus:ring-8 focus:ring-teal-500/5 outline-none transition-all" value={selectedPatientId} onChange={e => { setSelectedPatientId(e.target.value); setSurgeryId(''); setShowNewSurgeryForm(false); }} required>
                <option value="">Query master registry...</option>
                {patients.map(p => <option key={p.uhid} value={p.uhid}>{p.name} ({p.uhid})</option>)}
              </select>
            </div>

            {selectedPatient && (
              <div className="space-y-8 animate-in fade-in duration-700">
                <div className="space-y-3">
                  <div className="flex justify-between items-center px-1">
                    <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em]">Procedure Link</label>
                    <button type="button" onClick={() => setShowNewSurgeryForm(!showNewSurgeryForm)} className="text-[11px] font-black text-teal-600 uppercase flex items-center gap-2 hover:underline tracking-widest">
                      {showNewSurgeryForm ? 'Query Existing' : <><Plus size={16} /> Register Event</>}
                    </button>
                  </div>
                  {!showNewSurgeryForm ? (
                    <select className="w-full px-5 py-4 bg-slate-50 border border-slate-100 rounded-[1.5rem] font-bold text-slate-900 text-sm outline-none focus:ring-8 focus:ring-teal-500/5" value={surgeryId} onChange={e => setSurgeryId(e.target.value)} required>
                      <option value="">Select Target Procedure...</option>
                      {selectedPatient.surgeries.map(s => <option key={s.id} value={s.id}>{s.title} ({s.date})</option>)}
                    </select>
                  ) : (
                    <div className="space-y-4 p-6 bg-teal-50/20 rounded-[2rem] border border-teal-100/30">
                       <input required placeholder="Procedure Title (e.g. Tendon Transfer)" className="w-full px-5 py-3.5 text-sm font-bold rounded-2xl border border-teal-100/50 outline-none focus:bg-white transition-all" value={newSurgeryTitle} onChange={e => setNewSurgeryTitle(e.target.value)} />
                       <input required type="date" className="w-full px-5 py-3.5 text-sm font-bold rounded-2xl border border-teal-100/50 outline-none focus:bg-white transition-all" value={newSurgeryDate} onChange={e => setNewSurgeryDate(e.target.value)} />
                    </div>
                  )}
                </div>

                <div className="space-y-3">
                  <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] px-1">Clinical Phase</label>
                  <div className="grid grid-cols-1 gap-2.5">
                    {Object.values(SurgicalStage).map(s => (
                      <button key={s} type="button" onClick={() => setStage(s)} className={`px-5 py-4 rounded-[1.2rem] border text-[11px] font-black uppercase tracking-widest text-left flex justify-between items-center transition-all ${stage === s ? 'border-teal-500 bg-teal-50 text-teal-700 shadow-xl scale-[1.02]' : 'border-slate-100 text-slate-400 bg-slate-50/50 hover:bg-slate-100'}`}>
                        {s}{stage === s && <CheckCircle2 size={18} />}
                      </button>
                    ))}
                  </div>
                </div>

                <div className="space-y-3">
                  <label className="block text-[11px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center gap-2 px-1"><FileText size={16} className="text-teal-600" /> Operative (OT) Report</label>
                  <textarea value={otNotes} onChange={e => setOtNotes(e.target.value)} className="w-full px-6 py-5 bg-slate-50 border border-slate-100 rounded-[2rem] h-40 font-bold text-sm outline-none focus:ring-8 focus:ring-teal-500/5 resize-none transition-all leading-relaxed" placeholder="Detailed surgical anatomy, procedure steps, and immediate intra-operative findings..." />
                </div>
              </div>
            )}
          </div>
        </div>

        <div className="lg:col-span-7 space-y-8">
          <div className="bg-white p-10 rounded-[3.5rem] border border-slate-100 shadow-sm space-y-8 h-full flex flex-col">
            <h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-300 italic">HQ Asset Integration</h2>

            <div className="group relative p-12 border-4 border-dashed border-slate-100 rounded-[3rem] bg-slate-50/30 hover:bg-white hover:border-teal-300 transition-all flex flex-col items-center justify-center text-center cursor-pointer flex-1 min-h-[350px] shadow-inner">
              <input type="file" multiple accept="image/*,video/*,audio/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleFileChange} />
              <div className="p-8 bg-white rounded-[2.5rem] shadow-2xl text-slate-200 mb-6 group-hover:text-teal-600 group-hover:scale-110 transition-all flex gap-5 border border-slate-50">
                <Camera size={48} />
                <Music size={48} />
              </div>
              <p className="text-2xl font-black text-slate-900 tracking-tight">Synchronize Master Assets</p>
              <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.4em] mt-3">All Master Formats Accepted • High-Fidelity Capture</p>
            </div>

            {previewFiles.length > 0 && (
              <div className="grid grid-cols-4 sm:grid-cols-6 gap-4 px-2">
                {previewFiles.map((fileData, i) => (
                  <div key={i} className="group relative aspect-square rounded-[1.5rem] overflow-hidden border border-slate-100 bg-slate-50 flex items-center justify-center shadow-lg hover:shadow-xl transition-all">
                    {fileData.type === 'image' && <img src={fileData.url} className="w-full h-full object-cover" />}
                    {fileData.type === 'video' && <div className="text-slate-400 flex flex-col items-center gap-2"><PlayCircle size={32} /><span className="text-[9px] font-black uppercase tracking-widest">Video</span></div>}
                    {fileData.type === 'audio' && <div className="text-slate-400 flex flex-col items-center gap-2"><Music size={32} /><span className="text-[9px] font-black uppercase tracking-widest">Audio</span></div>}
                    <button type="button" onClick={() => removeFile(i)} className="absolute top-2 right-2 p-2 bg-black/60 text-white rounded-xl opacity-0 group-hover:opacity-100 transition-all hover:bg-red-500 shadow-2xl">
                      <Trash2 size={16} />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <button 
              type="submit" 
              disabled={isUploading || previewFiles.length === 0 || !selectedPatientId} 
              className="w-full bg-slate-900 text-white font-black py-6 rounded-[2rem] shadow-[0_25px_50px_rgba(0,0,0,0.2)] flex items-center justify-center gap-4 text-[13px] uppercase tracking-[0.4em] mt-auto active:scale-95 transition-all disabled:opacity-20 disabled:cursor-not-allowed group border-t border-white/10"
            >
              {isUploading ? <div className="w-5 h-5 border-4 border-white/20 border-t-white rounded-full animate-spin" /> : <CloudUpload size={28} className="group-hover:-translate-y-1 transition-transform" />}
              Commit Master Vault Assets
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default UploadMedia;

import React from 'react';
