import React, { useState } from 'react';
import { Search, Plus, User, Calendar, X } from 'lucide-react';
import { Patient, SurgeryEvent } from '../types';

interface DashboardProps {
  patients: Patient[];
  studyGroups: any[];
  onAddPatient: (patient: Patient) => void;
  onSelectPatient: (patient: Patient) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ patients, onAddPatient, onSelectPatient }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showModal, setShowModal] = useState(false);
  const [newPatient, setNewPatient] = useState<Partial<Patient>>({
    uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: ''
  });

  const filtered = patients.filter(p => 
    p.uhid.toLowerCase().includes(searchTerm.toLowerCase()) || p.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newPatient.uhid || !newPatient.name) return;
    const surgeries: SurgeryEvent[] = newPatient.dateOfSurgery ? [{
      id: `surg_${Date.now()}`, title: 'Initial Consultation', date: newPatient.dateOfSurgery
    }] : [];

    onAddPatient({
      ...newPatient as Patient,
      createdAt: new Date().toISOString().split('T')[0],
      surgeries
    });
    setShowModal(false);
    setNewPatient({ uhid: '', name: '', ageYears: 0, ageMonths: 0, diagnosis: '', primarySurgeon: 'Dr. Alexander Smith', studyGroupIds: [], dateOfSurgery: '' });
  };

  return (
    <div className="space-y-10 animate-in fade-in duration-700 max-w-7xl mx-auto">
      <div className="flex justify-between items-end px-2">
        <div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight italic">Clinical Registry</h1>
          <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.4em] mt-2">Precision Longitudinal Asset Management</p>
        </div>
        <button onClick={() => setShowModal(true)} className="flex items-center gap-3 bg-slate-900 text-white px-8 py-4 rounded-[1.5rem] text-[11px] font-black uppercase tracking-widest shadow-2xl hover:bg-slate-800 transition-all active:scale-95">
          <Plus size={20} /> Register Record
        </button>
      </div>

      <div className="relative max-w-3xl mx-auto">
        <div className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300"><Search size={24} /></div>
        <input 
          type="text" placeholder="Filter patient records by Identity or UHID..."
          className="w-full pl-16 pr-8 py-5 bg-white border border-slate-100 rounded-[2.5rem] outline-none focus:ring-8 focus:ring-teal-500/5 transition-all text-base font-medium shadow-xl placeholder:text-slate-300"
          value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-8">
        {filtered.map(p => (
          <div key={p.uhid} onClick={() => onSelectPatient(p)} className="bg-white p-8 rounded-[3rem] border border-slate-100 hover:border-teal-500 hover:shadow-2xl hover:-translate-y-2 transition-all cursor-pointer shadow-sm group">
            <div className="flex justify-between items-start mb-6">
              <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center text-slate-300 group-hover:text-teal-600 group-hover:bg-teal-50 transition-all shadow-inner"><User size={28} /></div>
              <span className="font-mono text-[11px] font-black text-slate-400 bg-slate-100 px-3 py-1.5 rounded-xl border border-slate-100">{p.uhid}</span>
            </div>
            <h3 className="font-black text-slate-900 text-xl truncate group-hover:text-teal-700 transition-colors mb-1.5">{p.name}</h3>
            <p className="text-slate-400 text-[11px] font-bold uppercase tracking-[0.2em] mb-5">{p.ageYears}y • {p.primarySurgeon}</p>
            <div className="bg-slate-50/80 p-5 rounded-2xl mb-6 min-h-[70px] flex items-center border border-slate-100"><p className="text-slate-600 text-[12px] font-medium leading-relaxed italic line-clamp-2">"{p.diagnosis}"</p></div>
            <div className="flex justify-between items-center border-t border-slate-50 pt-5">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-2"><Calendar size={16} className="text-teal-600" /> {p.dateOfSurgery || 'Initial Registry'}</span>
              <div className="flex gap-2">{p.studyGroupIds.map(id => <span key={id} className="text-[9px] font-black text-teal-600 uppercase bg-teal-50 px-3 py-1 rounded-xl border border-teal-100">{id}</span>)}</div>
            </div>
          </div>
        ))}
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[200] flex items-center justify-center p-4">
          <div className="bg-white w-full max-w-sm rounded-[3rem] shadow-2xl p-10 space-y-8 animate-in zoom-in-95">
            <div className="flex justify-between items-center"><h2 className="text-[11px] font-black uppercase tracking-[0.4em] text-slate-900 italic">Registry Entry</h2><button onClick={() => setShowModal(false)} className="text-slate-300 hover:text-slate-900 transition-colors p-2"><X size={28} /></button></div>
            <form onSubmit={handleSubmit} className="space-y-4">
              <input required placeholder="UHID (e.g. HOSP-123)" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none" onChange={e => setNewPatient({...newPatient, uhid: e.target.value})} />
              <input required placeholder="Patient Full Name" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none" onChange={e => setNewPatient({...newPatient, name: e.target.value})} />
              <input type="number" placeholder="Age (Years)" className="w-full px-5 py-3.5 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 outline-none" onChange={e => setNewPatient({...newPatient, ageYears: parseInt(e.target.value) || 0})} />
              <textarea required placeholder="Clinical Diagnosis" className="w-full px-5 py-4 bg-slate-50 rounded-2xl text-sm font-bold border border-slate-100 h-28 resize-none outline-none" onChange={e => setNewPatient({...newPatient, diagnosis: e.target.value})} />
              <button type="submit" className="w-full bg-slate-900 text-white font-black py-5 rounded-[1.5rem] text-xs uppercase tracking-[0.4em] shadow-2xl active:scale-95 transition-all">Register with Vault</button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

